(window.GIM_TS=window.GIM_TS||{})["Menachot.0"]={"from":0,"a":[["כאשר מביא אדם מנחה למקדש, הכהן קומץ חלק ממנה בידו, מניחו בכלי שרת מוליכו למזבח ומקטירו, ומאותה שעה הותרו השיריים באכילה לכהנים, והבעלים יצאו ידי חובתם. וביחס לכך אומרת המשנה: \u0003כל המנחות שנקמצו שלא לשמן\u0004 שהכהן קמץ ממנחה אחת לשם סוג אחר של מנחה, וכגון שקמץ ממנחה הנעשית בתנור (ויקרא ב, ד) לשם מנחה הנעשית במחבת (שם ה) — \u0003כשירות\u0004 להקרבה, \u0003אלא שלא עלו לבעלים לשם חובה\u0004 שהיתה מוטלת עליהם באותה מנחה, ולשם כך הם צריכים להביא מנחה אחרת. \u0003חוץ ממנחת חוטא ומנחת קנאות\u0004 (מנחת הסוטה) שאם קמצן שלא לשמן — פסולות לגמרי.","\u0003מנחת חוטא ומנחת קנאות שקמצן שלא לשמן,\u0004 או \u0003נתן\u0004 את הקומץ \u0003בכלי\u0004 שלא לשמן, או \u0003הלך\u0004 (הוליך) את הכלי ובו הקומץ, \u0003ו\u0004כן אם \u0003הקטיר\u0004 את הקומץ \u0003שלא לשמן, או\u0004 אפילו עשה זאת בתחילתו \u0003לשמן ו\u0004בסופו \u0003שלא לשמן, או שלא לשמן ולשמן\u0004 — הרי הם \u0003פסולות.\u0004","\u0003כיצד\u0004 הוא \u0003לשמן ושלא לשמן?\u0004 כגון שקומץ \u0003לשם מנחת חוטא ולשם\u0004 \u0003מנחת\u0004 \u0003נדבה, שלא לשמן ולשמן\u0004 — שקומץ \u0003לשם מנחת נדבה ולשם מנחת חוטא.\u0004","שואלים על לשון המשנה: \u0003למה לי למיתנא\u0004 \u0005[לו לשנות]\u0006 \u0003\"אלא\u0004 שלא עלו לבעלים\"? \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003ולא עלו לבעלים לשם חובה!\u0004","ומשיבים, \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003לבעלים הוא\u0004 ש\u0003לא עלו לשום חובה, הא\u0004 \u0005[אבל]\u0006 ה\u0003מנחה גופה\u0004 \u0005[עצמה]\u0006 \u0003כשרה\u0004 לגמרי, \u0003ו\u0004לכן \u0003אסור לשנויי\u0004 \u0005[לשנות בה]\u0006 שינוי אחר, וכגון שאם קמצה שלא לשמה — אסור גם להקטיר אותה שלא לשמה. \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: עולה ששחטה שלא לשמה\u0004 — \u0003אסור לזרוק דמה שלא לשמה.\u0004","ומקורו של דין זה, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 מן ה\u0003סברא, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 מן \u0003קרא\u0004 \u0005[מקרא].\u0006 ומפרטים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003סברא:\u0004 וכי \u0003משום דמשני\u0004 \u0005[שמשנה]\u0006 \u0003בה\u0004 שינוי אחד, \u0003כל הני לישני בה וניזיל\u0004 \u0005[כל אלה\u0006 ישנה בה וילך\u0005]\u0006?","\u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור\u0006 מקרא\u0005]\u0006, שנאמר: \u0003\"מוצא שפתיך תשמר ועשית כאשר נדרת לה' אלהיך נדבה\u0004 אשר דברת בפיך\" (דברים כג, כד), ויש לתהות: כיון שהוא אומר \"אשר נדרת\" אם כן מדוע הוא קורא לו \u0003נדבה?\u0004 הלוא \u0003נדר הוא!\u0004 כיצד \u0003קרי ליה\u0004 \u0005[קורא\u0006 הוא \u0005לו]\u0006 \u0003נדר וקרי ליה\u0004 \u0005[וקורא לו]\u0006 אחר כך \u0003נדבה!\u0004 \u0003אלא\u0004 כך יש להבין: \u0003אם כמה\u0004 (כמו) \u0003שנדרת עשית\u0004 ולא שינית — \u0003יהא\u0004 זה \u0003נדר\u0004 כלומר, תצא ידי חובת הנדר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 עשית כמו שנדרת, אלא שינית בו — לא תצא בו ידי חובתך, אלא \u0003יהא\u0004 קרבן \u0003נדבה;\u0004"],["\u0003ונדבה מי שרי לשנויי\u0004 \u0005[האם מותר לשנות]\u0006 \u0003בה,\u0004 לעשותה לכתחילה לשם קרבן אחר?","בענין ששנינו במשנתנו, שכל המנחות שנקמצו שלא לשמן כשרות, אלא שלא עלו לבעלים לשם חובה, שואלים: \u0003לימא מתניתין\u0004 \u0005[האם נאמר שמשנתנו]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 היא? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: כל המנחות שנקמצו שלא לשמן כשירות\u0004 לגמרי, \u0003ו\u0004אף \u0003עלו לבעלים לשם חובה,\u0004 שלא כדין הזבחים.","וטעם הדבר, לפי \u0003שאין המנחות דומות לזבחים, שהקומץ\u0004 מנחת \u0003מחבת לשום\u0004 (לשם) מנחת \u0003מרחשת\u0004 שהיא מחבת עמוקה — הלוא \u0003מעשיה מוכיחין עליה\u0004 שהיא \u0003לשום מחבת,\u0004 וכן אם קומץ מנחה \u0003חריבה\u0004 (מנחת חוטא, שאין בה שמן) \u0003לשום\u0004 מנחה \u0003בלולה\u0004 בשמן — הלוא \u0003מעשיה מוכיחין עליה\u0004 שהיא \u0003לשום חריבה,\u0004 ואין מחשבתו יכולה לשנות דבר זה.","\u0003אבל בזבחים אינו כן,\u0004 כי \u0003שחיטה אחת לכולן, וזריקה אחת לכולן, וקבלה אחת לכולן,\u0004 וכיון שההבדל בעבודת הקרבן הוא במחשבה — משום כך המחשבה משנה בהם, ולא עלו לבעלים לשם חובה.","ואומרים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003רב אשי,\u0004 ש\u0003אמר\u0004 להלן (מנחות ג,ב) בתירוץ של סתירה דומה בדברי ר' שמעון: \u0003כאן,\u0004 שאמר ר' שמעון שהיא כשרה ויצא בה ידי חובה — מדובר \u0003בקומץ מחבת לשום מרחשת,\u0004 שאומר: \"הריני קומץ לשם מרחשת\", שאינו מזכיר מנחה, אלא שם של כלי, ואין בדבריו כלום. \u0003כאן,\u0004 שאמר שלא יצא בה ידי חובה — מדובר \u0003בקומץ מנחת מחבת לשום מנחת מרחשת,\u0004 שהזכיר לשון מנחה,","ולפי זה יש לפרש כי \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 בקומץ \u0003מנחה לשום מנחה היא,\u0004 ולכן לא עלתה לבעלים. \u0003אלא ל\u0004דברי \u0003רבה ורבא,\u0004 שיישבו את הסתירה באופן אחר, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 גם כאן \u0003כדקא משני\u0004 \u0005[כמו\u0006 שמתרץ\u0005]\u0006 \u0003רבה\u0004 להלן: \u0003כאן,\u0004 שעלתה המנחה לבעלים — מדובר \u0003בשינוי קדש\u0004 שקומץ אותה לשם סוג אחר של מנחה, \u0003כאן,\u0004 שלא עלתה לבעלים — מדובר \u0003בשינוי בעלים\u0004 שקומץ אותה לשם בעלים אחרים; כיצד אתה יכול לומר כן?","\u0003הא מתניתין\u0004 \u0005[הרי משנתנו]\u0006 \u0003שינוי קודש הוא, דקתני\u0004 \u0005[שהוא שונה]\u0006 בהמשך: \u0003כיצד לשמן ושלא לשמן\u0004 — \u0003לשום מנחת חוטא ולשום מנחת נדבה,\u0004 ולא עלתה המנחה לבעליה!","\u0003ואי נמי כדקא משני\u0004 \u0005[ואו גם כן\u0006 תרצה להסביר כאן \u0005כמו שמתרץ]\u0006 \u0003רבא: כאן,\u0004 שיצאו הבעלים ידי חובתם — מדובר \u0003בקומץ מנחה לשום מנחה, כאן,\u0004 שלא עלתה לבעלים — \u0003בקומץ מנחה לשום זבח,\u0004 כיצד אתה מסביר כן?","\u0003הא מתניתין\u0004 \u0005[הרי משנתנו]\u0006 \u0003מנחה לשום מנחה היא, דקתני\u0004 \u0005[שהוא שונה]:\u0006 \u0003שלא לשמן ולשמן\u0004 — \u0003לשם מנחת נדבה לשם מנחת חוטא,\u0004 ומכל מקום לא עלתה לבעלים! \u0003אלא ל\u0004דעת \u0003רבה ורבא מחוורתא מתניתין\u0004 \u0005[ברור\u0006 הדבר ש\u0005משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' שמעון.\u0004","ומביאים את מקורם של הדברים שהוזכרו לעיל. \u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' שמעון\u0004 בברייתא שהבאנו לעיל, על דברי \u0003ר' שמעון\u0004 בברייתא אחרת. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר:\u0004 נאמר במנחה \u0003\"קדש קדשים היא כחטאת וכאשם\"\u0004 (ויקרא ו, י), והשוואה כפולה זו באה ללמד שהמנחות \u0003יש מהן\u0004 שנידונות \u0003כחטאת ויש מהן כאשם,\u0004 כיצד?","\u0003מנחת חוטא הרי היא כחטאת, לפיכך\u0004 אם \u0003קמצה שלא לשמה\u0004 — \u0003פסולה\u0004 לגמרי, \u0003כחטאת\u0004 ששחטה שלא לשמה, \u0003מנחת נדבה הרי היא כאשם, לפיכך\u0004 אם \u0003קמצה שלא לשמה\u0004 — \u0003כשירה,\u0004 כדינו של אשם שנשחט שלא לשמו.","\u0003ו\u0004כיון שהוא מדמה מנחת נדבה שמקריבה שלא לשמה ל\u0003אשם\u0004 שנשחט שלא לשמו, הרי עלינו לומר גם: \u0003מה אשם\u0004 שנעשה שלא לשמו \u0003כשר\u0004 אבל \u0003אינו מרצה\u0004 לבעליו, שלא יצא בו ידי חובתו — \u0003אף מנחת נדבה כשירה ו\u0004אולם \u0003אינה מרצה\u0004 על בעליה, ובניגוד למה שנאמר בברייתא הקודמת בשם ר' שמעון, שכל המנחות שנקמצו שלא לשמן כשרות ועלו לבעלים!","\u0003אמר רבה, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן,\u0004 שעלתה לבעלים — מדובר \u0003בשינוי קודש,\u0004 שקמץ לשם סוג אחר של מנחה, \u0003כאן,\u0004 שלא עלתה לבעלים — מדובר \u0003בשינוי בעלים,\u0004 ששינה וקמץ לשם בעלים אחרים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבה: \u0003מכדי\u0004 \u0005[הואיל]\u0006 וענין זה של \u0003מחשבה דפסל רחמנא\u0004 \u0005[שפוסלת התורה]\u0006 במנחה \u0003הקישא היא\u0004 \u0005[\u0006דבר שנלמד מן \u0005ההיקש הוא],\u0006 שהקישה התורה את המנחה לאשם — \u0003מה לי\u0004 אם עשה \u0003שינוי קודש מה לי שינוי בעלים?\u0004 והרי בקרבן אשם, בשני האופנים אין הבעלים יוצאים ידי חובתם!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: הרי \u0003\"מעשיה מוכיחין\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003ר' שמעון,\u0004 כדי להסביר מדוע בשינוי קודש אין המחשבה מועילה — \u0003סברא היא,\u0004 שכך דרכו של \u0003ר' שמעון\u0004 שהוא \u0003דריש טעמא דקרא\u0004 \u0005[דורש\u0006 את \u0005טעמו של המקרא],\u0006 ומוציא מכך מסקנות להלכה, ולפי זה, דווקא","\u0003מחשבה\u0004 של פסול \u0003דלא מינכרא\u0004 \u0005[שאינה ניכרת]\u0006 לכל, שלא ניכר ממעשיו שהמחשבה אינה נכונה — אותה \u0003פסל רחמנא\u0004 \u0005[פוסלת התורה],\u0006 והיא מחשבת שינוי בעלים. אבל \u0003מחשבה דמינכרא\u0004 \u0005[שניכרת],\u0006 וכגון שקומץ ממנחת מחבת לשם מנחת מרחשת, שמחשבתו מוכחת כאינה נכונה — \u0003לא פסל רחמנא\u0004 \u0005[לא פוסלת התורה].\u0006","ומביאים כמה וכמה קושיות על שיטה זו (שה\u0003סימן\u0004 להם הוא: \u0003עולה עולה מלק ומיצה חטאת העוף קדשי קדשים קדשים קלים).\u0004","\u0003אלא מעתה\u0004 לפי שיטה זו, \u0003עולת העוף שמלקה למעלה\u0004 במזבח \u0003משום\u0004 (לשם) \u0003חטאת העוף תרצה\u0004 לדעת ר' שמעון, שהרי גם כאן \u0003מעשיה מוכיחין עליה\u0004 ש\u0003עולת העוף היא, דאי\u0004 \u0005[שאם]\u0006 \u0003חטאת העוף היא\u0004 — \u0003למטה הוי עביד לה\u0004 \u0005[היה עושה אותה],\u0006 כשהוא עומד בצד המזבח, והלוא ר' שמעון אינו חולק על מה ששנינו שאינה עולה לבעליה!","ודוחים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חטאת העוף למעלה מי ליתא\u0004 \u0005[האם אינה]?\u0006 \u0003האמר מר\u0004 \u0005[הרי אמר החכם]:\u0006 \u0003מליקה\u0004 של חטאת העוף \u0003בכל מקום במזבח כשרה!\u0004 ואם כן לא ניכר מתוך מעשיו אם עולה היא או חטאת, ולכן המחשבה פוסלת.","ומקשים עוד: אם מחשבה ניכרת אינה פוסלת, \u0003עולת העוף שמיצה דמה למעלה לשם חטאת העוף תרצה,\u0004 שהרי \u0003מעשיה מוכיחין עליה\u0004 ש\u0003עולת העוף היא, דאי\u0004 \u0005[שאם]\u0006 \u0003חטאת העוף היא\u0004 — \u0003למטה הוה עביד לה\u0004 \u0005[היה עושה אותה],\u0006 ובדרך של \u0003הזאה\u0004 היתה נעשית, שאוחז בגופה ומזה, ולא במיצוי (סחיטה) הדם על המזבח כעולה!"],["ומשיבים: אין זה ניכר, ש\u0003אמרי\u0004 \u0005[אומרים]\u0006 אנשים: \u0003דילמא\u0004 \u0005[שמא]\u0006 חטאת היא כדבריו, וכבר היזה את דמה למטה כדינה, ומה שהוא ממצה את דמה למעלה — \u0003מיצוי דבתר\u0004 \u0005[שאחר]\u0006 \u0003הזאה הוא,\u0004 והוא כשר למעלה, \u0003דאמר מר\u0004 \u0005[ש\u0006הרי \u0005אמר החכם]:\u0006 אם \u0003מיצה דמה\u0004 של חטאת העוף \u0003בכל מקום במזבח\u0004 — \u0003כשירה,\u0004 וכיון שאפשר לטעות בזה הרי זו מחשבה שאינה ניכרת, והיא פסולה.","ועוד מקשים: \u0003חטאת העוף שהזה דמה למטה לשם עולת העוף תרצה,\u0004 שהרי \u0003מעשיה מוכיחין עליה\u0004 ש\u0003חטאת עוף היא, דאי\u0004 \u0005[שאם]\u0006 \u0003עולת העוף היא\u0004 — \u0003למעלה הוה עביד לה\u0004 \u0005[היה עושה אותה]\u0006 ולא למטה, \u0003ו\u0004כן \u0003מיצוי הוה עביד ליה\u0004 \u0005[היה עושה לה],\u0006 ולא הזאה!","ומשיבים: לדעת ר' שמעון \u0003הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 הריהי מרצה, \u0003אלא\u0004 כך יש לדייק בדבריו: \u0003לפי שאין המנחות דומות לזבחים קאמר\u0004 \u0005[הוא אומר]\u0006 — \u0003לזבחים ולא לעופות,\u0004 שעופות דומים בעניינם למנחות.","ומקשים עוד: \u0003קדשי קדשים ששחטן בצפון\u0004 העזרה \u0003לשם קדשים קלים לירצו\u0004 \u0005[שירצו],\u0006 שהרי \u0003מעשיהן מוכיחין עליהן\u0004 ש\u0003קדשי קדשים נינהו\u0004 \u0005[הם],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003קדשים קלים\u0004 — \u0003בדרום\u0004 של העזרה \u0003הוה עביד להו\u0004 \u0005[היה עושה אותם]!\u0006","ודוחים: אין זה מוכיח שקדשי קדשים הם, שכן \u0003אימור דאמר רחמנא\u0004 \u0005[אמור שאמרה התורה]\u0006 שקדשים קלים נעשים \u0003אף בדרום, בדרום ולא בצפון מי אמר\u0004 \u0005[האם אומרת]\u0006 התורה? \u0003דתנן\u0004 \u0005[ש\u0006הרי כך \u0005שנינו]\u0006 לגבי קדשים קלים: \u0003שחיטתן בכל מקום בעזרה,\u0004 ובכלל זה גם צפון.","ומקשים: אם כן, \u0003קדשים קלים ששחטן בדרום לשם קדשי קדשים לירצו\u0004 \u0005[שירצו],\u0006 שהרי \u0003מעשיהן מוכיחין עליהן\u0004 ש\u0003קדשים קלים נינהו\u0004 \u0005[הם],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003קדשי קדשים\u0004 הם — \u0003בצפון הוה עביד להו\u0004 \u0005[היה עושה אותם],\u0006 ולא בדרום!","ומשיבים: בכל זאת אין הדבר ניכר, שכן \u0003אמרי\u0004 \u0005[אומרים]\u0006 אנשים: באמת \u0003קדשי קדשים נינהו\u0004 \u0005[הם],\u0006 כדבריו, \u0003ומיעבר הוא דעבר\u0004 \u0005[ולעבור הוא שעבר]\u0006 על דברי תורה \u0003ושחט להו\u0004 \u0005[אותם]\u0006 \u0003בדרום.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מניח, שאנשים סבורים שאדם עושה שלא כדין ולכן אין מעשיו מוכיחים, במקרה שקומץ מנחת \u0003מחבת לשם מרחשת נמי\u0004 \u0005[גם כן],\u0006 מדוע אומר ר' שמעון שהיא כשרה ועלתה לבעליה? נאמר גם כאן שאין זו מחשבה ניכרת, אלא \u0003האי דקא קמיץ לה\u0004 \u0005[זה ש\u0006הוא \u0005קומץ אותה]\u0006 \u0003ל\u0004שם \u0003מרחשת, אמר\u0004 \u0005[אומר]\u0006 על כך הרואה: \u0003האי\u0004 \u0005[\u0006אדם \u0005זה]\u0006 \u0003במרחשת נדר, והא דמייתי לה\u0004 \u0005[וזה ש\u0006הוא \u0005מביא אותה]\u0006 \u0003במחבת\u0004 — אין זה מפני שהיא מנחת מחבת, אלא באמת מנחת \u0003מרחשת היא, ומעבר הוא דעבר ואתייה\u0004 \u0005[ולעבור הוא שעבר והביא אותה]\u0006 \u0003במחבת!\u0004","ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 אין מקום לטעות ולומר שמנחת מרחשת היא כדבריו, שכן \u0003כי נמי\u0004 \u0005[כאשר גם כן]\u0006 \u0003במרחשת נדר, כי מייתי לה\u0004 \u0005[כאשר מביא אותה]\u0006 \u0003במחבת\u0004 — מנחת \u0003מחבת הויא\u0004 \u0005[היא],\u0006 והיא כשרה לעניינה,","\u0003כדתנן\u0004 \u0005[כמו ששנינו]\u0006 במשנה: \u0003האומר \"הרי עלי\u0004 מנחה \u0003במחבת\" והביא במרחשת,\u0004 או נדר \"הרי עלי מנחה \u0003במרחשת\" והביא במחבת\u0004 — \u0003מה שהביא הביא,\u0004 וגומר את עבודתה כמנחת מחבת, \u0003וידי נדרו\u0004 (להביא מנחת מרחשת) \u0003לא יצא.\u0004 ומקשים: ועדיין, אם אתה מניח שאנשים סבורים שאדם עשה שלא כדין, מדוע מנחה שעשאה שלא לשמה כשרה ועלתה לבעליה?","והרי ייתכן שיעשה מנחת מרחשת ויאמר שהוא עושה אותה לשם מנחת מחבת, ואין מעשיה מוכיחים שהיא מנחת מרחשת, שיאמרו הרואים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003אמר\u0004 מתחילה בלשון \u0003\"זו\u0004 עלי \u0003להביא במחבת\" והביא\u0004 אותה \u0003במרחשת,\u0004 ובמקרה זה הריהי מנחת מחבת כדבריו (אלא שהיא פסולה), \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]:\u0006 אמר \"מנחה \u0003זו\u0004 עלי \u0003להביא במחבת\" והביא במרחשת,\u0004 או נדר \"מנחה זו עלי להביא \u0003במרחשת\" והביא במחבת\u0004 — \u0003הרי זו\u0004 מנחה \u0003פסולה!\u0004","ומשיבים: \u0003לרבנן הכי נמי\u0004 \u0005[ל\u0006דעת \u0005חכמים\u0006 האומרים כן באותה משנה \u0005כך הוא גם כן],\u0006 יש מכאן קושיה. ואולם \u0003ל\u0004דעת \u0003ר' שמעון,\u0004 שבדבריו אנו דנים בסוגיה זו, אין מכאן קושיה, כי \u0003כיון\u0004 ש\u0003אמר ר' שמעון\u0004 בברייתא שהאומר \"הרי עלי להביא במחבת\" והביא במרחשת — \u0003אף ידי נדרו יצא, אלמא קביעותא דמנא ולא כלום הוא\u0004 \u0005[מכאן\u0006 שלדעתו ה\u0005קביעה\u0006 מראש \u0005של כלי,\u0006 שאדם נודר להביא מנחת מחבת או מנחת מרחשת, \u0005אינה כלום],\u0006 \u0003ו\u0004לכן \u0003לא שנא אמר\u0004 \u0005[אינו שונה\u0006 אם הוא \u0005אומר]\u0006 \"מנחה \u0003זו\u0004 עלי להביא במרחשת\" \u0003ולא שנא אמר\u0004 \u0005[ואינו שונה\u0006 אם הוא \u0005אומר]\u0006 סתם \"הרי \u0003עלי\u0004 להביא במרחשת\", אם הביאה במחבת — הרי זו מנחת מחבת, וכשקמצה לשם מרחשת מעשיה מוכיחים עליה שמנחת מחבת היא, ולא כדבריו, ולכן היא כשרה ועולה לבעליה.","ומקשים עוד: \u0003אלא מעתה\u0004 לפי שיטה זו של רבה בדעת ר' שמעון, שכל שמעשיה מוכיחים עליה ועשאה שלא לשמה — כשרה ומרצה על בעליה, \u0003עולה ששחט לשם חטאת תרצה,\u0004 שהרי מעשיה מוכיחים שהיא עולה, \u0003דהאי\u0004 \u0005[שזו]\u0006 העולה היא תמיד \u0003זכר, והאי\u0004 \u0005[וזו]\u0006 החטאת היא \u0003נקבה!\u0004 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003שעיר\u0004 חטאת של \u0003נשיא\u0004 ש\u0003זכר הוא\u0004 — \u0003לא ידיע\u0004 \u0005[אין זה ידוע]\u0006 וניכר, שהרי יתכן שזכר זה היה שעיר נשיא.","ושואלים: ואם \u0003אמר\u0004 במפורש: \"הריני שוחט בהמה זו \u0003לשם חטאת יחיד\",\u0004 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 על זה? מדוע לא תרצה? הרי חטאת יחיד היא לעולם נקבה! \u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003חטאת יחיד ששחטה לשם עולה תרצה,\u0004 מפני שמעשיה מוכיחים עליה, שהרי ה\u0003חטאת נקבה ו\u0004ה\u0003עולה\u0004 היא \u0003זכר!\u0004 ומשיבים: אין הדבר ניכר, כי הכבשה \u0003מיכסיא\u0004 \u0005[מכוסה]\u0006 בחלקה האחורי \u0003באליה,\u0004 ואין רואים בבירור אם היא נקבה אם זכר.","ומקשים: \u0003התינח היכא דאייתי\u0004 \u0005[זה נוח,\u0006 מובן, \u0005במקום שהביא]\u0006 לחטאתו \u0003כבשה\u0004 שיש לה אליה, אבל אם \u0003אייתי\u0004 \u0005[הביא]\u0006 \u0003שעירה,\u0004 ואין לעיזים אליה, \u0003מאי\u0004 \u0003איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע לא תרצה? והרי מראיה מוכיחים שהיא חטאת! \u0003אלא\u0004 יש לתרץ באופן אחר: ההבחנה \u0003בין זכרים לנקבות לאו אדעתייהו דאינשי\u0004 \u0005[אינה על דעתם של בני אדם],\u0006 אינם שמים ליבם אליה, ואין הדבר ניכר לכל כאשר הוא משנה.","ועוד שואלים לשיטה זו: \u0003פסח ששחטו לשם אשם לירצי\u0004 \u0005[שירצה],\u0006 שהרי יש ביניהם הבדל ניכר, \u0003דהאי\u0004 \u0005[שזה]\u0006 פסח הוא כבש \u0003בן שנה, והאי\u0004 \u0005[וזה]\u0006 האשם הוא איל \u0003בן שתים!\u0004 ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003אשם נזיר ואשם מצורע\u0004 שהם בני שנה, \u0003לא פסיקא ליה\u0004 \u0005[אין הדבר פסוק,\u0006 ברור \u0005לו],\u0006 ואינו ניכר.","ומקשים: ואם \u0003אמר\u0004 במפורש: \"הריני שוחט את הפסח \u0003לשום אשם גזילות ולשום אשם מעילות\",\u0004 שצריך להביאם בני שנתים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 על זה? \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003אשם גזילות ואשם מעילות ששחטן לשום פסח לירצו\u0004 \u0005[שירצו],\u0006 שניכר ממעשיהם שאינם פסח, שהרי \u0003פסח\u0004 הוא תמיד \u0003בן שנה, והני\u0004 \u0005[ואלה]\u0006 הם \u0003בן שתי שנים!\u0004","\u0003אלא\u0004 יש לתרץ: ההבדל \u0003בין בן שנה לבין בן שתי שנים לאו אדעתייהו דאינשי\u0004 \u0005[אין בני אדם נותנים דעתם עליו\u0006\u0005],\u0006 ואין הדבר ניכר כל כך, \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003בן שנה דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבן שתים, ואיכא\u0004 \u0005[ויש]\u0006 \u0003בן שתים דמיחזי\u0004 \u0005[שנראה]\u0006 \u0003כבן שנה.\u0004","ושואלים עוד: \u0003שעיר\u0004 חטאת \u0003ששחטו לשום אשם לירצי\u0004 \u0005[שירצה],\u0006 שהרי מוכח עליו שאינו אשם, \u0003דהאי\u0004 \u0005[שזה]\u0006 האשם הוא איל שיש לו \u0003צמר\u0004 לבן, \u0003והאי\u0004 \u0005[וזה]\u0006 השעיר יש לו \u0003שיער\u0004 שחור! ומשיבים, \u0003אמרי\u0004 \u0005[יאמרו]\u0006 אנשים: \u0003דיכרא אוכמא\u0004 \u0005[איל שחור]\u0006 \u0003הוא,\u0004 ולא יבחינו שהוא ממין העיזים.","ומקשים: \u0003עגל ופר ששחטן לשום פסח ואשם,\u0004 שהם באים מן הצאן, \u0003לירצו\u0004 \u0005[שירצו],\u0006 שהרי ניכר שאינם שייכים לקרבן זה, שהרי \u0003עגל ופר בפסח ואשם ליכא\u0004 \u0005[אין]\u0006 בכלל! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן הוא גם כן],\u0006 ולשיטת ר' שמעון אכן יעלו לרצון לבעליהם,"],["\u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003זבחים\u0004 שאמר ר' שמעון, שאין המנחה דומה לזבחים שמעשיהם אינם מוכיחים, ולכן המחשבה מועילה בהם? הכוונה היא ל\u0003רוב\u0004 ה\u0003זבחים,\u0004 אבל אלו שמעשיהם מוכיחים איזה קרבן הם — אין מחשבת שינוי השם מועילה בהם, ועלו לבעלים לשם חובה.","\u0003רבא אמר\u0004 תירוץ אחר לסתירה בדברי ר' שמעון בשתי הברייתות, \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שאמרנו שהמנחה שלא לשמה עולה לרצון לבעליה — הוא \u0003בקומץ מנחה לשום מנחה, כאן\u0004 שכשרה אלא שאינה עולה לרצון לבעליה — \u0003בקומץ מנחה לשום זבח.\u0004","וטעם הדבר: בקומץ \u0003מנחה לשום מנחה\u0004 ממין אחר — הרי נאמר \u0003\"וזאת תורת המנחה\"\u0004 (ויקרא ו, ז), ולמדים מכאן ש\u0003תורה אחת לכל המנחות,\u0004 ששם אחד לכולן, ואין ההבדל ביניהן אלא לענין עשייתן לכתחילה. אבל אם קומץ \u0003מנחה לשום זבח\u0004 — \u0003\"וזאת תורת המנחה וזבח\"\u0004 הרי \u0003לא כתיב\u0004 \u0005[לא נאמר],\u0006 שנאמר שתורה אחת לכולם, והואיל ושינה את שם המנחה לשם קרבן אחר — לא עלתה לבעליה.","ושואלים: כיצד ניתן לומר שטעמו של ר' שמעון הוא משום שנאמר \"זאת תורת המנחה\"? \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא \"מפני שמעשיה מוכיחין עליה\" קאמר\u0004 \u0005[הוא אומר]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 כך יש להבין את דבריו: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מחשבה דלא מינכרא\u0004 \u0005[שאינה ניכרת]\u0006 \u0003היא,\u0004 שמעשיה של המנחה מוכיחים שלא כדבריו, \u0003ו\u0004מצד הסברה היה ראוי ש\u0003תיפסל,\u0004 בכל זאת נאמר \u0003\"וזאת תורת המנחה\"\u0004 — \u0003תורה אחת לכל המנחות.\u0004","ושואלים: \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הביטוי \u0003אבל בזבחים אינו כן?\u0004","ומשיבים, הכוונה היא: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003שחיטה אחת לכולן\u0004 ואין מעשיהם מוכיחים שלא כמחשבתו, ואם כן לפי הסברה צריך היה להכשיר בהם, מכל מקום \u0003\"וזאת תורת המנחה וזבח\" לא כתיב\u0004 \u0005[לא נאמר],\u0006 כלומר, לא נאמר \"זאת תורת הזבח\" כפי שנאמר \"זאת תורת המנחה\", והואיל ושינה בהם — לא עלו לבעליהם.","ומקשים: \u0003אלא מעתה,\u0004 שאתה למד מ\"זאת תורת המנחה\" שמנחה שעשאה לשם מנחה אחרת כשרה ועלתה לבעליה, אם כן \u0003חטאת חלב\u0004 שמביא על אכילת חלב בשגגה, \u0003ששחטה לשם חטאת דם\u0004 חטאת שהיה צריך להביא על שאכל דם בשגגה, או ששחטה \u0003לשום חטאת עבודה זרה,\u0004 או \u0003לשום חטאת נזיר,\u0004 או \u0003לשום חטאת מצורע\u0004 — \u0003תהא כשירה ותרצה, דאמר רחמנא\u0004 \u0005[שאמרה התורה]:\u0006 \u0003\"וזאת תורת החטאת\"\u0004 (ויקרא ו, יח), לומר: \u0003תורה אחת לכל חטאות!\u0004","ומשיבים: אכן, \u0003ל\u0004דעת \u0003ר' שמעון הכי נמי\u0004 \u0005[כך הוא גם כן],\u0006 שאם שחט חטאת לשם כל חטאת אחרת הרי היא כשרה ועולה לרצון. ומעירים: \u0003לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים],\u0006 החולקים על ר' שמעון, ואינם למדים מ\"זאת תורת החטאת\", \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר\u0004 רבא: \u0003חטאת חלב ששחטה לשם חטאת דם,\u0004 או \u0003לשום חטאת עבודה זרה\u0004 — \u0003כשירה,\u0004 אבל אם שחט אותה \u0003לשם חטאת נזיר\u0004 או לשם חטאת \u0003מצורע\u0004 — \u0003פסולה,\u0004 וטעם הדבר, לפי \u0003דהני\u0004 \u0005[שאלה,\u0006 חטאת נזיר וחטאת מצורע\u0005]\u0006 אינן כשאר חטאות הבאות לכפרת חטא, שהרי \u0003עולות בהדייהו נינהו\u0004 \u0005[יחד איתן הן\u0006 באות\u0005].\u0006","ומעירים: \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני ליה לכולהו לפסולא\u0004 \u0005[היה שונה\u0006 בשם רבא \u0005את כל\u0006 המקרים הללו, של חטאת ששחטה לשם חטאת אחרת, \u0005לפסול],\u0006 ואפילו חטאת חלב ששחטה לשם חטאת דם, שנאמר: \u0003\"ושחט אותה לחטאת\"\u0004 (ויקרא ד, לג), ו\"אותה\" בא להדגיש — \u0003לשם אותו חטאת,\u0004 ולא לשם חטאת אחרת.","\u0003רב אשי אמר\u0004 תירוץ אחר לגבי \u0003הסתירה בדברי ר' שמעון:\u0004 \u0003לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן,\u0004 שמנחה שנקמצה שלא לשמה כשרה ועלתה לבעליה — \u0003בקומץ מנחת מחבת\u0004 ואומר: הריני קומץ \u0003לשום מרחשת, כאן\u0004 שלא עלתה לבעליה — \u0003בקומץ מנחת מחבת\u0004 ואומר: הריני קומץ \u0003לשום מנחת מרחשת.\u0004","וטעם ההבדל: כשהוא קומץ \u0003מנחת\u0004 \u0003מחבת לשום מרחשת\u0004 — הרי \u0003במנא קא מחשב\u0004 \u0005[בכלי הוא מחשב],\u0006 \u0003ומחשבה במנא\u0004 \u0005[בכלי]\u0006 \u0003לא פסלה\u0004 \u0005[אינה פוסלת],\u0006 שאין בדבריו כלום, מפני שכלי אינו עומד להקרבה. אבל אם קומץ \u0003מנחת מחבת לשום מנחת מרחשת\u0004 — \u0003במנחה דפסלה\u0004 \u0005[שפוסלת]\u0006 \u0003בה מחשבה קא מחשב\u0004 \u0005[הוא מחשב],\u0006 ולכן לא עלתה המנחה לבעליה.","ומקשים: כיצד ניתן לומר שזה הוא טעמו של ר' שמעון? \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא\u0004 נותן טעם אחר לדבר, \u0003\"מפני שמעשיה מוכיחין עליה\" קאמר\u0004 \u0005[הוא אומר]!\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 כאשר קומץ מנחת מחבת לשם מרחשת, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003מחשבה מינכר\u0004 \u0005[ניכרת]\u0006 \u0003היא,\u0004 שמוכח מדבריו שהיא מחשבה שאינה ראויה, וראוי היה ש\u0003תיפסל,\u0004 מכל מקום הואיל וחישב בכלי שאין המחשבה בו פוסלת — כשרה ועלתה לבעלים.","ושואלים: \u0003ו\u0004לפי זה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003אבל בזבחים אינו כן?\u0004 ומשיבים: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003שחיטה אחת לכולן, זריקה אחת לכולן, קבלה אחת לכולן,\u0004 ואין שינויו ניכר לעין, וראוי היה שלא יפסול — מכל מקום \u0003בזביחה דפסלה ביה\u0004 \u0005[\u0006בדבר \u0005שפוסלת בו]\u0006 \u0003מחשבה קא מחשב\u0004 \u0005[הוא מחשב],\u0006 וכגון שאומר: הריני שוחט (עולה) לשם שלמים, ולכן אין הקרבן עולה לבעליו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 לפי הסבר זה, אם קומץ \u0003חרבה משום\u0004 (לשם) \u0003בלולה אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר ר' שמעון\u0004 שתעלה אף לשם חובה? והרי הוא מחשב במנחה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מה שאמר שהוא עושה כן לשם בלולה — יש להבין כי כוונתו \u0003לשום בילה בעלמא\u0004 \u0005[לשם בלילה סתם],\u0006 ולא לשם מנחה בלולה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש את דבריו, הרי גם בזבחים, כשהוא שוחט עולה \u0003לשום שלמים נמי\u0004 \u0005[גם כן]\u0006 נאמר: משמעות דבריו היא \u0003לשום שלמים בעלמא\u0004 \u0005[בלבד],\u0006 לעשות שלום בין האדם לקדוש ברוך הוא, ולא לשם קרבן שלמים, ומדוע אף ר' שמעון מודה שבמקרה זה לא עלה הקרבן לשם חובת בעליו?","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 ה\u0003זבח גופה איקרי\u0004 \u0005[עצמו נקרא]\u0006 \u0003שלמים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"המקריב את דם השלמים\"\u0004 (שם ז, לג), וכן \u0003\"הזרק את דם השלמים\"\u0004 (שם יד) ומשמע שהקרבן עצמו נקרא \"שלמים\", אבל \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003מנחה גופה\u0004 \u0005[עצמה]\u0006 \u0003מי איקרי\u0004 \u0005[האם נקראת]\u0006 \u0003\"בלולה\"?\u0004 שהרי \u0003\"וכל מנחה בלולה בשמן\"\u0004 (שם י) \u0003כתיב\u0004 \u0005[נאמר],\u0006 \u0003\"בלולה בשמן\" איקרי\u0004 \u0005[נקראת],\u0006 \u0003\"בלולה\" סתמא לא איקרי\u0004 \u0005[סתם אינה\u0006 נקראת\u0005]\u0006, ואין זה שם של קרבן.","לסיכום, שלושה הסברים ניתנו ליישוב הסתירה בדברי ר' שמעון, האם מנחה שנקמצה שלא לשמה עלתה לבעליה או לא. ומסבירים: \u0003כולהו\u0004 \u0005[כולם]\u0006 כל החכמים האחרים, רבא ורב אשי, \u0003כ\u0004דעת \u0003רבה לא אמרי\u0004 \u0005[אינם אומרים],\u0006 שיש לחלק בין אם קמצה לשם מנחה אחרת, ואז עלתה לבעליה, מפני שמעשיה של המנחה מוכיחים שמחשבתו אינה נכונה, לבין אם קמצה לשם אדם אחר, שלא עלתה לבעליה, מפני שאין מחשבתו ניכרת כלא נכונה — לפי שאינם מקבלים את סברתו העיקרית, \u0003דאדרבה\u0004 \u0005[שלהיפך],\u0006 לדעתם דווקא \u0003מחשבה דמנכרא\u0004 \u0005[שניכרת]\u0006 שהוא עושה שלא כדין \u0003פסל רחמנא\u0004 \u0005[פוסלת התורה].\u0006","וכן מצד אחר, רבה ורב אשי \u0003כ\u0004דעת \u0003רבא לא אמרי\u0004 \u0005[אינם אומרים],\u0006 שיש לחלק בין קומץ מנחה לשם זבח, שאינה עולה לבעליה, לבין קומץ מנחה לשם מנחה שהיא עולה לבעליה, שנאמר \"זאת תורת המנחה\" — תורה אחת לכל המנחות, מפני שהלימוד של \u0003\"וזאת תורת\u0004 המנחה\" \u0003לא משמע להו\u0004 \u0005[להם],\u0006 אינם מקבלים אותו.","וכן רבה ורבא \u0003כ\u0004דעת \u0003רב אשי לא אמרי\u0004 \u0005[אינם אומרים],\u0006 שיש להבחין בין קומץ מנחה לשם כלי, שאין המחשבה פוסלת בו כלל והיא עולה לבעליה, לבין קומץ מנחה לשם מנחה, שלא עלתה לבעליה — \u0003משום קושיא\u0004 \u0005[הקושיה]\u0006 שהקשה עליו \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא,\u0004 מקומץ חריבה לשם בלולה, שהיא עולה לבעליה למרות ש\"בלולה\" היא מנחה ולא כלי.","ומעירים: עניינה של מחשבה פסולה שאינה ניכרת, שהוא \u0003מילתא דפשיטא ליה\u0004 \u0005[דבר\u0006 \u0005שפשוט לו]\u0006 \u0003לרבה להאי גיסא\u0004 \u0005[לצד זה],\u0006 שיש בה כדי לפסול, \u0003ולרבא\u0004 היה פשוט לו \u0003להאי גיסא\u0004 \u0005[לצד זה],\u0006 שאינה פוסלת כלל, \u0003מיבעיא ליה\u0004 \u0005[מסופק לו]\u0006 \u0003לרב הושעיא. דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב הושעיא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בלשון אחרת: \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הושעיא מר' אסי\u0004 שאלה זו: המביא \u0003מנחה לשום זבח\u0004"],["\u0003מה לי אמר ר' שמעון,\u0004 מה דעתו במקרה זה? האם \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003ר' שמעון\u0004 שהוא מכשיר מנחה שקמצה לשם מנחה ממין אחר, הוא \u0003משום\u0004 ש\u0003מחשבה דמינכרא\u0004 \u0005[שניכרת]\u0006 שאינה נכונה \u0003לא פסלה\u0004 \u0005[אינה פוסלת],\u0006 ומנחה מעשיה מוכיחים עליה שלא כדבריו. \u0003והא\u0004 \u0005[וזו]\u0006 גם כן, כשקומץ מנחה לשם זבח, \u0003מחשבה דמינכרא הוא\u0004 \u0005[שניכרת היא],\u0006 ואינה פוסלת.","\u0003או דילמא טעמא\u0004 \u0005[שמא טעמו]\u0006 של \u0003ר' שמעון\u0004 הוא \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזאת תורת המנחה\"\u0004 (ויקרא ו, ז) — תורה אחת לכל המנחות, ואילו \"זאת תורת המנחה \u0003וזבח\" לא כתיב\u0004 \u0005[לא נאמר],\u0006 ולכן כשקומץ מנחה לשם זבח — לא עלתה לבעלים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי: \u0003כלום הגענו לסוף דעתו של ר' שמעון?\u0004 כלומר, אין אנו יודעים להסביר את טעמו בענין זה.","ומסבירים: \u0003כ\u0004תירוצו של \u0003רבה לא משני ליה\u0004 \u0005[אינו מתרץ לו],\u0006 שיש להבחין בין שינוי קודש לשינוי בעלים — \u0003משום\u0004 ה\u0003קושיא\u0004 של \u0003אביי,\u0004 ששניהם נלמדו מאותו היקש;","\u0003כרבא לא משני ליה\u0004 \u0005[אינו מתרץ לו]\u0006 שמנחה לשם מנחה כשרה, מפני שנאמר: \"זאת תורת המנחה\" — \u0003משום\u0004 ה\u0003קושיא\u0004 מ\u0003\"וזאת תורת החטאת\"\u0004 (שם יח), שלמרות שנאמר כן, השוחט חטאת לשם חטאת אחרת — פסל.","\u0003כ\u0004תירוצו של \u0003רב אשי לא משני ליה\u0004 \u0005[אינו מתרץ לו],\u0006 שיש להבחין בין קומץ מנחה לשם כלי לבין קומץ מנחה לשם מנחה — \u0003משום\u0004 ה\u0003קושיא\u0004 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא,\u0004 מקומץ חריבה לשם בלולה, שהיא עולה לבעליה, למרות שאינו מחשב לשם כלי.","שנינו במשנה: כל המנחות שקמצן שלא לשמן כשרות, \u0003חוץ ממנחת חוטא ומנחת קנאות,\u0004 שאם עשה עבודתן שלא לשמן — פסולות. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מנחת חוטא\u0004 יש טעם בדבר — \u0003\"חטאת\" קרייה רחמנא\u0004 \u0005[קראה אותה התורה],\u0006 שנאמר: \u0003\"לא ישים עליה שמן ולא יתן עליה לבונה כי חטאת היא\" וגו'\u0004 (שם ה, יא), ומכיון שהיא נקראת חטאת — דינה כחטאת, שפסולה שלא לשמה. \u0003אלא מנחת קנאות מנלן\u0004 \u0005[מנין לנו]\u0006 שזה דינה?","ומשיבים, ממה \u0003דתני תנא קמיה\u0004 \u0005[ששנה חוזר המשניות לפני]\u0006 \u0003רב נחמן: מנחת קנאות מותרה נדבה,\u0004 שאם הפריש מעות למנחת סוטה, ולא היה צורך בכולן — ישתמשו בהן לקרבנות נדבה של ציבור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003שפיר קאמרת\u0004 \u0005[יפה אומר אתה],\u0006 שהרי \u0003\"מזכרת עון\"\u0004 (במדבר ה, טו) \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה, ובחטאת כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ואתה נתן לכם לשאת את עון העדה\"\u0004 (ויקרא י, יז), וכיון שבשני הכתובים נאמר \"עון\" למדים בגזירה שווה: \u0003מה חטאת מותרה נדבה\u0004 — \u0003אף מנחת קנאות מותרה נדבה,\u0004 ועל פי זה נוסיף גם לענייננו: \u0003וכחטאת, מה חטאת פסולה שלא לשמה\u0004 — \u0003אף מנחת קנאות פסולה שלא לשמה.\u0004","ומקשים: \u0003אלא מעתה,\u0004 שמכאן אנו למדים, אף \u0003אשם יהא פסול שלא לשמו, דגמר\u0004 \u0005[שהוא למד]\u0006 בגזירה שווה של המילה \u0003\"עון\" \"עון\" מחטאת,\u0004 שבחטאת נאמר \"עון העדה\" (שם) ובאשם נאמר \"ונשא עונו\" (שם ה, יז)!","ודוחים: \u0003דנין \"עון\" מ\u0004מקום אחר שכתוב בו \u0003\"עון\", ואין דנין \"עונו\"\u0004 \u0003מ\"עון\".\u0004","ושואלים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה]?\u0006 מה משנה הבדל זה? \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על הפסוקים שנאמרו במצורע: \u0003\"ושב הכהן\"\u0004 (שם יד, לט) \u0003\"ובא הכהן\"\u0004 (שם מד) — \u0003זו היא שיבה זו היא ביאה,\u0004 ולמדים זה מזה בגזירה שווה משום שהתוכן שווה, למרות שהמילים אינן זהות!","\u0003ועוד\u0004 אפשר להקשות: \u0003ליגמר\u0004 \u0005[שילמד]\u0006 \u0003\"עונו\" \"עונו\" מעון\u0004 שכתוב בחטאת \u0003של\u0004 \u0003שמיעת הקול\u0004 כלומר, של מי שנשבע לשקר שאינו יודע עדות לחבירו, \u0003דכתיב\u0004 \u0005[שנאמר\u0006 שם\u0005]:\u0006 \u0003\"אם לא יגיד ונשא עונו\"\u0004 (שם ה, א)!","\u0003אלא\u0004 בהכרח צריך אתה לומר: \u0003כי גמרי\u0004 \u0005[כאשר למדים]\u0006 \u0003גזירה שוה\u0004 מחטאת למנחת קנאות — רק \u0003ל\u0004ענין \u0003מותר נדבה הוא דגמרי\u0004 \u0005[שלמדים],\u0006 ואין למדים מכאן לענין פסול שלא לשמה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 הלוא \u0003אין גזירה שוה למחצה\u0004 — על כך יש לומר כי במקרה זה \u0003גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 ל\u0003גבי חטאת\u0004 שלענין זה אין למדים, \u0003שנאמר:\u0004 \u0003\"ושחט אותה לחטאת\"\u0004 (ויקרא ד, לג), ויש פה הדגשה: \"אותה\", כלומר, רק אם שחט \u0003אותה לשמה\u0004 — \u0003כשירה, שלא לשמה\u0004 — \u0003פסולה, אבל כל קדשים\u0004 אחרים \u0003בין לשמן\u0004 \u0003בין שלא לשמן\u0004 — \u0003כשרים.\u0004","ושואלים: \u0003אלא\u0004 לפי זה, שהתורה מיעטה כל קרבן אחר, \u0003מנחת חוטא ומנחת קנאות\u0004 ש\u0003פסולין שלא לשמן מנלן\u0004 \u0005[מנין לנו]?\u0006","ומשיבים: \u0003חטאת טעמא מאי\u0004 \u0005[מה הטעם]\u0006 שהיא פסולה שלא לשמה — \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בה \"היא\",\u0004 שנאמר בחטאת הנשיא \"חטאת הוא\" (ויקרא ד, כד) להדגיש — דווקא כשהיא נעשית לשמה היא כשרה, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 לענין מנחת חוטא ומנחת קנאות — \u0003הא כתיב בהו\u0004 \u0005[הרי כתוב בהם]\u0006 לשון \u0003\"היא\",\u0004 במנחת חוטא \"חטאת היא\" (שם ה, יא), ובמנחת קנאות \"מנחת קנאות הוא\" (במדבר ה, טו).","ומקשים: \u0003אשם נמי\u0004 \u0005[גם כן]\u0006 \u0003הא כתיב ביה\u0004 \u0005[הרי כתובה בו]\u0006 המילה \u0003\"הוא\"\u0004 שנאמר: \"והקטיר אותם הכהן המזבחה אשה לה' אשם הוא\" (ויקרא ז, ה)! ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003\"הוא\" לאחר הקטרת אימורין\u0004 (החלקים הקרבים) על המזבח \u0003הוא דכתיב\u0004 \u0005[שנאמר],\u0006","\u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 דווקא בחטאת יש ללמוד מ\"הוא\" שאם שחטה שלא לשמה הריהי פסולה, \u0003אבל אשם לא נאמר בו\u0004 \"אשם \u0003הוא\" אלא לאחר הקטרת אימורין,\u0004 ואין לומר שהוא נפסל אז במחשבת שלא לשמו, שהרי \u0003הוא עצמו שלא הוקטרו אימוריו\u0004 כלל על המזבח \u0003כשר.\u0004","אגב כך שואלים: \u0003ואלא \"הוא\"\u0004 שנאמר באשם \u0003למה לי?\u0004 ומשיבים: \u0003לכ\u0004 דברי \u0003רב הונא אמר רב,\u0004 שאמר: \u0003אשם שניתק לרעייה\u0004 שמתו או שנתכפרו בעליו, ודינו לרעות בשדה עד שיפול בו מום ויביאו בדמיו עולה לנדבת הציבור, אם נמסר לרועה, \u0003ו\u0004קודם שנפל בו מום \u0003שחטו סתם\u0004 ולא פירש לשם מה — הרי הוא \u0003כשר לשום עולה,\u0004 שהרי דמיו מיועדים לכך.","ונדייק: דווקא אם \u0003ניתק\u0004 לרעייה — \u0003אין\u0004 \u0005[כן],\u0006 הוא כשר לעולה, אבל אם \u0003לא ניתק\u0004 — \u0003לא.\u0004 וטעם הדבר, מפני ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"אשם \u0003הוא\",\u0004 לומר: \u0003בהוייתו יהא,\u0004 אשם הוא עד שייעקר שמו ממנו.","בהמשך למה ששנינו במשנה, שכל המנחות שקמצן שלא לשמן כשרות, אלא שלא עלו לבעליהן לשם חובה, \u0003אמר רב: מנחת העומר שקמצה שלא לשמה\u0004 — \u0003פסולה\u0004 היא, \u0003הואיל ובאת להתיר\u0004 את אכילת התבואה החדשה \u0003ו\u0004כשעשאה שלא לשמה \u0003לא התירה. וכן אתה אומר באשם נזיר\u0004 טמא, שמכשיר את הנזיר להתחיל ולמנות נזירות חדשה בטהרה,"],["\u0003ואשם מצורע\u0004 שמתיר אותו לבוא למחנה ישראל ובאכילת קדשים, \u0003ששחטן שלא לשמן\u0004 — שהם \u0003פסולין, הואיל ובאו להכשיר\u0004 אותם \u0003ולא הכשירו.\u0004","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל המנחות שנקמצו שלא לשמן\u0004 — \u0003כשירות, אלא שלא עלו לבעלים לשום חובה, חוץ ממנחת חוטא ומנחת קנאות. ואם איתא\u0004 \u0005[אכן]\u0006 כדברי רב, \u0003ליתני נמי\u0004 \u0005[שישנה גם כן]\u0006 \u0003חוץ ממנחת העומר!\u0004","ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר\u0006 התנא \u0005שונה]\u0006 במשנתנו הרי זה רק במנחה ש\u0003באה\u0004 עבור \u0003יחיד,\u0004 מנחה ש\u0003באה\u0004 ב\u0003צבור לא קתני\u0004 \u0005[אינו שונה].\u0006 וכן, \u0003כי תני\u0004 \u0005[כאשר הוא שונה]\u0006 הרי זה במנחה ה\u0003באה בגלל עצמה,\u0004 כלומר, כשלעצמה, אבל מנחה שבאה \u0003בגלל זבח,\u0004 כגון מנחת העומר הבאה עם שני כבשים — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006","וכן \u0003כי קתני\u0004 \u0005[כאשר הוא שונה]\u0006 הרי זה \u0003הנך\u0004 \u0005[אותן]\u0006 מנחות \u0003שאין קבוע להן זמן,\u0004 תאריך מסויים, אבל \u0003הא\u0004 \u0005[זו]\u0006 מנחת העומר ש\u0003קבוע לה זמן\u0004 בששה עשר בניסן, \u0003לא קתני\u0004 \u0005[אינו שונה]\u0006 אותה. ואם כן, אין סתירה לדברי רב ממה שלא הזכיר התנא מנחת העומר בין המנחות הפסולות במשנה.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 רב: \u0003וכן אתה אומר באשם נזיר ואשם מצורע ששחטן שלא לשמן\u0004 — \u0003פסולין, הואיל ובאו להכשיר ולא הכשירו.\u0004","ומקשים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 בזבחים: \u0003כל הזבחים ששחטן שלא לשמן\u0004 — הרי הם \u0003כשרין\u0004 לכל דבר, \u0003אלא שלא עלו לבעלים לשום חובה, חוץ מפסח וחטאת,\u0004 שאם שחטם שלא לשמם — הריהם פסולים. \u0003ואם איתא\u0004 \u0005[יש,\u0006 נכון הדבר\u0005]\u0006 כדברי רב, \u0003ליתני נמי\u0004 \u0005[שישנה גם כן]:\u0006 \u0003חוץ מאשם נזיר ואשם מצורע\u0004 שהם פסולים, מפני ש\u0003באו להכשיר ולא הכשירו!\u0004","ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003אשם גזילות\u0004 שמביא גזלן שנשבע לשקר, \u0003ואשם מעילות\u0004 שמביא המועל בהקדש, ש\u0003לכפרה\u0004 של עוון \u0003אתו\u0004 \u0005[באו]\u0006 ולא להכשיר, ואם שחטם שלא לשמם כשרים — \u0003לא פסיקא ליה\u0004 \u0005[אין\u0006 הדבר \u0005פסוק לו],\u0006 ולכן אינו שונה דין אשם במשנה.","ותוהים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003אשם נזיר ואשם מצורע\u0004 שאם שחטם שלא לשמם פסולים, מפני ש\u0003באו להכשיר ולא הכשירו, הני נמי\u0004 \u0005[\u0006אשמות \u0005אלה גם כן],\u0006 אשם גזילות ואשם מעילות ייפסלו כשעשאם שלא לשמם, כיון \u0003ש\u0004\u0003באו לכפרה ולא כפרו!\u0004","\u0003אמר ר' ירמיה: מצינו שחלק הכתוב בין מכפרים ובין מכשירין,\u0004 שהחמיר יותר בפסולם של המכשירים, שהרי \u0003מכפרין אית בהו דאתו\u0004 \u0005[יש בהם\u0006 קרבנות \u0005שבאים]\u0006 \u0003לאחר מיתה,\u0004 ואילו \u0003מכשירין לית בהו דאתו\u0004 \u0005[אין בהם\u0006 כאלה \u0005שבאים]\u0006 \u0003לאחר מיתה\u0004 של הבעלים. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה\u0004 היולדת, שצריכה להביא חטאת ועולה, \u0003שהביאה\u0004 \u0003חטאתה ומתה\u0004 — \u0003יביאו יורשין\u0004 שלה את \u0003עולתה,\u0004 שהיא כפרתה. אבל אם הפרישה \u0003עולתה ומתה\u0004 — \u0003לא יביאו יורשין חטאתה,\u0004 שחטאת זו באה כדי להכשירה לאכילת קדשים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: מכשירין נמי\u0004 \u0005[גם כן]\u0006 \u0003מי לית בהו דאתו\u0004 \u0005[האם אין בהם\u0006 כאלה \u0005שבאים]\u0006 \u0003לאחר מיתה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003המפריש מעות ל\u0004קרבן \u0003נזירותו,\u0004 שיש בו חטאת, עולה ושלמים — \u0003לא נהנין\u0004 מהם לכתחילה, \u0003ולא מועלין\u0004 בהם, כלומר, אם נהנה מהם בשוגג אינו משלם קרן וחומש, ואינו מביא אשם מעילה, \u0003מפני\u0004 שהם \u0003ראויין לבא כולן שלמים,\u0004 ואין מעילה במעות שלמים.","\u0003מת\u0004 הנזיר \u0003והיו לו מעות סתומין\u0004 שהקדיש לנזירותו, אבל לא פירש אלו מעות מיועדים לאיזה קרבן — כל המעות הללו \u0003יפלו לנדבה,\u0004 לקרבנות נדבה של הציבור. אם היו לו מעות \u0003מפורשין,\u0004 שייחד מעות לכל אחד מן הקרבנות שהוא צריך להביא, הרי מה שהופרש לצורך דמי חטאת — \u0003יוליך לים המלח,\u0004 לפי שהם דמי חטאת שמתו בעליה שדינה למיתה, ומעות אלו \u0003לא נהנין\u0004 בהם, \u0003ולא מועלין\u0004 בהם, מפני שאינם עומדים להקרבה, \u0003דמי עולה\u0004 — \u0003יביא בהן עולה, ומועלין בהן\u0004 בדמים,","\u0003דמי שלמים\u0004 — \u0003יביא בהן שלמים, ונאכלין\u0004 השלמים \u0003ליום אחד\u0004 בלבד, כדין איל השלמים שמביא הנזיר (ולא כדין שלמים רגילים, שנאכלים לשני ימים ולילה אחד), \u0003ו\u0004אולם \u0003אין טעונין לחם\u0004 כשלמי נזיר. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003עולה ושלמים\u0004 של ה\u0003נזיר\u0004 ש\u0003מכשירים נינהו\u0004 \u0005[הם],\u0006 שהם מתירים אותו בשתיית יין, \u0003וקא אתו\u0004 \u0005[והם באים]\u0006 \u0003לאחר מיתה!\u0004","\u0003אמר רב פפא, הכי קא אמר\u0004 \u0005[כך אומר]\u0006 \u0003ר' ירמיה: לא מצינו הכשר קבוע,\u0004 שאין הכשר בלעדיו, ש\u0003בא לאחר מיתה; ו\u0004עולה ושלמים של \u0003נזיר\u0004 כל אחד מהם \u0003הכשר שאינו קבוע הוא,\u0004"],["\u0003דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 \u0003גילח על אחת משלשתן\u0004 (חטאת, או עולה, או שלמים) — \u0003יצא,\u0004 משמע שאין ההכשר תלוי בקרבן מסויים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003אשם מצורע שנשחט שלא לשמו, או שלא ניתן מדמו על גבי בהונות\u0004 — \u0003הרי זה עולה לגבי מזבח, וטעון נסכים\u0004 כדין אשם מצורע, \u0003ו\u0004מכל מקום \u0003צריך אשם אחר להכשירו\u0004 את המצורע. והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על שיטת \u0003רב,\u0004 שאמר שקרבן כזה פסול לגמרי, מאחר שבא להכשיר ולא הכשיר.","ביחס למה שנאמר בשם רב, שמנחת העומר שנקמצה שלא לשמה פסולה, מוסיפים: \u0003ור' שמעון בן לקיש אמר: מנחת העומר שקמצה שלא לשמה\u0004 — \u0003כשירה,\u0004 ומקטיר את קומצה, \u0003ו\u0004אולם \u0003שיריה אין נאכלין\u0004 לכהנים, משום איסור \"חדש\", \u0003עד שתביא מנחת העומר אחרת\u0004 באותו יום \u0003ותתירנה.\u0004","ושואלים: וכיון \u0003ששיריה אין נאכלין עד שתביא מנחת העומר אחרת,\u0004 הקומץ של מנחה זו עצמה \u0003מקרב היכי\u0004 \u0005[ליקרב כיצד היא]\u0006 \u0003קרבה?\u0004 הלא נאמר: \u0003\"ממשקה ישראל\u0004 למנחה ולעולה ולשלמים\" (יחזקאל מה, טו), לומר שאין מקריבים קרבן לגבוה אלא \u0003מן המותר לישראל,\u0004 ולפני הקרבת העומר התבואה אינה מותרת לישראל!","\u0003אמר רב אדא בר אהבה, קסבר\u0004 \u0005[סבור]\u0006 \u0003ריש לקיש: אין\u0004 בקרבנות \u0003מחוסר זמן לבו ביום,\u0004 אלא, הואיל ובו ביום יהיה החדש מותר, הריהי כשרה להקרבה כבר עכשיו.","על הסבר זה \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אדא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יצחק\u0004 ממה ששנינו בברייתא: \u0003יש בעופות שאין במנחות, יש במנחות שאין בעופות.\u0004 ומפרטים: \u0003יש בעופות\u0004 שאין במנחות — \u0003שהעופות באין בנדבת שנים,\u0004 ששני אנשים יכולים להתנדב בשותפות קרבן מן העוף, \u0003אבל\u0004 לגבי \u0003מנחות \"נפש\" כתיבא\u0004 \u0005[נאמר]\u0006 בהן (\"ונפש כי תקריב קרבן מנחה\", ויקרא ב, א), לומר שרק אדם יחיד (\"נפש\") מביא קרבן מנחה.","\u0003ו\u0004עוד, ש\u0003מחוסרי כפרה,\u0004 שהם \u0003זב וזבה יולדת ומצורע,\u0004 הצריכים להביא קרבן לגמר כפרתם — מביאים קרבן מן העוף, אבל אין בקרבנם מנחה.","\u0003ו\u0004כן \u0003הותרו\u0004 העופות \u0003מכלל איסורן בקודש,\u0004 שמליקה בעוף חולין עושה אותו נבילה האסורה באכילה, ובקדשים היא מכשירה את העוף להקרבה ולאכילה. \u0003מה שאין כן במנחות,\u0004 שאין במנחה דבר שאסור בחולין והותר איסורו בקודש.","\u0003ויש במנחות\u0004 מה שאין בעופות — \u0003שהמנחות טעונות כלי\u0004 לעבודתן, שצריך לתת את המנחה בכלי שרת, \u0003ו\u0004יש בהן שצריכות \u0003תנופה והגשה\u0004 לקרן המזבח, \u0003וישנן בציבור כביחיד,\u0004 שכמו שיש מנחות של יחיד כך יש מנחות של ציבור (העומר, שתי הלחם ולחם הפנים), \u0003מה שאין כן בעופות,\u0004 שאין בעבודתם כלי שרת, ואין בהם תנופה או הגשה, ואין קרבן ציבור מן העוף.","\u0003ואם איתא\u0004 \u0005[יש,\u0006 נכון הדבר\u0005]\u0006 שמנחת העומר שנקמצה שלא לשמה כשרה מיד להקטרה, הרי \u0003במנחות נמי משכחת לה\u0004 \u0005[גם כן מוצא אתה אותה]\u0006 ש\u0003הותרו\u0004 \u0003מכלל איסורן בקודש, ומאי ניהו\u0004 \u0005[ומה הן]?\u0006 \u0003מנחת העומר\u0004 שנקמצה שלא לשמה, שלמרות שהתבואה החדשה נאסרה להדיוט עד שתקרב מנחת העומר, מנחה זו מותרת בהקרבה!","ודוחים: \u0003כיון\u0004 ש\u0003אין מחוסר זמן לבו ביום, לאו איסורא\u0004 \u0005[לא איסור]\u0006 \u0003הוא\u0004 שהותר, אלא מתחילתה כשרה היא, כאילו כבר קרבה מנחת העומר האחרת.","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת\u0004 ממה ששנינו בענין טהרת המצורע: \u0003הקדים מתן שמן\u0004 על בהונות המצורע \u0003למתן דם\u0004 האשם על הבהונות, שלא כפי שאמרה התורה (ויקרא יד, יד— יז) — \u0003ימלאנו\u0004 את לוג ה\u0003שמן ויחזור ויתן שמן\u0004 על בהונות המצורע \u0003אחר מתן דם.\u0004 הקדים \u0003מתן בהונות\u0004 מן השמן \u0003למתן שבע\u0004 הזאות השמן לפני ה' — \u0003ימלאנו שמן ויחזור ויתן מתן בהונות אחר מתן שבע.\u0004","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003אין מחוסר זמן לבו ביום, אמאי\u0004 \u0005[מדוע]\u0006 אם שינה את הסדר \u0003יחזור ויתן? מאי דעבד עבד\u0004 \u0005[מה שעשה עשה],\u0006 שהרי כבר מתחילת היום היה ראוי להעשות!","\u0003אמר רב פפא: שאני\u0004 \u0005[שונים]\u0006 \u0003הלכות מצורע, דכתיבא בהו\u0004 \u0005[שנאמרה בהם]\u0006 לשון \u0003הוייה,\u0004 ש\u0003אמר הכתוב: \"זאת תהיה תורת המצורע\"\u0004 (שם), \u0003\"תהיה\"\u0004 — \u0003בהוייתה תהא,\u0004 ואסור לשנות מן הסדר.","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב פפא\u0004 ממה ששנינו: \u0003הקדים\u0004 שחיטת \u0003חטאתו\u0004 של מצורע \u0003לאשמו,\u0004 שלא כראוי (ראה שם יג— יט) — \u0003לא יהיה אחר ממרס בדמה\u0004 של החטאת שלא יקרש, עד שישחט האשם ויזה מדמו, ואחר כן יזה דם החטאת. \u0003אלא תעובר צורתה\u0004 של החטאת, יניחנה עד למחר עד שתיפסל, \u0003ותצא לבית השריפה.\u0004 ואם אין מחוסר זמן לבו ביום, מדוע לא נראה את החטאת כאילו נשחטה לאחר האשם?","ותמהים: \u0003אמאי קא מותיב\u0004 \u0005[מדוע מקשה]\u0006 \u0003רב פפא? והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא הוא\u0004 ש\u0003אמר: שאני\u0004 \u0005[שונים]\u0006 \u0003הלכות מצורע דכתיבא בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003הוייה,\u0004 ולפיכך שינוי הסדר פוסל בהם! \u0003אלא\u0004 יש לומר כי \u0003רב פפא הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שהסדר מעכב בהלכות מצורע, אמורים דווקא ב\u0003עבודה,\u0004 אבל \u0003שחיטה לאו עבודה היא,\u0004 שאינה מעיקר עבודת הקרבן. \u0003ו\u0004לפיכך, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אין מחוסר זמן לבו ביום\u0004 — \u0003יהא אחר ממרס בדמה\u0004 של החטאת, \u0003ולקריב\u0004 \u0005[ושיקריב]\u0006 את ה\u0003אשם\u0004 שישחטנו ויזה מדמו, \u0003והדר ליקרב\u0004 \u0005[ואחר\u0006 כך \u0005יקריב]\u0006 את ה\u0003חטאת!\u0004","\u0003אלא אמר רב פפא: היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003ריש לקיש,\u0004 שמנחת העומר שנקמצה שלא לשמה כשירה להקרבה — לא מפני שאין מחוסר זמן לבו ביום, אלא מפני \u0003דקסבר\u0004 \u0005[שהוא סבור]\u0006 כי \u0003האיר מזרח,\u0004 כלומר, בוקרו של יום ששה עשר בניסן, \u0003מתיר\u0004 את התבואה החדשה, גם בלא הקרבת מנחת העומר, שכן \u0003ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 \u0003אפילו בזמן שבית המקדש קיים,\u0004"],["\u0003האיר מזרח מתיר.\u0004","ומעירים: \u0003והא\u0004 \u0005[ו\u0006דבר \u0005זה]\u0006 של \u0003ריש לקיש לאו בפירוש איתמר\u0004 \u0005[נאמר]\u0006 בשמו, \u0003אלא מכללא\u0004 \u0005[מכלל\u0006 הדברים\u0005]\u0006 \u0003איתמר\u0004 \u0005[נאמר],\u0006 שמתוך דבריו אפשר ללמוד שהוא סבור כך. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מביאין מנחת בכורים\u0004 כלומר, מנחות ובכורים, \u0003ומנחת בהמה\u0004 (מנחת נסכים, הבאה עם קרבן בהמה) מן התבואה החדשה \u0003קודם לעומר.\u0004 וטעם הדבר — משום \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהא הקרבן \u0003\"ממשקה ישראל\"\u0004 (יחזקאל מה, טו) — מן המותר לישראל, והתבואה החדשה עדיין לא הותרה, \u0003ואם הביא\u0004 — \u0003פסול.\u0004","וכן \u0003קודם לשתי הלחם\u0004 הבאים בחג השבועות \u0003לא יביא\u0004 מנחות וביכורים, \u0003משום דאיקרו\u0004 \u0005[ש\u0006שתי הלחם \u0005נקראו]\u0006 \u0003בכורים,\u0004 והם הראשית לכל הביכורים, \u0003ו\u0004מכל מקום \u0003אם הביא\u0004 — \u0003כשר.\u0004","\u0003ואמר ר' יצחק\u0004 שכך \u0003אמר ריש לקיש: לא שנו\u0004 שאם הביא מן החדש קודם לעומר שהוא פסול, \u0003אלא\u0004 כשהביא \u0003בארבעה עשר ובחמשה עשר\u0004 בניסן, \u0003אבל בששה עשר\u0004 בניסן, גם \u0003אם הביא\u0004 קודם לעומר — \u0003כשר; וקשיא לי\u0004 \u0005[\u0006והיה \u0005לי קשה]:\u0006 מדוע יהא מותר בששה עשר קודם לעומר? \u0003ליהוו\u0004 \u0005[שיהיו]\u0006 \u0003כמחוסר זמן! אלמא קסבר\u0004 \u0005[\u0006אלא \u0005מכאן ש\u0006ריש לקיש \u0005סבור]:\u0006 \u0003האיר המזרח מתיר,\u0004 ולכן אין זה מחוסר זמן.","לעיל הובאה דעת רב, שמנחת העומר שנקמצה שלא לשמה — פסולה, ודעת ריש לקיש, שהיא כשרה אלא שצריך מנחה אחרת להתיר את החדש. \u0003ו\u0004אילו \u0003רבא אמר: מנחת העומר שקמצה שלא לשמה\u0004 — \u0003כשירה, ושיריה נאכלין, ואינה צריכה מנחת העומר אחרת להתירה, שאין מחשבה\u0004 פסולה \u0003מועלת\u0004 (מועילה) לפסול \u0003אלא במי שראוי לעבודה, ובדבר הראוי לעבודה, ובמקום הראוי לעבודה.\u0004","ומפרטים: \u0003במי שראוי לעבודה\u0004 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003כהן בעל מום,\u0004 שפסול לעבודה, שאין מחשבתו פוסלת קרבן. \u0003ובדבר הראוי לעבודה\u0004 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מנחת העומר,\u0004 שהיא מנחה \u0003דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 בדרך כלל לעבודה, ש\u0003חדוש הוא\u0004 שמביאים קרבן מן השעורים. \u0003ובמקום הראוי לעבודה\u0004 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 עבודה שנעשתה במחשבת פסול כאשר \u0003נפגם המזבח,\u0004 שאינה פוסלת, ואם יתוקן המזבח בו ביום — ניתן להקריב את הקרבן.","ושבים לדון בענין האיסור להקריב לגבוה דברים האסורים להדיוט. \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 בתחילת פרשת העולה נאמר: \"מן הבהמה מן הבקר ומן הצאן תקריבו את קרבנכם\" (ויקרא א, ב), וחכמים דרשו \"מן הבקר\" כלשון מיעוט — להוציא את הנעבד לעבודה זרה, ומוסיפים: \u0003כשהוא אומר\u0004 שוב \u0003\"מן הבקר\" למטה\u0004 בהמשך \"אם עולה קרבנו מן הבקר\" (שם ג) — \u0003שאין תלמוד לומר,\u0004 כלומר, לכאורה לא הוצרכנו לכך, \u0003אלא\u0004 המיעוט \u0003להוציא את הטרפה,\u0004 ללמד שהיא פסולה להקרבה. ויש לתמוה: ומדוע הוצרכנו לכתוב?","\u0003והלא דין\u0004 (קל וחומר) \u0003הוא: ומה\u0004 בהמה \u0003בעל מום שמותרת להדיוט\u0004 — \u0003אסורה לגבוה\u0004 (ראה ויקרא כב, כ), \u0003טריפה שאסורה להדיוט\u0004 (שמות כב, ל) \u0003אין דין שאסורה לגבוה?\u0004 כנגד זה טוענים: \u0003חלב ודם יוכיחו, שאסורין להדיוט ו\u0004מכל מקום \u0003מותרין לגבוה!\u0004","ודוחים: \u0003מה לחלב ודם\u0004 שהם מותרים לגבוה, \u0003שכן\u0004 גם בהדיוט הם \u0003באין מכלל היתר,\u0004 שהרי הבהמה עצמה מותרת היא, \u0003תאמר בטריפה שכולה אסורה, ו\u0004אם כן \u0003לא תהא מותרת לגבוה!\u0004","ומשיבים: \u0003מליקה\u0004 בעוף \u0003תוכיח,\u0004 \u0003שכולה איסור ו\u0004היא \u0003אסורה להדיוט,\u0004 שעוף שנמלק מן העורף אסור באכילה, כנבילה, \u0003ו\u0004מכל מקום \u0003מותרת לגבוה,\u0004 שכך מקריבים קרבן מן העוף, ומשום כך הוצרכנו לכתוב לפסול טריפה.","ודוחים: אין מכאן ראיה, \u0003מה למליקה שכן קדושתה אוסרתה,\u0004 כלומר, רק \u0003בשעת קדושתה למזבח היא נאסרה להדיוט, דהיינו\u0004 בשעת \u0003מליקתה, אבל קודם לכן לא נאסרה להדיוט. מה שאין כן בטריפה, שאין קדושתה אוסרתה\u0004 להדיוט, אלא מעצמה היא אסורה, ואין לומר שתהיה מותרת לגבוה!","\u0003ואם השבתה,\u0004 כלומר, ואם מכל מקום תמצא דרך להשיב ולטעון שטריפה תהיה כשרה להקרבה, \u0003כשהוא אומר \"מן הבקר\" למטה\u0004 (ויקרא א, ג) \u0003שאין תלמוד לומר\u0004 כלומר, אין בו צורך לכאורה, אלא בא \u0003להוציא את הטריפה.\u0004 עד כאן לשון הברייתא.","ושואלים: \u0003מה \"אם השבתה\"\u0004 כלומר, מה היא אותה טענה שהוא מרמז לה, ואינו מפרשה? לשאלה זו נתנו תשובות אחדות \u0003(סימן: רקיח מר אדא לשישי\"ה)\u0004.","\u0003אמר רב, משום דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003מנחת העומר תוכיח, ש\u0004היא \u0003אסורה להדיוט\u0004 ככל תבואה חדשה, \u0003ומותרת לגבוה,\u0004 ומכאן נלמד לטריפה, לכך הוצרכנו לכתוב האוסר טריפה בהקרבה. ופורכים את הטענה: \u0003מה למנחת העומר\u0004 שהיא מותרת לגבוה, \u0003שכן\u0004 היא \u0003מתרת\u0004 את ה\u0003חדש,\u0004 מה שאין כן טריפה!","ומשיבים: מנחת העומר \u0003בשביעית\u0004 אינה מתירה את החדש, שהרי אסור לזרוע ואין תבואה, ומכל מקום היא מותרת! ודוחים: ב\u0003שביעית נמי\u0004 \u0005[גם כן]\u0006 יש במנחת העומר צד היתר, \u0003שכן\u0004 היא \u0003מתרת ספיחין\u0004 שצמחו מעצמם בלא זריעה \u0003בשביעית!\u0004 ומשיבים: מכל מקום, \u0003כ\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר: ספיחין אסורים בשביעית\u0004 הרי אינה מתרת כלל, ומכל מקום היא מותרת לגבוה, ולכן הוצרך הכתוב לאסור את הטריפה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בר אבא לרב אשי, לר' עקיבא נמי\u0004 \u0005[גם כן]\u0006 \u0003לפרוך\u0004 \u0005[נפרוך]\u0006 את הטענה כך: \u0003מה למנחת העומר\u0004 שהיא מותרת לגבוה, \u0003שכן\u0004 היא \u0003מתרת חדש בחוצה לארץ,\u0004 ששם אין איסור שביעית!","\u0003ואפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]:\u0006 איסור \u0003חדש בחוץ לארץ לאו דאורייתא\u0004 \u0005[אינו מן התורה],\u0006 ואינה מתירה כלל את החדש בשביעית, אפשר לפרוך בדרך אחרת: מה למנחת העומר \u0003שכן\u0004 היא \u0003באה להתיר לאו שבתוכה,\u0004 שהקטרת הקומץ מתירה את השיריים באכילה לכהנים, מה שאין כן טריפה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא:\u0004 אין זו פירכה, כי \u0003אי הכי\u0004 \u0005[אם כך],\u0006 לפי סברה זו יש לומר כי \u0003טריפה נמי\u0004 \u0005[גם כן]\u0006 \u0003תקריב ותתיר לאו שבתוכה,\u0004 כדי להתיר את בשרה באכילה לכהנים, ולכן הוצרך הכתוב לאוסרה בהקרבה! \u0003אלא פריך הכי\u0004 \u0005[פרוך כך]:\u0006 \u0003מה למנחת העומר\u0004 שהיא מותרת לגבוה, \u0003שכן מצותה בכך,\u0004 שהתורה ציותה להביא אותה כדי להתיר את החדש. מה שאין כן בטריפה, שאין מצוה בהקרבתה.","\u0003ריש לקיש אמר:\u0004 הטענה שיש להשיב כדי להתיר טריפה בהקרבה היא \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003מפטם הקטרת יוכיח, שאסור להדיוט ומותר לגבוה,\u0004 ולכן הוצרכנו לכתוב לאסור את הטריפה בהקרבה. ותוהים על הלשון: \u0003מפטם גברא\u0004 \u0005[איש]\u0006 \u0003הוא!\u0004","\u0003אלא\u0004 הכוונה היא: \u0003פטום הקטרת יוכיח, שאסור להדיוט\u0004 לרקוח קטורת כמו זו של המקדש (שמות ל, לז), \u0003ומותר לגבוה.\u0004 ודוחים: אין זו טענה, \u0003מה לפטום הקטרת\u0004 שהוא מותר לגבוה, \u0003שכן מצותו בכך,\u0004 מה שאין כן בטריפה!","\u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא אמר\u0004 הסבר אחר, \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003שבת תוכיח, ש\u0004היא \u0003אסורה\u0004 במלאכה \u0003להדיוט ומותרת לגבוה\u0004 בעבודת הקרבנות, והוא הדין לטריפה שתהא מותרת לגבוה, ולכן הוצרך הכתוב לאוסרה.","ודוחים: \u0003מה לשבת\u0004 שהותרה לגבוה, \u0003שכן הותרה מכללה\u0004 גם \u0003אצל הדיוט במילה,\u0004 שהרי מצוה למול בזמנו אף בשבת, למרות שהיא מלאכה!","ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003מילה צורך הדיוט הוא\u0004 שאתה טוען שהותרה אצלו? הלוא \u0003מילה מצוה היא! אלא\u0004 כך יש לדחות: \u0003מה לשבת\u0004 שהותרה לגבוה \u0003שכן מצותה בכך,\u0004 שהתורה ציותה על עבודת הקרבנות בשבת, מה שאין כן בטריפה.","\u0003רב אדא בר אבא אמר\u0004 הסבר נוסף, \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003כלאים תוכיח, שאסורין להדיוט\u0004 בלבישה \u0003ו\u0004מכל מקום \u0003מותרין לגבוה,\u0004 שבאבנט של הכהן יש כלאים. והוא הדין לטריפה, שתהיה מותרת לגבוה, ולכן הוצרך הכתוב לאוסרה.","ודוחים: \u0003מה לכלאים\u0004 שהותרו לגבוה, \u0003שכן הותרו מכללן אצל הדיוט בציצית,\u0004 שנותנים פתיל תכלת של צמר אף בציציות של פשתן! ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ציצית צורך הדיוט היא,\u0004 שאתה אומר שהותרה אצלו? והלוא \u0003מצוה היא! אלא\u0004 כך יש לדחות:"],["\u0003מה לכלאים שמצותו בכך!\u0004","\u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אמר,\u0004 כך יש להסביר את הטענה המרומזת, שיש סברה להתיר טריפה בהקרבה: \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר],\u0006 \u0003ליהדר דינא\u0004 \u0005[יחזור הדין]\u0006 \u0003ותיתי\u0004 \u0005[ותבוא,\u0006 ותילמד ההלכה\u0005]\u0006 \u0003ב\u0004שיטת הלימוד \u0003\"מה הצד\":\u0004 כלפי הטענה \u0003מה למליקה\u0004 שאין ללמוד ממנה להכשיר את הטריפה, \u0003שכן קדושתה אוסרתה,\u0004 יש להשיב: \u0003חלב ודם\u0004 \u0003יוכיחו,\u0004 שלא קדושתם אוסרת אותם להדיוט, ובכל זאת מותרים לגבוה.","ואם תאמר: \u0003מה לחלב ודם שכן באים מכלל היתר,\u0004 שהבהמה עצמה מותרת להדיוט — \u0003מליקה תוכיח,\u0004 שאינה באה מכלל היתר.","\u0003וחזר הדין, לא ראי זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן\u0004 — \u0003שאסורין להדיוט ומותרין לגבוה, אף אני אביא טרפה\u0004 — \u0003אף על פי שאסורה להדיוט תהא מותרת לגבוה,\u0004 ולכך הוצרך הכתוב לאסור טריפה בהקרבה. ודוחים: אין זו טענה, שכן \u0003מה להצד השוה שבהן\u0004 שהותרו לגבוה, \u0003שכן\u0004 עיקר \u0003מצותה בכך!\u0004","\u0003אלא אמר רב אשי,\u0004 הוצרכנו לכתוב האוסר טריפה בהקרבה \u0003משום דאיכא למימר\u0004 \u0005[שיש לומר]:\u0006 \u0003מעיקרא דדינא פרכא\u0004 \u0005[מעיקרו של הדין,\u0006 הלימוד, \u0005מופרך הוא],\u0006 שכן מתחילה \u0003מהיכא קא מייתית לה\u0004 \u0005[מהיכן אתה מביא,\u0006 רוצה ללמוד \u0005אותה]\u0006 לפסול את הטריפה — בקל וחומר \u0003מבעל מום\u0004 שמותר להדיוט ואסור לגבוה, וכל שכן טריפה שאסורה להדיוט.","ואולם \u0003מה לבעל מום\u0004 שיש בו חומרה יתירה, \u0003שכן עשה בו מקריבין כקריבין,\u0004 שהרי המום פוסל את הכהן המקריב כדרך שהוא פוסל את הקרבן (ראה ויקרא פרק כב), מה שאין כן טריפה, שהרי כהן שהוא טריפה כשר לעבודה. ולכן הוצרך הכתוב לאסור את הטריפה בהקרבה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא סבא לרב אשי:\u0004 והרי \u0003יוצא דופן\u0004 (הנולד בניתוח דרך דופן הרחם) \u0003יוכיח, שלא עשה בו מקריבין כקריבין,\u0004 שבהמה יוצאת דופן פסולה להקרבה, ואילו כהן יוצא דופן כשר לעבודה, \u0003ו\u0004הוא \u0003מותר להדיוט\u0004 באכילה \u0003ואסור לגבוה,\u0004 ומכאן יש ללמוד בקל וחומר לטריפה האסורה להדיוט שתהא אסורה לגבוה. ואם כן לא הוצרכנו לכתוב כדי לאוסרה!","השיב לו רב אשי, יש לדחות: \u0003מה ליוצא דופן,\u0004 שיש בו צד פסול למזבח, \u0003שכן אינו קדוש בבכורה,\u0004 אבל טריפה קדושה בבכורה, ולכן הוצרך הכתוב לאוסרה.","וכנגד זה יש לטעון: \u0003בעל מום יוכיח\u0004 שקדוש בבכורה, ומותר להדיוט ואסור לגבוה! ואם תאמר: \u0003מה לבעל מום שכן עשה בו מקריבין כקריבין\u0004 — \u0003יוצא דופן יוכיח\u0004 שלא עשה בו מקריבים כקריבים.","\u0003וחזר הדין, לא ראי זה כראי זה ולא ראי זה כראי זה, הצד השוה שבהן\u0004 — \u0003שמותרין להדיוט ואסורים לגבוה, וכל שכן טרפה שאסורה להדיוט תהא אסורה לגבוה,\u0004 ואם כן לא הוצרך הכתוב לאוסרה!","אלא שיש להשיב על כך: \u0003מה להצד השוה שבהן שכן לא הותרו מכללן,\u0004 שהאיסור שבשני אלה (יוצא דופן ובעל מום) אין לו היתר בשום מקרה, \u0003תאמר בטריפה שהותרה מכללה,\u0004 ולכן הוצרך הכתוב לאסור את הטריפה בהקרבה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: טרפה שהותרה מכללה מאי\u0004 \u0005[מה]\u0006 \u0003היא? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003מליקה\u0004 של \u0003עולת העוף לגבוה,\u0004 שכאשר מולקים את העוף הריהו נעשה טריפה תחילה, קודם עיקר המליקה, ולמרות זאת הוא קרב על המזבח — והלוא \u0003בעל מום נמי\u0004 \u0005[גם כן]\u0006 \u0003בעופות אשתרויי אשתרי\u0004 \u0005[מותר הוא\u0006 מכללו לגבוה\u0005],\u0006 שהרי כלל בידינו: יש דין \u0003תמות\u0004 (שיהיה הקרבן תמים בלי מום) \u0003וזכרות\u0004 (בקרבנות שבאים רק ממין זכר) \u0003בבהמה, ואין\u0004 דין \u0003תמות וזכרות בעופות!\u0004","\u0003אלא\u0004 תאמר שטריפה שהותרה מכללה היא \u0003מליקה\u0004 של \u0003חטאת העוף\u0004 שהותרה \u0003לכהנים,\u0004 שהרי בדרך כלל רק שחיטה (בסכין ומן הצואר) מתירה את העוף באכילה — אינך יכול לטעון כן, שהרי \u0003כהנים משולחן גבוה קא זכו\u0004 \u0005[הם זוכים],\u0006 ממה שהותר בהקרבה למזבח, ואם כן גם בענין זה אין הבדל בין בעל מום לטריפה, שהרי גם מליקה של חטאת העוף וגם בעל מום בעוף הותרו מכללם למזבח. ונמצא שהקל וחומר במקומו עומד, ולא הוצרכנו לכתוב כדי לאסור את הטריפה!","\u0003ואלא פריך הכי\u0004 \u0005[יש לפרוך כך]:\u0006 \u0003מה להצד השוה שבהן\u0004 בבעל מום ויוצא דופן \u0003שכן מומן ניכר, תאמר בטריפה שכן אין מומה ניכר! משום הכי איצטריך קרא\u0004 \u0005[משום כך הוצרך המקרא]\u0006 \"מן הבקר\" (ויקרא א, ב) למעט טריפה מהקרבה. עד כאן עסקנו בבירור דברי הברייתא, לפיה למדנו פסול טריפה למזבח מ\"מן הבקר\".","ושואלים: \u0003וטריפה\u0004 שאסורה בהקרבה \u0003מהכא נפקא\u0004 \u0005[מכאן יוצאת,\u0006 נלמדת\u0005]?\u0006 הלוא \u0003מהתם נפקא\u0004 \u0005[משם יוצאת,\u0006 נלמדת\u0005]\u0006 שנאמר: \u0003\"ממשקה ישראל\u0004 למנחה ולעולה ולשלמים\" (יחזקאל מה, טו) — שמקריבים לקרבן רק \u0003מן המותר לישראל!\u0004","ועוד, \u0003מ\u0004מה שנאמר במעשר בהמה: \u0003\"כל אשר יעבור תחת השבט\u0004 העשירי יהיה קדש לה' \" (ויקרא כז, לב) \u0003נפקא\u0004 \u0005[\u0006היא \u0005יוצאת,\u0006 נלמדת\u0005]\u0006 — \u0003פרט לטריפה\u0004 שאינו רשאי להקריבה, לפי \u0003שאינה עוברת\u0004 בגלל חולשתה, ומשם למדנו לשאר קרבנות!","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 כל המקראות הללו, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מ\"משקה ישראל\" הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 יש בזה \u0003למעוטי\u0004 \u0005[למעט]\u0006 ולאסור טריפה דווקא \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא היתה לה\u0004 \u0003שעת הכושר,\u0004 וכגון שנולדה כשהיא טריפה, ולא היתה ראויה מעולם להקרבה, והוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003ערלה וכלאי הכרם\u0004 שאיסורם נלמד בפסוק זה. \u0003אבל\u0004 טריפה ש\u0003היתה לה שעת הכושר אימא תתכשר\u0004 \u0005[אמור שתהא כשרה],\u0006 על כן הוצרכנו למה ש\u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"כל אשר יעבור\",\u0004 ומשמע: כל שאינה עוברת עכשיו, ואפילו היתה ראויה לכך מתחילתה.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005כותבת התורה]\u0006 רק \u0003\"כל אשר יעבור\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 הרי זה בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 ולאסור בהקרבה רק \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003נטרפה ולבסוף הקדישה, דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מעשר\u0004 בהמה, שהרי בפסוק זה נאסר להקדיש טריפה. \u0003אבל הקדישה ולבסוף נטרפה, דבעידנא דאקדשה הוה חזיא\u0004 \u0005[שבזמן שהקדישה היתה ראויה]\u0006 \u0003אימא תתכשר\u0004 \u0005[אמור שתהא כשרה],\u0006 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם \u0003\"מן הבקר\",\u0004 ולפיכך כל המקראות הללו \u0003צריכי\u0004 \u0005[צריכים\u0006 להיאמר\u0005].\u0006","\u0003אחד מנחת חוטא ואחד כל המנחות\u0004 הטעונות קמיצה, \u0003שקמצן זר\u0004 שאינו כהן, או כהן \u0003אונן\u0004 ביום שמת אחד מקרוביו, או כהן \u0003טבול יום\u0004 שטבל באותו יום לטומאתו, שאינו טהור לגמרי עד שתשקע השמש, או \u0003מחוסר בגדים\u0004 שלא היו עליו כל בגדי הכהונה, או \u0003מחוסר כיפורים\u0004 כגון זב או מצורע שנטהר ועדיין לא הביא קרבנו, וכן כהן \u0003שלא רחץ ידיו ורגליו\u0004 מן הכיור קודם העבודה, או \u0003ערל,\u0004 או \u0003טמא,\u0004 או שקמץ כשהוא \u0003יושב,\u0004 או \u0003עומד על גבי כלים,\u0004 או \u0003על גבי בהמה,\u0004 או \u0003על גבי רגלי חבירו\u0004 — \u0003פסול.\u0004","\u0003קמץ בשמאל\u0004 — \u0003פסול, בן בתירא אומר: יחזיר\u0004 הקומץ לכלי, \u0003ויחזור ויקמוץ בימין.\u0004","\u0003קמץ ועלה בידו\u0004 עם סולת המנחה \u0003צרור\u0004 אבן, \u0003או גרגר מלח, או קורט\u0004 (חתיכה קטנה) \u0003של לבונה\u0004 — \u0003פסול, מפני שאמרו: הקומץ היתר והחסר\u0004 — \u0003פסול,\u0004 ואם יש בו צרור וכו' הקומץ חסר ממידתו הראויה. \u0003ואיזהו\u0004 הקומץ \u0003היתר\u0004 — \u0003שקמצו מבורץ,\u0004 גדוש יותר מכפי מידתו, באופן שאצבעותיו אינן מכילות את הסולת, \u0003וחסר\u0004 — \u0003שקמצו בראשי אצבעותיו.\u0004","על לשון המשנה שואלים: \u0003למה לי למתנא\u0004 \u0005[לשנות]:\u0006 \u0003אחד מנחת חוטא ואחד כל המנחות\u0004 שקמצן זר ואונן? \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003כל המנחות שקמצן זר ואונן!\u0004","ומשיבים: \u0003לר' שמעון איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון: בדין הוא שתהא מנחת חוטא טעונה שמן ולבונה\u0004 כשאר מנחות, כדי \u0003שלא יהא חוטא נשכר,\u0004 \u0003ומפני מה אינה טעונה\u0004 שמן ולבונה? כדי \u0003שלא יהא קרבנו מהודר; ו\u0004כן \u0003בדין הוא שתהא חטאת חלב\u0004 (הבאה על חטא) \u0003טעונה נסכים,\u0004"],["\u0003שלא יהא חוטא נשכר, ומפני מה אינה טעונה? שלא יהא קרבנו מהודר. סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל ואמר ר' שמעון:\u0004 היקל הכתוב במנחת חוטא \u0003שלא יהא קרבנו מהודר,\u0004 אם כן \u0003כי קמצי לה\u0004 \u0003פסולין נמי תתכשר\u0004 \u0005[כאשר קומצים אותה פסולים גם כן תהא כשרה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 התנא בלשון \"אחד מנחת חוטא ואחד כל המנחות\" שאין הדבר כן.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 לגבי זבחים, שהתנא שונה: \"כל הזבחים שקיבל דמם זר וכו' פסולים\", \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003אחד חטאת חלב ואחד כל הזבחים שקבלו דמן זר ואונן\u0004 פסולים, \u0003ולימא\u0004 \u0005[ונאמר]:\u0006 \u0003לר' שמעון אצטריך\u0004 \u0005[הוצרך]\u0006 להשמיענו שלמרות שהיקל הכתוב בחטאת חלב שלא יהא קרבנו מהודר, מכל מקום אם קיבלו פסולים את דמה הריהי פסולה!","\u0003אלמא\u0004 \u0005[אלא]\u0006 אנו מניחים כי \u0003כיון דתנא ליה\u0004 \u0005[ששנה לו]\u0006 בלשון \u0003\"כל\" ולא קתני\u0004 \u0005[ואינו שונה]\u0006 \u0003\"חוץ\"\u0004 — \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003משמע,\u0004 וגם לשיטת ר' שמעון אין צורך בהדגשה מיוחדת, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין מנחות, \u0003כיון דתנא\u0004 \u0005[ששנה]\u0006 \u0003\"כל\" ולא קתני\u0004 \u0005[ואינו שונה]\u0006 \u0003\"חוץ\"\u0004 — \u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003משמע,\u0004 וגם מנחת חוטא!","ומתרצים: מכל מקום, כאן לענין מנחות \u0003אצטריך\u0004 \u0005[הוצרך]\u0006 הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואוקימנא לרישא\u0004 \u0005[והעמדנו את ההתחלה,\u0006 את המשנה הקודמת\u0005]\u0006 ששנינו בה שכל המנחות שקמצן שלא לשמן לא עלו לבעליהן, ש\u0003לא כ\u0004שיטת \u0003ר' שמעון,\u0004 אם כן \u0003סיפא נמי\u0004 \u0005[סופה,\u0006 משנתנו, \u0005גם כן]\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' שמעון\u0004 היא, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבזה גם ר' שמעון מודה.","\u0003אמר רב: זר שקמץ\u0004 — \u0003יחזיר.\u0004 ותוהים: \u0003והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003פסל תנן\u0004 \u0005[שנינו]\u0006 במשנה! ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003פסל? פסל עד שיחזיר\u0004 את הקומץ למנחה, ויחזור כהן ויקמוץ.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו\u0004 \u0005[הרי זו]\u0006 בדיוק שיטת \u0003בן בתירא\u0004 במשנתנו, ששנה בענין קמיצה בשמאל, שיחזיר ויחזור ויקמוץ בימין! ומשיבים: \u0003אי דאיתיה\u0004 \u0005[אם שישנו]\u0006 \u0003לקומץ בעיניה\u0004 \u0005[בעינו,\u0006 כמות שהוא\u0005]\u0006 \u0003לא פליגי רבנן עליה\u0004 \u0005[לא חלוקים חכמים על]\u0006 שיטתו של \u0003בן בתירא, כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה במקרה ש\u0003חסר\u0004 ה\u0003קומץ, רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003לא יביא\u0004 סולת \u0003מתוך ביתו וימלאנו\u0004 את הכלי, ואילו \u0003בן בתירא סבר\u0004 \u0005[סבור]:\u0006 \u0003יביא מתוך ביתו וימלאנו.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מסביר, הרי לשון המשנה, \u0003בן בתירא אומר: יחזיר ויחזור ויקמוץ בימין,\u0004 אינה מדוייקת, אלא \u0003בן בתירא אומר: יחזיר ויביא מתוך ביתו וימלאנו, ויחזור ויקמוץ בימין, מיבעי ליה\u0004 \u0005[הוצרך לו]\u0006 לשנות!","אלא צריך לתרץ בדרך אחרת: \u0003כי קא\u0004 \u0003אמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 שאם קמץ הזר יחזיר, הרי זה דווקא \u0003ל\u0004שיטת \u0003בן בתירא.\u0004 ותוהים: והלוא \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003עד כאן לא\u0004 שמענו ש\u0003קא מכשר\u0004 \u0005[מכשיר]\u0006 \u0003בן בתירא אלא\u0004 בקומץ \u0003בשמאל, אבל בשאר פסולין לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב, שהוא הדין גם לשאר פסולים האמורים במשנה, שניתן להחזיר ולקמוץ.","ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 קומץ \u0003שמאל,\u0004 שהיה מקום לומר שדווקא יכשיר בן בתירא — \u0003דאשכחן לה הכשירא\u0004 \u0005[\u0006מפני \u0005שמצאנו לה,\u0006 לשמאל \u0005הכשר]\u0006 \u0003ביום הכפורים,\u0004 שהכהן הגדול אוחז את כף הקטורת ביד שמאל כשהוא נכנס לקדש הקדשים, והלוא \u0003זר נמי\u0004 \u0005[גם כן]\u0006 \u0003אשכחן לה הכשירא\u0004 \u0005[מצאנו לו הכשר]\u0006 \u0003בשחיטה,\u0004 ששחיטת הקרבן כשרה בזר, ומדוע לא שנה בו בן בתירא שיחזיר ויקמוץ בכשרות!","ודוחים: \u0003שחיטה לאו עבודה היא,\u0004 ומשום כך היא כשרה בזר, ולא היינו באים ללמוד מכאן להכשיר זר בקמיצה, שהיא עבודת כהונה.","ומקשים: \u0003ולא?\u0004 וכי אין השחיטה עבודה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' זירא אמר רב: שחיטת פרה\u0004 אדומה \u0003בזר\u0004 — \u0003פסולה, ואמר רב עלה\u0004 \u0005[עליה]\u0006 בטעם הדבר: שהרי נזכר בה \u0003אלעזר\u0004 הכהן (במדבר יט, ג), \u0003ו\"חוקה\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 (שם ב), ובמקום שכתוב \"חוקה\" הרי זה לעכב! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה,\u0004 ש\u0003קדשי בדק הבית היא\u0004 ולא קדשי מזבח, כלומר, אין לה דינים של קרבן.","ותמהים: \u0003ולאו כל דכן הוא\u0004 \u0005[ולא כל שכן הוא]?\u0006 אם \u0003קדשי בדק הבית בעו\u0004 \u0005[צריכים]\u0006 \u0003כהונה, קדשי מזבח לא בעו\u0004 \u0005[אינם צריכים]\u0006 \u0003כהונה?! אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 אין בכך קושי, ויש להבין את עניינה של שחיטת פרה בכהן \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 לענין \u0003מראות נגעים\u0004 (ראיית נגעי הצרעת לטמא ולטהר), \u0003דלאו עבודה נינהו\u0004 \u0005[שאינם עבודה]\u0006 \u0003ובעי\u0004 \u0005[וצריכים]\u0006 \u0003כהונה.\u0004 ומקשים: מכל מקום, מדוע הוצרך רב לומר שקמיצה בזר אינה פוסלת?","\u0003ונילף\u0004 \u0005[ונלמד]\u0006 \u0003מבמה\u0004 שהקריבו עליה קודם שהוקם המקדש, ושם הזר כשר לעבודה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003מבמה\u0004 למקדש \u0003לא ילפינן\u0004 \u0005[אין אנו למדים],\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003מנין ליוצא\u0004 כגון איברי קרבן עולה שיצאו חוץ לעזרה ונפסלו להקרבה, \u0003שאם עלה\u0004 למזבח \u0003לא ירד\u0004 — \u0003שהרי יוצא כשר בבמה!\u0004","ודוחים: ה\u0003תנא\u0004 על הכתוב \u0003\"זאת תורת העלה\"\u0004 (ויקרא ו, ב) \u0003סמיך ליה\u0004 \u0005[הוא סומך],\u0006 המלמד שכל שעלה למזבח (אפילו הוא פסול) כיון שעלה לא ירד, וההשוואה לבמה אינה מקור לדין, אלא רק סימן לדבר.","ושואלים עוד: \u0003אלא טעמא דאשמעינן\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שהשמיע לנו]\u0006 \u0003רב\u0004 שקמיצת הזר אינה פוסלת את המנחה, יודעים אנו שכך היא דעת בן בתירא, \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 אם \u0005לא\u0006 היה אומר \u0005כך]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003בשאר פסולין\u0004 חוץ מקמיצה בשמאל \u0003פסל בן בתירא? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה ור' אלעזר בר' שמעון אומרים: מכשיר היה בן בתירא בכל הפסולין כולן!\u0004","\u0003ותניא\u0004 \u0005[ו\u0006עוד \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \"והביאה אל בני אהרן הכהנים \u0003וקמץ משם\"\u0004 (שם ב, ב) — \u0003ממקום שרגלי הזר עומדות,\u0004 שאין הקמיצה צריכה להיעשות במקום מסויים בעזרה, אלא גם במקום שהזר נכנס אליו ומביא את מנחתו.","\u0003בן בתירא אומר,\u0004 כך יש לדרוש כתוב זה: \u0003מנין שאם קמץ בשמאל, שיחזיר\u0004 את הקומץ למנחה \u0003ויחזור ויקמוץ בימין? תלמוד לומר: \"וקמץ משם\"\u0004 — \u0003ממקום שקמץ כבר,\u0004 מן המנחה, משם חוזר וקומץ.","\u0003וכיון דקרא סתמא כתיב בה\u0004 \u0005[שהמקרא בסתם נאמר בו],\u0006 שיכול להחזיר את הקומץ למנחה ולחזור ולקמוץ, \u0003מה לי\u0004 אם קמץ מתחילה ב\u0003שמאל ומה לי שאר הפסולין?\u0004","\u0003אלא\u0004 יש לומר כי \u0003הא קמשמע לן\u0004 \u0005[\u0006חידוש \u0005זה השמיע לנו]\u0006 \u0003רב:\u0004 לדעת בן בתירא, לא רק אם קמץ הזר אינו פוסל את המנחה, אלא \u0003קמץ ואפילו קידש\u0004 את הקומץ בכלי שרת. \u0003ולאפוקי מהני תנאי\u0004 \u0005[ולהוציא\u0006 מדברי \u0005תנאים אלה]\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בן יוסי בן יאסיין ור' יהודה הנחתום אמרו: במה דברים אמורים\u0004 שבן בתירא מכשיר — במקרה \u0003שקמץ\u0004 הפסול \u0003ולא קידש, אבל\u0004 אם גם \u0003קידש\u0004 — \u0003פסל\u0004 לדברי הכל, ולא יועיל להחזיר את הקומץ למנחה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 להיפך, שדבר זה בא רב להשמיע: דווקא אם \u0003קמץ\u0004 הפסול — \u0003אין\u0004 \u0005[כן],\u0006 מכשיר בן בתירא אם יחזיר את הקומץ למנחה, אבל אם כבר \u0003קידש\u0004 את הקומץ בכלי שרת — \u0003לא, כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]?\u0006 \u0003כ\u0004דעת \u0003הני תנאי\u0004 \u0005[תנאים אלה],\u0006 ר' יוסי בן יוסי בן יאסיין ור' יהודה הנחתום, \u0003ולאפוקי מתנא קמא\u0004 \u0005[ולהוציא מ\u0006דברי \u0005התנא הראשון]\u0006 באותה ברייתא, שסבור כי גם אם קידש את הקומץ בכלי — יחזיר, שלא נפסל בכך.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: מאי קא סברי הני תנאי\u0004 \u0005[מה סבורים תנאים אלו]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 לדעתם \u0003קמיצת פסולין עבודה היא,\u0004 שיפסול \u0003אף על גב דלא עביד ליה\u0004 \u0005[אף על פי שלא עושה לו]\u0006 לקומץ \u0003מתן כלי!\u0004 \u0003אי\u0004 \u0005[אם]\u0006 \u0003קמיצת פסולין לאו\u0004 \u0005[לא]\u0006 \u0003עבודה היא, כי עבד\u0004 \u0005[כאשר עשה]\u0006 \u0003לה מתן כלי מאי הוה\u0004 \u0005[מה הוא]\u0006 מה בכך? מדוע לא יוכל להחזירו לכלי?","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רב נחמן:\u0004 יש לומר כי \u0003לעולם עבודה היא,\u0004 \u0003ו\u0004אולם \u0003לא גמרה\u0004 \u0005[נגמרת]\u0006 \u0003עבודתה עד דעביד\u0004 \u0005[שעושה]\u0006 \u0003לה מתן כלי,\u0004 ורק באותה שעה הוא פוסל.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמתן בכלי גומר את עבודת הקמיצה בפסול, יפסול \u0003אפילו\u0004 קמץ ו\u0003לא קידש\u0004 את הקומץ בכלי המיוחד לכך,"],["\u0003וכי מהדר ליה לקומץ לדוכתיה\u0004 \u0005[וכאשר מחזיר\u0006 הפסול \u0005את הקומץ\u0006 \u0005למקומו]\u0006 לכלי שבו המנחה — \u0003תקדוש\u0004 \u0005[שיתקדש]\u0006 הקומץ, שהרי ניתן בכלי שרת, \u0003ולפסול\u0004 \u0005[ויפסול],\u0006 שהרי נגמרה הקמיצה בפסול!","\u0003אמר ר' יוחנן, זאת אומרת: כלי שרת אין מקדשין\u0004 את הניתן בהם \u0003אלא מדעת,\u0004 וכשמחזיר הפסול את הקומץ למנחה אינו נותן את הקומץ בכלי כדי לקדשו, ולכן אינו פוסל.","ומתקשים, מכלל הדברים אתה למד: \u0003הא\u0004 \u0005[אבל]\u0006 אם נתן בהם דברים \u0003מדעת מקדשין? והא בעא מיניה\u0004 \u0005[והרי שאל ממנו]\u0006 \u0003ריש לקיש מר' יוחנן: כלי שרת מהו שיקדשו\u0004 את ה\u0003פסולין\u0004 הניתנים בהם \u0003לכתחילה ליקרב\u0004 על המזבח? \u0003ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מקדשין!\u0004 ומתרצים, כך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין מקדשין\u0004 את הפסולים הניתנים בהם \u0003ליקרב,\u0004 \u0003אבל מקדשין\u0004 אותם \u0003ליפסל.\u0004","\u0003רב עמרם אמר:\u0004 גם אם כלי שרת מקדשים שלא מדעת, ייתכן שיחזיר את הקומץ בלא שיתקדש בכלי — \u0003כגון שהחזירו לביסא\u0004 (כלי של מנחה) \u0003גדושה\u0004 מעל גדותיה בסולת, כך שהקומץ שהוחזר לא נכנס לתוך חלל הכלי, וכך אינו מתקדש.","ותמהים: אם היה הכלי גדוש \u0003ומקמץ היכי קמץ\u0004 \u0005[וכיצד\u0006 יכול היה \u0005לקמוץ]\u0006 ממנו מתחילה? הרי לא קמץ מתוך הכלי! \u0003אלא,\u0004 צריך לפרש: \u0003כגון שהחזירו לביסא טפופה\u0004 שהיתה מלאה אך לא גדושה, וקמץ מתוכה, וממקום שקמץ — לשם הוא מחזיר.","ושואלים: \u0003וכיון דקמץ ליה עבד ליה\u0004 \u0005[וכיון\u0006 שבשעה \u0005שקמץ עשה]\u0006 \u0003גומא\u0004 במקום שקמץ, הרי \u0003כי מהדר\u0004 \u0005[כאשר מחזיר]\u0006 את הקומץ למקומו נמצא כי \u0003לגוויה דמנא קא מהדר ליה\u0004 \u0005[לתוכו של הכלי הוא מחזיר אותו],\u0006 ויתקדש על ידי כן להיפסל! ומשיבים: \u0003מכי מהדר ליה\u0004 \u0005[שכאשר מחזיר אותו]\u0006 את הקומץ לכלי אינו מחזירו לגומא, אלא \u0003מנח ליה אדפנא דמנא\u0004 \u0005[מניח אותו על דפנות הכלי],\u0006 \u0003ומניד ליה ונפל ממילא\u0004 \u0005[ומנענע אותו\u0006 את הכלי, עד \u0005שנופל\u0006 הקומץ \u0005מאליו]\u0006 לתוך הגומא, ש\u0003נעשה\u0004 הדבר \u0003כמי שהחזירו הקוף,\u0004 ולא אדם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא: ולוקמה\u0004 \u0005[ונעמידנה]\u0006 שיחזיר קומץ לכלי שרת, ולא יתקדש — \u0003כגון שהחזירו לכלי המונח על גבי קרקע!\u0004 \u0003אלא\u0004 מתוך שאין מסבירים כן, ואנו מניחים שכלי שרת המונח על גבי קרקע מקדש, \u0003שמע מינה\u0004 \u0005[נלמד מכאן]\u0006 שגם \u0003קומצין\u0004 את קומץ המנחה \u0003מכלי שעל גבי קרקע?\u0004 שהרי שתי עבודות אלו צריכות כלי שרת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003קא נגעת בבעיא דאיבעיא לן\u0004 \u0005[נוגע אתה בשאלה שנשאלה לנו],\u0006 ש\u0003ר' אבימי תני\u0004 \u0005[היה שונה,\u0006 לומד\u0005]\u0006 מסכת \u0003מנחות בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב חסדא.\u0004","ותחילה תוהים: \u0003ו\u0004ר' \u0003אבימי בי\u0004 \u0005[בבית]\u0006 \u0003רב חסדא תני\u0004 \u0005[\u0006היה \u0005שונה]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא, קולפי טאבי בלעי מאבימי עלה דהא שמעתא\u0004 \u0005[אלות הרבה ספגתי מאבימי על שמועה זו]\u0006 כלומר, אבימי גער בי כאשר הקשיתי על דבריו בענין מכירת נכסי יתומים על ידי בית דין, שהיו סותרים את דברי הברייתא, וכך הסביר לי: אם \u0003בא להכריז\u0004 ימים \u0003רצופין\u0004 — מכריז \u0003שלשים יום,\u0004 כדברי הברייתא, ואם מכריז רק ב\u0003שני וחמישי ושני\u0004 — מכריז \u0003ששים יומי\u0004 \u0005[ימים].\u0006 ואם כן רב חסדא היה שונה לפני אבימי ולא להיפך!","ומשיבים: \u0003אבימי מסכתא איתעקרא איתעקר ליה\u0004 \u0005[מסכת\u0006 מנחות \u0005נשכחה ממנו],\u0006 \u0003ואתא קמיה\u0004 \u0005[ובא לפני]\u0006 \u0003רב חסדא\u0004 תלמידו \u0003לאדכורי גמריה\u0004 \u0005[להזכיר לו תלמודו].\u0006 ושואלים: אם רב חסדא היה תלמידו, \u0003ולישלח ליה וליתי לגביה\u0004 \u0005[שישלח אליו\u0006 אבימי לקרוא לו \u0005ויבוא\u0006 רב חסדא \u0005אצלו]!\u0006 ומשיבים, \u0003סבר\u0004 \u0005[סבור]\u0006 היה אבימי: \u0003הכי מסתייעא מילתא טפי\u0004 \u0005[כך יסתייע,\u0006 יצליח \u0005הדבר יותר],\u0006 שאם מטריח עצמו לבוא כתלמיד לרבו יעלה לימודו יפה יותר. ושבים לעיקר הענין.","\u0003פגע ביה\u0004 \u0005[פגש בו]\u0006 \u0003רב נחמן\u0004 באבימי בדרכו מבית רב חסדא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כיצד קומצין? אמר ליה\u0004 \u0005[לו]\u0006 אבימי: כגון \u0003מכלי זה,\u0004 שהיה מונח על הקרקע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003וכי קומצין מכלי שעל גבי קרקע? אמר ליה\u0004 \u0005[לו]:\u0006 כוונתי \u0003דמגבה ליה\u0004 \u0005[שמגביה אותו]\u0006 \u0003כהן,\u0004 וכהן אחר קומץ ממנו.","עוד שאל אותו רב נחמן: \u0003כיצד מקדשין את המנחות? אמר ליה\u0004 \u0005[לו]\u0006 אבימי: \u0003נותנה לכלי זה,\u0004 שהיה מונח לפניו על הקרקע. אמר לו רב נחמן: \u0003וכי מקדשין בכלי שעל גבי קרקע? אמר ליה\u0004 \u0005[לו]\u0006 אבימי: \u0003דמגבה ליה\u0004 \u0005[שמגביה אותו]\u0006 \u0003כהן\u0004 את הכלי, ונותן לתוכו את המנחה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אם כן, הוצרכתה שלשה כהנים,\u0004 אחד שמקדש את המנחה, ואחד שמגביה את הכלי, ואחד שקומץ מתוך הכלי! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אין זו קושיה, \u0003ותהא צריכה\u0004 אפילו \u0003שלשה עשר\u0004 כהנים, \u0003כ\u0004קרבן ה\u0003תמיד\u0004 ששלושה עשר כהנים היו עוסקים בעבודתו.","עוד \u0003איתביה\u0004 \u0005[הקשה לו]\u0006 רב נחמן ממה ששנינו לגבי סדר עבודות המנחה שהמחשבה פוגמת בהן: \u0003זה הכלל, כל הקומץ ונותן בכלי, המוליך והמקטיר, לאכול דבר שדרכו לאכול\u0004 או להקטיר דבר שדרכו להקטיר,","\u0003ואילו מגביה לא קתני\u0004 \u0005[אינו שונה]\u0006 ביניהן, משמע שאין צורך בהגבהת הכלי! ענה לו אבימי: ה\u0003תנא סדר עבודות\u0004 שהמחשבה פוסלת בהן הוא \u0003נקיט\u0004 \u0005[אוחז,\u0006 מזכיר\u0005],\u0006 \u0003ולא סדר כהנים,\u0004 שלא מנה את כל הכהנים הנצרכים לעבודת המנחה.","ובענין זה \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מדרב ששת: מהו לקמוץ מכלי שעל גבי קרקע? אמר ליה\u0004 \u0005[לו]\u0006 לשואל: \u0003פוק חזי מה עבדין לגאו\u0004 \u0005[צא וראה מה עושים\u0006 הכהנים \u0005בפנים]\u0006 בתוך ההיכל, כאשר היו נוטלים את בזיכי הלבונה מעל שולחן לחם הפנים כדי להקטירם על המזבח, כשם שהכהן נוטל את הקומץ מן המנחה שבכלי כדי להקטירו. שכך שנינו: כאשר מחליפים את לחם הפנים בכל שבת, היו \u0003ארבעה כהנים נכנסין\u0004 להיכל, \u0003שנים בידם שני סדרים\u0004 (מערכות) חדשים של לחם, \u0003ושנים בידם שני בזיכין\u0004 של לבונה, \u0003וארבעה\u0004 כהנים אחרים \u0003מקדמין לפניהם, שנים\u0004 כדי \u0003ליטול שני סדרים\u0004 המצויים על השולחן, כדי לפנות מקום לחדשים, \u0003ושנים\u0004 כדי \u0003ליטול\u0004 מן השולחן את \u0003שני\u0004 ה\u0003בזיכין,\u0004"],["\u0003ואילו\u0004 כהן ש\u0003מגביה את השולחן\u0004 מעל גבי הקרקע לצורך נטילת הבזיכים ממנו \u0003לא קתני\u0004 \u0005[אינו שונה],\u0006 ומכאן שאת קומץ המנחה גם כן קומצים מכלי שעל גבי קרקע.","ודוחים: \u0003לאו אמרת התם\u0004 \u0005[האם לא אמרת שם]\u0006 לגבי המשנה \"כל הקומץ ונותן בכלי\" וכו' ש\u0003סדר עבודות\u0004 המנחה החשובות \u0003נקט\u0004 \u0005[הוא אוחז]?\u0006 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר כי \u0003סדר עבודות\u0004 החשובות \u0003נקט\u0004 \u0005[הוא אוחז],\u0006 ואין להוכיח מכאן שאין צורך בהגבהה.","ומקשים: \u0003מי דמי\u0004 \u0005[האם\u0006 הדבר \u0005דומה]?\u0006 \u0003התם לא נחית למניינא דכהנים\u0004 \u0005[שם אינו יורד למנין של כהנים],\u0006 בכמה כהנים מדובר, ואילו \u0003הכא נחית למניינא דכהנים\u0004 \u0005[כאן\u0006 הוא \u0005יורד למנין של כהנים],\u0006 ו\u0003אם איתא\u0004 \u0005[כך הוא],\u0006 שצריך הגבהה — \u0003ליתני\u0004 \u0005[שישנה]\u0006 גם כהן \u0003מגביה! אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003קומצין מכלי שעל גבי קרקע,\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ועוד בענין זה, \u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי, קומץ\u0004 הכהן \u0003מכלי ש\u0004מונח \u0003על גבי קרקע\u0004 — \u0003שכן מצינו בסילוק בזיכין\u0004 של לבונה מעל שולחן הפנים, שהוא מונח על קרקע המקדש. וכן \u0003מקדשין מנחה\u0004 מתחילה \u0003בכלי שעל גבי קרקע\u0004 — \u0003שכן מצינו בסידור בזיכין\u0004 עם הלחם על השולחן.","ולאחר הקדמת הדברים הללו שהיו ברורים לו, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: קידוש קומץ\u0004 בכלי שעל גבי קרקע \u0003מאי\u0004 \u0005[מה]\u0006 דינו? האם \u0003מ\u0004קידוש \u0003מנחה ילפינן לה\u0004 \u0005[למדים אנו אותה],\u0006 שמקדשים בכלי שעל גבי קרקע, \u0003או\u0004 האם \u0003מ\u0004קבלת \u0003דם ילפינן לה\u0004 \u0005[למדים אנו אותה],\u0006 מה הדם אין מקבלים אותו בכלי שעל גבי קרקע, אף הקומץ אין נותנים אותו בכלי שעל גבי קרקע? \u0003הדר פשטה\u0004 \u0005[חזר\u0006 רבא ו\u0005פתרה]:\u0006 \u0003מדם ילפינן לה\u0004 \u0005[למדים אנו].\u0006","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבא הכי\u0004 \u0005[כך]\u0006 שלמדים מתן הקומץ בכלי מקבלת הדם בכלי? \u0003והא אתמר\u0004 \u0005[והרי נאמר]:\u0006 \u0003קומץ שחלקו בשני כלים\u0004 — \u0003רב נחמן אמר: אינו קדוש, ורבא אמר: קדוש. ואם איתא\u0004 \u0005[אכן הוא],\u0006 \u0003לילף\u0004 \u0005[שילמד]\u0006 \u0003מדם,\u0004 שאינו מתקדש אם ניתן בשני כלים! ומשיבים: \u0003הדר ביה\u0004 \u0005[חזר בו]\u0006 \u0003רבא מההיא,\u0004 ממה שאמר שהקומץ שחילקו לשני כלים קדוש.","ומבררים: \u0003ודם מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003לא קדוש לחצאין? דתני\u0004 \u0005[ששנה]\u0006 \u0003רב תחליפא בן שאול\u0004 בענין מי חטאת (פרה אדומה): \u0003קידש\u0004 את המים בשני כלים, והיה במים \u0003פחות מכדי הזאה בכלי זה,\u0004 כלומר, פחות מכדי שיכול לטבול בהם את אגודת האזוב ולהזות, \u0003ופחות מכדי הזאה בכלי זה\u0004 — \u0003לא קידש,\u0004 ואפילו צירף אותם אחר כך לכלי אחד — אינו יכול להזות מהם.","\u0003ואיבעיא להו\u0004 \u0005[ונשאלה להם]:\u0006 \u0003ב\u0004קבלת \u0003דם\u0004 החטאת בכלי לצורך הזאה על המזבח \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם נאמר כי \u0003הלכתא\u0004 \u0005[הלכה\u0006 למשה מסיני\u0005]\u0006 \u0003היא\u0004 לגבי מי חטאת בלא טעם, \u0003ומהלכתא לא ילפינן\u0004 \u0005[ומהלכה אין למדים]\u0006 לדינים אחרים.","\u0003או דלמא התם מאי טעמא\u0004 \u0005[שמא שם מה הטעם]\u0006 — משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וטבל במים\"\u0004 (במדבר יט, יח), במים שנתן מתחילה בכלי, ומכאן שצריך היה להיות בהם מתחילה כשיעור הזאה, \u0003הכא נמי הכתיב\u0004 \u0005[כאן,\u0006 בחטאת, \u0005גם כן נאמר]:\u0006 \u0003\"וטבל\u0004 הכהן את אצבעו \u0003בדם\"\u0004 (ויקרא ד, ו)?","\u0003ואיתמר\u0004 \u0005[ונאמר]\u0006 על כך, \u0003אמר ר' זריקא, אמר ר' אלעזר: אף בדם לא קידש\u0004 אם קיבל פחות מכשיעור הזאה בכלי זה ופחות מכשיעור בכלי זה. \u0003אמר רבא, תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003(בפני כהן מניח)\u0004 [בפר כהן משיח], שנאמר בו: \"וטבל הכהן את אצבעו בדם והזה מן הדם\" (שם), \u0003\"וטבל\"\u0004 — שיהא בו די דם כדי שיטבול בו את אצבעו, \u0003ולא\u0004 יהא שם דם מועט כל כך שיהא רק \u0003מספיג\u0004 מקנח דם באצבעו מדפנות הכלי.","\u0003\"בדם\"\u0004 — באותו דם שכבר היה שם, לומר שצריך \u0003שיהא בדם שיעור טבילה מעיקרו,\u0004 \"והזה \u0003מן הדם\"\u0004 — \u0003מן הדם שבענין,\u0004 כלומר, מן הדם שבכלי (כאשר יבואר להלן).","ומסבירים: \u0003ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"וטבל\" ואיצטריך למכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"בדם\",\u0004 למרות ששניהם עוסקים בשיעור הדם, \u0003דאי כתב רחמנא\u0004 \u0005[שאם היתה כותבת התורה]\u0006 רק \u0003\"וטבל\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 די במה שיש עכשיו בדם כדי טבילה והזאה אחת \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא קיבל\u0004 בכלי זה \u0003שיעור\u0004 כל ה\u0003טבילות,\u0004 \u0003דהיינו\u0004 דם שיש בו כדי \u0003הזאה שבע פעמים, מעיקרו\u0004 — על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"בדם\".\u0004","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"בדם\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי אם היה מתחילה שיעור ראוי, והוא משתמש בדם שהיה בכלי מתחילה — \u0003אפילו\u0004 יש עכשיו בכלי דם בשיעור \u0003מספיג\u0004 הרי זה כשר, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"וטבל\",\u0004 דרך טבילה ולא דרך סיפוג.","ושואלים: מה ששנינו \u0003\"מן הדם שבענין\", למעוטי מאי\u0004 \u0005[למעט מה]\u0006 הוא בא? \u0003אמר רבא: למעוטי\u0004 \u0005[למעט]\u0006 \u0003שירים שבאצבע,\u0004 שלאחר כל הזאה צריך לחזור ולטבול אצבעו בדם שבכלי ולהזות, ולא מן הדם שנותר על אצבעו. ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לר' אלעזר, דאמר: שירים ש\u0004נותרו \u0003באצבע\u0004 — \u0003פסולין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין בר רב אדא לרבא: אמרי\u0004 \u0005[אומרים]\u0006 \u0003תלמידך\u0004 שכך \u0003אמר רב עמרם, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003היה מזה\u0004 מדם החטאת \u0003ונתזה הזאה מידו\u0004 על הבגד, \u0003אם עד שלא הזה\u0004 — \u0003טעון\u0004 הבגד \u0003כיבוס,\u0004 כדין בגד שנפל עליו דם חטאת הראוי להזאה, אם \u0003משהזה\u0004 ניתז הדם על הבגד — \u0003אין טעון כיבוס;\u0004","\u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה: אם \u0003עד שלא גמר\u0004 כל \u0003הזאתו\u0004 ניתז — טעון כיבוס, \u0003ומשגמר הזאתו\u0004 ניתז דם — אינו טעון כיבוס? \u0003שמע מינה\u0004 \u0005[\u0006ו\u0005למד מכאן]\u0006 ש\u0003שירים ש\u0004נותרו \u0003באצבע\u0004 בין הזאה להזאה, כל עוד לא נגמרה הזאת דם החטאת — \u0003כשרים\u0004 להזאה, שהרי דם שאינו ראוי להזאה אינו טעון כיבוס!","ודוחים: \u0003לא,\u0004 הכוונה היא: אם ניתז הדם מידו \u0003עד שלא יצתה מידו הזאה\u0004 — \u0003טעון כיבוס, ו\u0004אם \u0003משיצאה הזאה מידו ונתזה ממה שנשאר\u0004 על אצבעו — \u0003אין טעון כיבוס,\u0004 שכבר נפסל להזאה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבא ממה ששנינו בענין פרה אדומה: \u0003גמר\u0004 הכהן \u0003מלהזות\u0004 מדמה כנגד פתח ההיכל — \u0003מקנח ידו\u0004 מן הדם \u0003בגופה של פרה,\u0004 מפני שאינו עומד להזאה, ונדייק: \u0003גמר\u0004 מלהזות — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא גמר\u0004 — \u0003לא,\u0004 למרות שנותרו שיריים על אצבעו, ומכאן שהם כשרים להזאה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא, כך יש לפרש: כאשר \u0003גמר\u0004 כל ההזאה — \u0003מקנח ידו,\u0004 אם עדיין \u0003לא גמר\u0004 — \u0003מקנח אצבעו\u0004 אחר כל הזאה, כדי שלא יזה מן הדם שנותר עליה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 כי כאשר \u0003גמר מקנח ידו בגופה של פרה\u0004 — מפני \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושרף את הפרה לעיניו\u0004 את עורה ואת פרשה ואת דמה\" (במדבר יט, ה), שצריך לשרוף את דמה יחד עם בשרה, \u0003אלא לא גמר מקנח אצבעו, במאי\u0004 \u0005[במה]\u0006 \u0003מקנח? דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שמקנח \u0003בגופה של פרה, איבעי ליה למיתני\u0004 \u0005[צריך היה לו לשנות]:\u0006 \u0003מקנח ידו ואצבעו בגופה של פרה!\u0004 אלא \u0003מדלא קתני הכי שמע מינה\u0004 \u0005[מ\u0006תוך \u0005שאינו שונה כך למד מכאן]\u0006 \u0003דלא בעי\u0004 \u0005[שאינו צריך]\u0006 \u0003קינוח!\u0004","\u0003אמר אביי:\u0004 מקנח את אצבעו \u0003בשפת מזרק\u0004 שבו היה דם, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"כפורי זהב\" וגו'\u0004 (עזרא א, י) שהם המזרקים, והם קרויים כן על שם שמכפרים (=מקנחים) בהם את הדם.","ושבים לעיקר הענין, ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר הכי\u0004 \u0005[כך]\u0006 שדם אינו קדוש לחצאין? \u0003והא איתמר\u0004 \u0005[והרי נאמר]:\u0006 \u0003חביתי כהן גדול\u0004 עשירית האיפה (עשרון) סולת שצריך הכהן הגדול להביא מחציתה בבוקר ומחציתה בערב — \u0003ר' יוחנן אמר: אינה קדושה לחצאין,\u0004 אם קידש חצי עשרון בכלי זה וחצי עשרון בכלי זה. \u0003ר' אלעזר אמר: מתוך שקרבה לחצאין,\u0004 שהיו מקריבים מחציתה בבוקר ומחציתה בין הערביים — אף \u0003קדושה לחצאין;\u0004"],["\u0003ואם איתא\u0004 \u0005[יש,\u0006 נכון הדבר\u0005],\u0006 שלדעת ר' אלעזר, דם אינו מתקדש לחצאין — \u0003לילף\u0004 \u0005[שילמד]\u0006 דין חביתי כהן גדול \u0003מדם! וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' אלעזר מילתא ממילתא לא גמר\u0004 \u0005[דבר מדבר אינו למד],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: מנחה שקמצה בהיכל\u0004 — \u0003כשרה,\u0004 למרות שמקום עשייתה הרגיל הוא בעזרה, \u0003שכן מצינו בסילוק בזיכין\u0004 מעל שולחן לחם הפנים (שהוא מעין קמיצה, שלאחר מכן מותר הלחם באכילה) ועושים אותו בהיכל!","ומשיבים: \u0003מנחה ממנחה יליף\u0004 \u0005[לומד],\u0006 שהמנחות דבר אחד הן, ובכלל זה לחם הפנים, אבל \u0003מנחה מדם לא יליף\u0004 \u0005[אינו למד].\u0006","ושואלים: \u0003ומנחה ממנחה מי יליף\u0004 \u0005[האם הוא למד]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 אם \u0003עד שלא פרקה\u0004 את מערכת לחם הפנים בשבת מעל השולחן ונטל את הבזיכים, \u0003נפרס\u0004 (נשבר) \u0003לחמה\u0004 — \u0003הלחם פסול, ואין מקטיר עליו\u0004 (בגללו) \u0003את הבזיכין,\u0004 אם \u0003משפרקה\u0004 \u0003נפרס לחמה\u0004 — \u0003הלחם\u0004 אמנם \u0003פסול,\u0004 ואינו נאכל לכהנים, אבל \u0003מקטיר עליו את הבזיכין.\u0004","\u0003ואמר ר' אלעזר: לא פרקה ממש, אלא כיון שהגיע זמנה לפרק, אף על פי ש\u0004עדיין \u0003לא פרקה,\u0004 ולא נטלו את הבזיכים — \u0003כמי שפרקה דמיא\u0004 \u0005[נחשבת],\u0006 ואם נפרס הלחם באותה שעה — מקטיר עליו את הבזיכים.","ואם לדעת ר' אלעזר למדים מנחה ממנחה, יש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 מקטיר את הבזיכים? \u0003תיהוי\u0004 \u0005[שתהא\u0006 זו\u0005]\u0006 \u0003כמנחה שחסרה קודם קמיצה\u0004 ונפסלה, שאין קומצים אותה, ואין מקטירים את קומצה!","ודוחים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 \u0003מנחה\u0004 קודם קמיצה \u0003לא בריר ברירה קומץ דידיה\u0004 \u0005[אין מבורר הקומץ שלה],\u0006 ולכן אם חסרה ונפסלה — אינו יכול לקמוץ ממנה, \u0003והא בריר ברירה קומץ דידה\u0004 \u0005[ו\u0006אילו \u0005זו,\u0006 לחם הפנים, \u0005מבורר הקומץ שלה],\u0006 שהם בזיכי הלבונה, \u0003ו\u0004לכן \u0003כיון שהגיע זמנה לפרק\u0004 — \u0003כמאן דפרקה דמיא\u0004 \u0005[כמי שפירקה נחשבת].\u0006","ומקשים: \u0003אלא מעתה,\u0004 שלדעת ר' אלעזר למדים מנחה ממנחה, גם אם נחשב הפירוק כאילו ניטל קומצו, מדוע אם נפרס הלחם באותה שעה מקטיר עליו את הבזיכים? \u0003תיהוי\u0004 \u0005[תהיה,\u0006 יהיה דינו\u0005]\u0006 \u0003כ\u0004דין \u0003שירים\u0004 של מנחה \u0003שחסרו בין קמיצה להקטרה,\u0004 ש\u0003אין מקטירין קומץ עליהן!\u0004 ומשיבים: \u0003לאו פלוגתא נינהו\u0004 \u0005[\u0006וכי \u0005אין מחלוקת\u0006 בדבר זה\u0005]?\u0006 \u0003ר' אלעזר סבר לה כמאן דאמר\u0004 \u0005[סבור הוא כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003שירים שחסרו בין קמיצה להקטרה\u0004 — \u0003מקטיר קומץ עליהן.\u0004","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו: \u0003חביתי כהן גדול, ר' יוחנן אמר: אינה קדושה לחצאין,\u0004 \u0003ור' אלעזר אמר: מתוך שקרבה לחצאין,\u0004 מחצית בבקר ומחצית בערב, גם \u0003קדושה לחצאין. אמר ר' אחא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוחנן? אמר קרא\u0004 \u0005[המקרא]:\u0006 \"יקריבו... \u0003מנחה\u0004 תמיד \u0003מחציתה\u0004 בבקר ומחציתה בערב\" (ויקרא ו, יג), לומר: \u0003הביא\u0004 תחילה \u0003מנחה\u0004 שלמה \u0003ואחר כך\u0004 אתה \u0003חוציהו\u0004 לשנים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על ר' אלעזר ממה ששנינו: \u0003חביתי כהן גדול לא היו באות חצאין, אלא מביא עשרון שלם וחוצהו; ותניא\u0004 \u0005[ושנויה\u0006 על כך ברייתא\u0005]:\u0006 \u0003אילו נאמר\u0004 \"יקריב \u0003מנחה מחצית\u0004 בבקר ומחצית בערב\", \u0003הייתי אומר: מביא חצי עשרון מביתו שחרית ומקריב,\u0004 ועוד \u0003חצי עשרון מביתו ערבית ומקריב\u0004 — על כן \u0003תלמוד לומר: \"מחציתה בבקר\",\u0004 לומר \u0003מחצה מ\u0004דבר \u0003שלם הוא מביא,\u0004 ואינו מביא מחצית לעצמה!","ודוחים: אפשר לומר כי דבר זה הוא \u0003למצוה,\u0004 שכך צריך לעשות לכתחילה, אבל בדיעבד אם הביא לחצאין — הרי זה כשר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב גביהא מבי כתיל לרב אשי: והא\u0004 \u0005[והרי]\u0006 \u0003\"חוקה\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003בה\u0004 במנחת החביתין (\"חק עולם\", שם טו), ובמקום שנאמר \"חוקה\" הרי זה לעכב! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא נצרכא\u0004 חוקה זו \u0003אלא\u0004 לענין שצריך \u0003להביאה\u0004 עשרון \u0003שלם מביתו,\u0004 אבל כשהוא נותנה בכלי שרת לשם הקרבה הריהי קדושה גם לחצאין. ודנים בדברי ר' יוחנן, שאמר שמנחת חביתין אינה קדושה לחצאין.","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והא איתמר\u0004 \u0005[והרי נאמר]:\u0006 אם \u0003הפריש\u0004 אדם \u0003חצי עשרון\u0004 למנחה, \u0003ודעתו להוסיף\u0004 עליו ולהשלים אותו \u0003לעשרון —\u0004 \u0003רב אמר: אינו קדוש,\u0004 כיון שלא הביא עשרון שלם, \u0003ור' יוחנן אמר: קדוש. ואם איתא\u0004 \u0005[אכן]\u0006 סבור ר' יוחנן שמנחת חביתין אינה קדושה לחצאין — \u0003לילף\u0004 \u0005[שילמד]\u0006 \u0003מ\u0004מנחת \u0003חביתין,\u0004 שכל מנחה אינה קדושה לחצאין!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003ר' יוחנן מילתא ממילתא לא יליף\u0004 \u0005[דבר מדבר אינו למד],\u0006 ממנחת חביתין למנחה אחרת — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: שלמים ששחטן ב\u0004תוך ה\u0003היכל\u0004 — \u0003כשירין, דכתיב\u0004 \u0005[שנאמר]\u0006 בהם: \u0003\"ושחטו פתח אהל מועד\"\u0004 (ויקרא ג, ב), כלומר, בעזרה, והדעת נותנת \u0003שלא יהא\u0004 דינו של ה\u0003טפל,\u0004 שהוא העזרה, \u0003חמור מ\u0004של ה\u0003עיקר,\u0004 שהוא אהל מועד. הרי שהוא למד דבר מדבר (היכל מעזרה)!","ומשיבים: ור' יוחנן אמנם למד דבר מדבר, ולדעתו גם מנחה למדה ממנחת חביתין שאינה קדושה לחצאין, ואולם במקרה ש\u0003דעתו להוסיף\u0004 ולהשלימו \u0003שאני\u0004 \u0005[שונה]\u0006 הדבר, שאין זה נחשב מקדש מחצית בלבד. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \"קערת כסף וכו' מזרק אחד כסף וכו' שניהם \u0003מלאים\u0004 סלת\" (במדבר ז, יג) — \u0003אין \"מלאים\" אלא שלמים, כלומר, שאינו קדוש\u0004 הסולת שבו \u0003עד שיהא\u0004 בו \u0003עשרון שלם. ואמר ר' יוסי: אימתי\u0004 אמרו שאינו קדוש כשאין בו עשרון שלם — \u0003בזמן שאין דעתו\u0004 מתחילה \u0003להוסיף\u0004 על מה שנתן, \u0003אבל בזמן שדעתו להוסיף\u0004 — \u0003ראשון ראשון קדוש.\u0004","ושואלים: \u0003ורב,\u0004 שאמר לגבי מנחה רגילה, שאם הפריש חצי עשרון גם אם דעתו להוסיף עליו אינו קדוש, \u0003ב\u0004ענין מנחת \u0003חביתין כמאן סבירא ליה\u0004 \u0005[כ\u0006דעת \u0005מי סבור הוא]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר\u0004 שהיא קדושה לחצאין, אם כן \u0003לילף\u0004 \u0005[שילמד]\u0006 \u0003מחביתין!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003רב מילתא ממילתא לא יליף\u0004 \u0005[דבר מדבר אינו למד]\u0006 — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב: מנחה\u0004 רגילה, שצריכה שמן ולבונה, \u0003קדושה\u0004 בכלי שרת גם \u0003בלא שמן (ובלא לבונה)\u0004 — \u0003שכן מצינו בלחם הפנים\u0004 שאין בו שמן, ומתקדש בכלי שרת, וכן היא מתקדשת \u0003בלא לבונה\u0004 — \u0003שכן מצינו במנחת נסכים\u0004 שאין בה לבונה.","וכן היא מתקדשת גם \u0003בלא שמן ובלא לבונה\u0004 — \u0003שכן מצינו במנחת חוטא,\u0004 שאין בה לא שמן ולא לבונה. הרי שהוא למד ממנחה למנחה! אלא \u0003על כרחיך רב כר' יוחנן סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שאין מנחת חביתין קדושה לחצאין, ומשם הוא למד למנחה רגילה.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003אמר רב: מנחה קדושה בלא שמן, ואין דינה כעשרון חסר\u0004 — \u0003שכן מצינו בלחם הפנים\u0004 שהוא קדוש בלא שמן. וכן מנחה מתקדשת \u0003בלא לבונה\u0004 — \u0003שכן מצינו במנחת נסכים\u0004 שאין בה לבונה, וכן מתקדשת \u0003בלא שמן ובלא לבונה\u0004 — \u0003שכן מצינו במנחת חוטא,\u0004 שאין בה לא שמן ולא לבונה.","\u0003ושמן ולבונה\u0004 עצמם \u0003קדשי האי בלא האי והאי בלא האי\u0004 \u0005[מתקדשים\u0006 בכלי שרת \u0005זה בלא זה וזה בלא זה];\u0006 \u0003שמן\u0004 מתקדש לעצמו — \u0003שכן מצינו בלוג שמן של מצורע\u0004 שמתקדש לעצמו, \u0003לבונה\u0004 מתקדשת לעצמה — \u0003שכן מצינו בלבונה הבאה בבזיכין\u0004 שאין עימה שמן. \u0003ור' חנינא אמר:\u0004"],["\u0003לא זו קדושה בלא זו, ולא זו קדושה בלא זו,\u0004 אלא כל מנחה שטעונה שמן ולבונה מתקדשת בכלי רק כשיש שם סולת שמן ולבונה.","ושואלים: \u0003ול\u0004דעת \u0003ר' חנינא\u0004 שאין מנחה קדושה בלא שמן ולבונה, כלי מידה של \u0003עשרון\u0004 שהיה במקדש \u0003ל\u0004שם \u0003מה נמשח? והלא אינו עשוי אלא למדידת קמח בלבד, והקמח אינו קדוש בלא שמן!\u0004 ומשיבים: העשרון נמשח \u0003ל\u0004צורך \u0003מנחת חוטא,\u0004 שאין עימה לא שמן ולא לבונה.","\u0003ו\u0004עוד שואלים: כלי מידה של \u0003לוג למה נמשח,\u0004 אם אין השמן מתקדש בפני עצמו? ומשיבים: \u0003ללוג\u0004 שמן \u0003של מצורע,\u0004 שאינו חלק ממנחה, שוודאי מתקדש לעצמו.","ומעירים: \u0003ואף שמואל סבר לה להא\u0004 \u0005[סבור לזו]\u0006 שאמר \u0003רב,\u0004 שכלי שרת מקדש סולת בפני עצמה, גם במנחה שטעונה שמן. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי הלח\u0004 כלי שרת שנועדו למשקים במקדש \u0003מקדשין את הלח\u0004 שניתן בהם, \u0003ומדות היבש\u0004 כלי מדידה המיועדים לדברים יבשים \u0003מקדשין את היבש,\u0004 אבל \u0003אין כלי הלח מקדשין את היבש, ולא מדות היבש מקדשין את הלח.\u0004","\u0003ואמר שמואל: לא שנו\u0004 שכלי הלח אין מקדשים את היבש, \u0003אלא מדות, אבל מזרקות\u0004 (כלים ששימשו לקבלה ולזריקה) \u0003של דם מקדשות\u0004 אף \u0003את היבש, שנאמר\u0004 בקרבנות הנשיאים למשכן: \"מזרק אחד כסף... \u0003שניהם מלאים סלת בלולה בשמן למנחה\"\u0004 (במדבר ז, יג), הרי שהמזרק מקדש את המנחה שהיא יבשה.","ועל כך \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא:\u0004 מה הראיה מכאן? הלוא \u0003מנחה לחה היא,\u0004 שהרי נאמר שהיתה בלולה בשמן! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא נצרכא\u0004 ראיה זו של שמואל \u0003אלא\u0004 ביחס \u0003ליבש שבה (דהיינו לבונה),\u0004 כלומר, לסולת שבה, שנתקדשה במזרק.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003שמואל: אין מנחה קדושה\u0004 בכלי \u0003עד שיהו כולן\u0004 יחד, אם כן, \u0003יבש שבה היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006 \u0003והלא\u0004 בשעה שהמנחה מתקדשת \u0003כולן לחים הן מפני השמן,\u0004 ואין שם יבש כלל! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003שמואל: האי בלא האי\u0004 \u0005[זה בלא זה]\u0006 מתקדש.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 בתירוץ הקושיה של רב אחא מדיפתי, שמנחה לחה היא, ולכן אין מכאן ראיה שמזרקות מקדשות את היבש: \u0003מנחה\u0004 ואפילו לחה \u0003לגבי\u0004 \u0005[אצל]\u0006 \u0003דם\u0004 שהוא נוזל — \u0003כיבש דמיא\u0004 \u0005[נחשבת].\u0006","ושבים לדון \u0003גופא\u0004 \u0005[לגופו]\u0006 של דבר שהזכרנו, \u0003אמר ר' אלעזר: מנחה שקמצה בהיכל\u0004 — \u0003כשרה, שכן מצינו\u0004 מעין קמיצה בהיכל, \u0003בסילוק בזיכין\u0004 מעל שולחן לחם הפנים כדי להקטירם, ועל ידי כך מותר הלחם באכילה לכהנים, כמו קומץ המנחה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003ר' ירמיה\u0004 ממה ששנינו בברייתא: נאמר במנחה \"והביאה אל בני אהרן הכהנים \u0003וקמץ משם\"\u0004 (ויקרא ב, ב) — \u0003ממקום שרגלי הזר עומדות,\u0004 במקום שרשאי הזר לעמוד בו.","\u0003בן בתירא אומר\u0004 הסבר אחר לכתוב זה: \u0003מנין שאם קמץ בשמאל\u0004 שאין זה פוסל לגמרי, אלא \u0003שיחזיר\u0004 את הקומץ למנחה ויחזור \u0003ויקמוץ בימין? תלמוד לומר: \"וקמץ משם\"\u0004 — \u0003ממקום שקמץ כבר.\u0004 הרי מדברי התנא הראשון אתה למד שצריך לקמוץ רק במקום שהזר מותר לעמוד, ולא בהיכל!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הוא\u0004 ר' ירמיה \u0003מותיב לה\u0004 \u0005[הקשה קושיה זו]\u0006 \u0003והוא מפרק לה\u0004 \u0005[מתרץ אותה].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יעקב לר' ירמיה בר תחליפא: אסברא לך\u0004 \u0005[אסביר לך],\u0006 \u0003לא נצרכא\u0004 הלכה זו כדי לאסור קמיצה בהיכל, \u0003אלא\u0004 כדי \u0003להכשיר את כל עזרה כולה\u0004 לקמיצה, \u0003שלא תאמר: הואיל ועולה\u0004 היא \u0003קדשי קדשים, ומנחה\u0004 אף היא \u0003קדשי קדשים, מה עולה טעונה\u0004 שחיטה ב\u0003צפון\u0004 העזרה — \u0003אף מנחה\u0004 שהיא קדשי קדשים תהא קמיצתה \u0003טעונה צפון.\u0004 ודוחים: כיצד ניתן ללמוד מעולה למנחה?","\u0003מה לעולה\u0004 שיש בה קדושה גדולה יותר, \u0003שכן\u0004 היא מוקרבת \u0003כליל!\u0004 ומשיבים: על כל פנים ניתן היה ללמוד \u0003מחטאת,\u0004 שהיא קדשי קדשים, ואינה כליל, ושחיטתה רק בצפון.","ודוחים: \u0003מה לחטאת\u0004 שיש בה חומרה יתירה על המנחה, \u0003שכן\u0004 היא \u0003מכפרת על חייבי כריתות!\u0004 ומשיבים: ניתן היה ללמוד \u0003מאשם\u0004 שהוא קדשי קדשים, ואינו כליל, ואינו מכפר על חייבי כריתות, והוא נשחט בצפון.","ודוחים: \u0003מה לאשם\u0004 שיש בו מעלה יתירה על המנחה, \u0003שכן\u0004 הוא מ\u0003מיני דמים,\u0004 ועיקר הכפרה היא בדם! ומוסיפים: מטעם זה \u0003מכולהו נמי\u0004 \u0005[מכולם גם כן],\u0006 גם מעולה וחטאת, אי אפשר ללמוד, \u0003שכן\u0004 כולם הם \u0003מיני דמים!\u0004","\u0003אלא\u0004 משום כך \u0003איצטריך\u0004 \u0005[נצרך]\u0006 הדבר להיאמר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר],\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והקריבה אל הכהן והגישה אל המזבח וקמץ\"\u0004 (שם), יש ללמוד מכאן: \u0003מה הגשה\u0004 נעשית \u0003בקרן דרומית מערבית\u0004 של המזבח, \u0003אף קמיצה נמי\u0004 \u0005[גם כן]\u0006 תיעשה \u0003בקרן דרומית מערבית\u0004 סמוך למזבח, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שרשאי לקמוץ בכל העזרה.","ודנים \u0003גופא\u0004 \u0005[לגופה]\u0006 של הלכה אחרת שהזכרנו לעיל, \u0003אמר ר' יוחנן: שלמים ששחטן בהיכל\u0004 — \u0003כשרין, שנאמר: \"ושחטו פתח אהל מועד\"\u0004 (שם ג, ב), \u0003ולא יהא טפל חמור מן העיקר,\u0004 שאם החצר \"פתח אוהל מועד\" שהיא עזרה שבמקדש, ראויה לשחיטת קדשים — כל שכן אוהל מועד עצמו, ההיכל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא, \u0003ר' יהודה בן בתירא אומר: מנין שאם הקיפו גוים את העזרה,\u0004 ויורים אבנים וחיצים אל תוכה, ואי אפשר להיות בעזרה מפני הסכנה, \u0003שהכהנים נכנסין להיכל\u0004 שהוא מוגן \u0003ואוכלין\u0004 שם \u0003בקדשי קדשים ושירי מנחות? תלמוד לומר:\u0004"],["\"לכל מנחתם ולכל חטאתם ואשמם וכו' \u0003בקדש הקדשים תאכלנו\"\u0004 (במדבר יח, ט-י), לומר שאף שמצות אכילתם בחצר אוהל מועד, יש מקרים בהם אוכלים קדשי קדשים ומנחות גם בהיכל (קודש הקדשים).","\u0003והא\u0004 \u0005[והרי]\u0006 לפי דברי ר' יוחנן \u0003למה לי קרא\u0004 \u0005[כתוב]\u0006 זה? \u0003לימא\u0004 \u0005[נאמר]\u0006 גם כאן: הלוא נאמר \u0003\"בחצר אהל מועד יאכלוה\"\u0004 (ויקרא ו, ט), כלומר בעזרה, \u0003ולא יהא טפל חמור מן העיקר,\u0004 אם בעזרה אוכלים — כל שכן בהיכל!","ודוחים: אין הדברים דומים, כי שחיטה היא \u0003עבודה,\u0004 ו\u0003אדם עובד\u0004 את רבו (אדונו) לא רק בחצר, אלא גם \u0003במקום\u0004 המיוחד ל\u0003רבו,\u0004 ולכן \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ולומדים בקל וחומר \u0003שלא יהא טפל חמור מן העיקר.\u0004 אבל לגבי \u0003אכילה, שאין אדם אוכל במקום רבו,\u0004 הרי \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 מפני \u0003דכתב קרא\u0004 \u0005[שאמר הכתוב]\u0006 \"בקדש הקדשים תאכלנו\" מותר לאכול בהיכל, \u0003הא לא כתב קרא\u0004 \u0005[אבל אם לא היה אומר הכתוב]\u0006 כן במפורש, לומר \u0003לא יהא טפל חמור מן העיקר לא אמרינן\u0004 \u0005[אין אנו אומרים].\u0006","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה: מנחה \u0003ש\u0004\u0003בללה\u0004 בשמן \u0003חוץ לחומת עזרה, ר' יוחנן אמר: פסולה, ריש לקיש אמר: כשרה.\u0004 ומסבירים את טעמיהם: \u0003ריש לקיש אמר כשרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויצק עליה שמן ונתן עליה לבונה\"\u0004 (שם ב, ב), \u0003והדר\u0004 \u0005[ואחר\u0006 כך\u0005]\u0006 נאמר: \u0003\"והביאה אל בני אהרן הכהנים וקמץ\",\u0004 ודייקו חכמים כי","\u0003מקמיצה ואילך מצות כהונה,\u0004 ובכך \u0003לימד\u0004 הכתוב \u0003על יציקה ובלילה שכשרין בזר. ומ\u0004כיון ש\u0003כהונה לא בעיא\u0004 \u0005[אינה צריכה]\u0006 הבלילה, אף \u0003פנים\u0004 \u0003נמי לא בעיא\u0004 \u0005[גם כן אינה צריכה],\u0006 ואפשר לעשותה חוץ לעזרה.","\u0003ור' יוחנן אמר: פסולה\u0004 היא, ש\u0003כיון\u0004 ש\u0003עשייתה בכלי\u0004 שרת \u0003הוא, נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003כהונה לא בעיא\u0004 \u0005[אינה צריכה],\u0006 אבל \u0003פנים מיהת בעיא\u0004 \u0005[על כל פנים צריכה היא].\u0006 ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן:\u0004 מנחה ש\u0003בללה זר\u0004 — \u0003כשרה,\u0004 נבללה \u0003חוץ לחומת העזרה\u0004 — \u0003פסולה.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: \u0003מנחה שחסרה קודם קמיצה, ר' יוחנן אמר: יביא מתוך ביתו\u0004 סולת נוספת \u0003וימלאנה, ריש לקיש אמר: לא יביא מתוך ביתו וימלאנה,\u0004 אלא יביא מנחה חדשה.","ומסבירים את טעמיהם: \u0003ר' יוחנן אמר מביא מתוך ביתו וימלאנה,\u0004 כי ה\u0003קמיצה קבעה ליה\u0004 \u0005[קובעת אותה]\u0006 כמנחה גמורה להיפסל, וכל עוד לא נקמצה יש לה תקנה. ואילו \u0003ריש לקיש אמר: לא יביא מתוך ביתו וימלאנה,\u0004 כי \u0003קדושת כלי קבעה ליה\u0004 \u0005[קובעת אותה]\u0006 כמנחה, משעה שנכנסה בכלי שרת ונתקדשה, ולכן אם חסרה נפסלה, ואין לה עוד תקנה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש,\u0004 הרי שנינו לענין לוג שמן שמביא המצורע: \u0003חסר הלוג, אם עד שלא יצק\u0004 ממנו הכהן לכפו כדי ליתן על בהונות המצורע — \u0003ימלאנו,\u0004 ואין אומרים שקדושת הכלי קובעת כדי לפוסלו בחסרון! ומעירים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003שירים\u0004 של מנחה \u0003שחסרו בין קמיצה להקטרה,\u0004 שכבר קמץ את הקומץ ועדיין לא הקטיר אותו, \u0003ר' יוחנן אמר: מקטיר קומץ עליהן\u0004 על השיריים, כדי להתירם באכילה, \u0003וריש לקיש אמר: אין מקטיר קומץ עליהן.\u0004 ומעירים: \u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' אליעזר כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 \u0003כי פליגי\u0004 \u0005[כאשר הם חלוקים]\u0006 הרי זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003ר' יהושע.\u0004","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003נטמאו שיריה\u0004 של המנחה, או \u0003נשרפו שיריה\u0004 או \u0003אבדו שיריה, כמדת\u0004 (לפי שיטת) \u0003ר' אליעזר\u0004 — \u0003כשרה\u0004 המנחה, \u0003כמדת ר' יהושע\u0004 — \u0003פסולה;\u0004","\u0003מאן דפסל\u0004 \u0005[מי שפוסל,\u0006 ריש לקיש\u0005]\u0006 סבור בפשטות \u0003כ\u0004דעת \u0003ר' יהושע, ומאן דמכשר\u0004 \u0005[ומי שמכשיר,\u0006 ר' יוחנן\u0005]\u0006 אומר כך: \u0003עד כאן לא\u0004 שמענו ש\u0003אמר ר' יהושע התם\u0004 \u0005[שם]\u0006 שהיא פסולה \u0003אלא\u0004 במקרה ש\u0003לא אישתייר\u0004 \u0005[נשתייר]\u0006 דבר מן המנחה, שהואיל ומטרת הקומץ להתיר את השיריים, הרי אם אין שיריים — אין הקטרה, \u0003אבל היכא דאישתייר\u0004 \u0005[במקום שנשתייר]\u0006 חלק מן השיריים — \u0003אפילו ר' יהושע מודה ליה\u0004 \u0005[לו]\u0006 לר' אליעזר שהיא כשרה.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לענין זבחים, \u0003ר' יהושע אומר: כל הזבחים שבתורה שנשתייר מהם כזית בשר או כזית חלב\u0004 — הרי זה \u0003זורק\u0004 את \u0003הדם,\u0004 כדי להתיר את הבשר באכילה או את החלב בהקרבה. אבל אם נשאר רק \u0003כחצי זית בשר\u0004 או \u0003כחצי זית חלב\u0004 — \u0003אינו זורק את הדם,\u0004 שאין אכילה או הקטרה בפחות מכזית, ואין החצאים מצטרפים.","\u0003ובעולה, אפילו\u0004 נשתייר ממנה \u0003כחצי זית בשר וכחצי זית חלב\u0004 — \u0003זורק את הדם, מפני שבעולה כולה כליל,\u0004 שגם הבשר וגם החלב מוקטרים על המזבח, וביחד יש כאן הקטרה בכזית. \u0003ובמנחה, אף על פי שכולה קיימת\u0004 — \u0003לא יזרוק.\u0004"],["ותוהים: \u0003מנחה מאי עבידתה\u0004 \u0005[מה מעשיה]\u0006 כאן? הרי כאן מדובר בזבחים! \u0003אמר רב פפא:\u0004 הכוונה היא ל\u0003מנחת נסכים\u0004 הבאה עם הזבח,","\u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ובהדי זבח אתיא\u0004 — \u0003כי גופיה דזבח דמיא\u0004 \u0005[כיון שביחד עם הזבח היא באה\u0006 — \u0005כמו גופו של הזבח היא נחשבת],\u0006 ואם נשארה מנחת נסכים הרי זה כאילו \u0003נשאר משהו מן הזבח, ויזרוק את הדם למרות שלא נשאר מן הבשר והחלב, על כן\u0004 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינו כן. על כל פנים, מברייתא זו בענין זבח מוכיח ר' יוחנן, שגם לדעת ר' יהושע, אם נותרו חלק מן השיריים מקטיר עליהם את הקומץ.","ושואלים: \u0003ומאן דפסל\u0004 \u0005[ומי שפוסל]\u0006 במקרה שחסרו חלק מן השיריים, כלומר, ריש לקיש, מה הוא סבור? ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 הדין במנחה, \u0003דאמר קרא\u0004 \u0005[שאומר הכתוב]:\u0006 \u0003\"והרים הכהן מן המנחה את אזכרתה והקטיר המזבחה\"\u0004 (ויקרא ב, ט), ומה \u0003שנאמר \"מן\u0004 \u0003המנחה\",\u0004 שהוא מיותר לכאורה, שהרי במנחה הכתוב עוסק, הרי זה בא לומר: \u0003עד דאיתא לכולה\u0004 \u0005[שישנה כל]\u0006 ה\u0003מנחה לא יקטיר.\u0004","\u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוחנן\u0005]\u0006 כיצד הוא דורש? \u0003\"מן המנחה\"\u0004 כוונתו \u0003מנחה שהיתה כבר,\u0004 כלומר, זו שהיתה \u0003שלימה בשעת קמיצה יקטיר, אף על גב דהשתא\u0004 \u0005[אף על פי שעכשיו]\u0006 \u0003אינה שלימה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו בברייתא: אם \u0003עד שלא פרקה\u0004 את המערכת של לחם הפנים \u0003נפרס\u0004 \u0003הלחם\u0004 — \u0003פסול, ואין מקטיר עליו את הבזיכין, ואם משפרקה נפרס לחמה\u0004 — \u0003הלחם\u0004 אמנם \u0003פסול,\u0004 אבל \u0003מקטיר עליו את הבזיכין. ואמר ר' אלעזר: לא\u0004 מש \u0003פרקה ממש, אלא כיון שהגיע זמנה לפרק ואף על פי שלא פירקה.\u0004 הרי שמקטירים את הקומץ (הבזיכים) למרות שהלחם נפרס ופסול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אליעזר היא,\u0004 המתיר להקטיר את הקומץ למרות שאבדו השיריים, אבל אני הולך כדעת ר' יהושע הפוסל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אנא אמינא\u0004 \u0005[אני אומר]\u0006 \u0003לך משנה שלימה,\u0004 כלומר, ברייתא השנויה בסתם, שיש להניח שהיא כדעת הכל, \u0003ואמרת לי את\u0004 \u0005[ואתה אומר לי]\u0006 שזו שיטת יחיד של \u0003ר' אליעזר?\u0004","ועוד, \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' אליעזר\u0004 היא, \u0003מאי איריא\u0004 \u0005[מדוע דווקא]\u0006 נוקט דין \u0003נפרס\u0004 הלחם? \u0003אפילו שרוף ואבוד נמי מכשר\u0004 \u0005[גם כן היה מכשיר]!\u0006 \u0003אישתיק\u0004 \u0005[שתק]\u0006 ריש לקיש, שלא היה לו מה להשיב.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 \u0003שתק? לימא ליה\u0004 \u0005[שיאמר לו]\u0006 לר' יוחנן: אין להוכיח מלחם הפנים שהוא קרבן ציבור, לסתם מנחה, שכן \u0003צבור שאני\u0004 \u0005[שונה],\u0006 \u0003הואיל ואישתרי\u0004 \u0005[והותרה]\u0006 \u0003טומאה לגבייהו\u0004 \u0005[לגביהם],\u0006 שקרבנות הציבור קרבים אפילו בטומאה — \u0003אישתרי נמי\u0004 \u0005[הותרו גם כן]\u0006 מנחות \u0003חסרות! אמר רב אדא בר אהבה:\u0004 מה שלא השיב לו כך, \u0003זאת אומרת,\u0004 ש\u0003החסרון\u0004 במנחות \u0003כבעל מום דמי\u0004 \u0005[נחשב],\u0006 \u0003ו\u0004הרי \u0003אין בעל מום\u0004 כשר להקרבה אפילו \u0003בצבור.\u0004","מסופר, \u0003יתיב\u0004 \u0005[יושב]\u0006 היה \u0003רב פפא וקאמר להא שמעתא\u0004 \u0005[ואומר את השמועה הזו],\u0006 שריש לקיש שתק, ולא השיב לר' יוחנן שקרבן ציבור שונה, ומכאן דייק רב אדא בר אהבה שהחסרון כבעל מום. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף בר\u0004 \u0005[בן]\u0006 \u0003שמעיה לרב פפא: מי לא עסקינן\u0004 \u0005[האם אין אנו עוסקים]\u0006 במחלוקת \u0003ר' יוחנן וריש לקיש\u0004 אפילו \u0003במנחת העומר\u0004 של \u0003צבור היא? ו\u0004בכל זאת \u0003פליגי\u0004 \u0005[חלוקים\u0006 בה\u0005],\u0006 ולפיכך לא היה כל מקום שיעלה ריש לקיש טענה זו, ואין ללמוד מכאן דבר. ושבים לעיקר המחלוקת בין ר' יוחנן וריש לקיש.","\u0003אמר רב מלכיו, תנא חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 נאמר \"וקמץ... \u0003מסלתה\"\u0004 (ויקרא ב, ב) — ללמד \u0003שאם חסרה כל שהוא\u0004 מן הסולת שהיתה בה \u0003פסולה,\u0004 ואינו יכול לקמוץ, וכן \u0003\"משמנה\"\u0004 (שם) — \u0003שאם חסרה כל שהוא\u0004 מן השמן שהיה בה — \u0003פסול.\u0004","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 נאמר \u0003\"והנותרת מן המנחה\u0004 לאהרן ולבניו\" (שם ג) — מן המנחה שהיתה בתחילה, \u0003פרט למנחה שחסרה היא, ושחסר קומצה, ושלא הקטיר מלבונתה כלום,\u0004 שהיא פסולה ואינה נאכלת לכהנים.","ויש לשאול: \u0003תרי קראי\u0004 \u0005[שני מקראות]\u0006 \u0003בחסרות למה לי?\u0004 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 בא \u0003למנחה שחסרה קודם קמיצה,\u0004 לומר שנפסלה ואינו יכול לחזור ולמלאה, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003ל\u0004גבי \u0003שירים שחסרו בין קמיצה להקטרה,\u0004 שאינו יכול להקטיר קומץ עליהם?","\u0003ו\u0004אם כן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003ר' יוחנן בתרוייהו\u0004 \u0005[בשניהם],\u0006 בשתי ההלכות שנחלק עם ריש לקיש, גם לענין מנחה שחסרה קודם קמיצה, שלדעתו יכול להביא סולת מביתו ולמלאה, וגם לענין שיריים שחסרו לאחר קמיצה, שלדעתו מקטיר עליהם את הקומץ!","ודוחים: \u0003לא,\u0004 צריכים לומר כך: \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 בא \u0003למנחה שחסרה קודם קמיצה,\u0004 אבל לא לפוסלה לגמרי, אלא לומר \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מביא מביתו וימלאנה\u0004 עד שתהיה שלימה — \u0003אין\u0004 \u0005[כן]\u0006 כשרה, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 מביא — \u0003לא,\u0004 והרי היא פסולה. \u0003וחד\u0004 \u0005[\u0006ופסוק \u0005אחד]\u0006 הוא \u0003לשירים שחסרו בין קמיצה להקטרה,\u0004 אבל לא לפסול את הקומץ, אלא לומר \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003מקטיר קומץ עליהן\u0004 — \u0003אותן שירים אסורים לאכילה.\u0004","\u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003לדברי האומר שירים שחסרו בין קמיצה להקטרה מקטיר קומץ עליהן, אותן שירים מה הן באכילה?\u0004","\u0003אמר זעירי, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והנותרת\u0004 מן המנחה לאהרן ולבניו\" (ויקרא ב, ג), כלומר, השיריים שנותרו לאחר הקמיצה ייאכלו לאהרן ולבניו — \u0003ולא הנותרת מן הנותרת,\u0004 שאם חסרו השיריים עצמם, אין הכהנים אוכלים ממה שנותר מהם. \u0003ור' ינאי אמר\u0004 באופן שונה: מה שנאמר \u0003\"מהמנחה\u0004 לאהרן ולבניו\", כוונתו: מן ה\u0003מנחה שהיתה כבר\u0004 בשעת קמיצה.","שנינו במשנה: \u0003קמץ בשמאל\u0004 — פסול. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' זירא, דאמר קרא\u0004 \u0005[שאמר הכתוב]:\u0006 \u0003\"ויקרב את המנחה וימלא כפו ממנה\"\u0004 (ויקרא ט, יז), \u0003כף זה איני יודע מהו,\u0004 ימנית או שמאלית, \u0003כשהוא אומר\u0004 בענין כפרת המצורע: \u0003\"ולקח הכהן מלוג השמן ויצק על כף הכהן השמאלית\"\u0004 (שם יד, טו), הרי זה בא ללמד: דווקא \u0003כאן\u0004 הכף היא \u0003שמאלית, הא\u0004 \u0005[הרי]\u0006 \u0003כל מקום שנאמר\u0004 סתם \u0003כף אינו אלא ימין.\u0004 ושואלים: וכיצד אתה למד מכתוב זה?","\u0003והא מיבעי ליה לגופיה\u0004 \u0005[והרי צריך אותו לגופו,\u0006 לעצמו\u0005]\u0006 לומר שיוצק על הכף השמאלית ולא על הימנית! ומשיבים: \u0003\"שמאלית\" אחרינא כתיב\u0004 \u0005[אחרת כתוב]\u0006 באותו ענין (שם טז), ומשם אנו למדים.","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]\u0006 ודרוש כך: \u0003אין מיעוט אחר מיעוט\u0004 בא \u0003אלא לרבות,\u0004 לומר שיכול ליצוק גם על כף הכהן הימנית! ומשיבים: עוד \u0003\"שמאלית\" אחרינא כתיב\u0004 \u0005[אחרת כתוב]\u0006 בפרשת המצורע העני (שם כו), לומר שאין דורשים כאן מיעוט אחר מיעוט, אלא שיש ללמוד: \u0003כאן שמאלית ואין אחר שמאלית.\u0004","ומקשים, \u0003ואימא\u0004 \u0005[ואמור]:\u0006 \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003מה כאן שמאלית\u0004 — \u0003אף בעלמא נמי\u0004 \u0005[בכלל גם כן]\u0006 \u0003שמאלית\u0004 ולא ימנית! ומשיבים: \u0003ארבעה \"שמאלית\" כתיבי\u0004 \u0005[כתובים],\u0006 \u0003תרי\u0004 \u0005[שנים]\u0006 מהם כתובים \u0003ב\u0004מצורע \u0003עני\u0004 (שם כו ושם כז) \u0003ותרי\u0004 \u0005[ושנים]\u0006 כתובים \u0003בעשיר\u0004 (שם טו ושם טז), ויש לדרוש שלושה מהן לכפי שהסברנו, והפעם הרביעית מלמדת שאין לומר להיפך: מה כאן כף שמאלית — אף בכל מקום שמאלית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא:\u0004 אם כך, שאתה מניח כי יש לדרוש כל ייתור מעין זה בפרשיות המצורע, אם כן \u0003\"על בהן ידו הימנית ועל בהן רגלו הימנית\" דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003ב\u0004נתינת ה\u0003שמן\u0004 על בהונות \u0003מצורע עשיר\u0004 (שם יז), \u0003למה לי?\u0004"],["\u0003דהא כתב\u0004 \u0005[שהרי נאמר]\u0006 שם שצריך ליתנו \u0003\"על דם האשם\"\u0004 (ויקרא יד, יז), וכבר נאמר שדם האשם ניתן על הבהן הימנית (שם יד)! וכן במצורע עני, לשם מה הוצרך לומר \"על בהן ידו הימנית ועל בהן רגלו הימנית\" (שם כח), והרי נאמר \"על מקום דם האשם\"! ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 שנזכר בעשיר בא \u0003להכשיר צדדין,\u0004 לא רק על גב הבהן (במקום הצפורן), אלא גם בצד הבהן, \u0003וחד\u0004 \u0005[ואחד]\u0006 שנזכר בעני — \u0003לפסול צידי צדדין,\u0004 החלק הפנימי של הבהן.","ושואלים: ומה שנאמר \u0003\"על דם האשם\"\u0004 (שם יז) במצורע עשיר, ו\u0003\"על מקום דם האשם\"\u0004 במצורע עני (שם כח), \u0003למאי אתו\u0004 \u0005[למה באו]?\u0006 למה הוצרכו שניהם?","ומשיבים: \u0003הני צריכי\u0004 \u0005[אלה נצרכים],\u0006 שכן \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 רק \u0003\"על דם האשם\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 אם \u0003איתיה\u0004 \u0005[ישנו]\u0006 הדם על הכהן — \u0003אין\u0004 \u0005[כן],\u0006 יתן את השמן, אבל אם \u0003נתקנח\u0004 משם — \u0003לא,\u0004 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"על מקום\u0004 דם האשם\", ולאו דווקא על הדם עצמו.","\u0003ואי כתב רחמנא\u0004 \u0005[ואם היתה כותבת התורה]\u0006 רק \u0003\"על מקום\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003דוקא\u0004 כאשר \u0003נתקנח\u0004 הדם יתן על מקומו את השמן, \u0003אבל איתיה\u0004 \u0005[\u0006אם הדם \u0005ישנו]\u0006 — \u0003אימא הוי\u0004 \u0005[אמור שהוא]\u0006 מהוה \u0003חציצה\u0004 בין השמן לבהן, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 \u0003\"על דם האשם\"\u0004 שאין דם זה נחשב לחציצה.","\u0003אמר רבא: מאחר דכתיב\u0004 \u0005[שנאמר]\u0006 שצריך הכהן לתת מן השמן \u0003\"על דם האשם\" ו\"על מקום\u0004 דם \u0003האשם\", וכתיבא\u0004 \u0005[ו\u0006כבר \u0005נכתבה]\u0006 \u0003ימנית בדם\u0004 במצורע עשיר (שם יד) ובמצורע עני (שם כה), אם מה שנאמר בשמן \u0003\"על בהן ידו הימנית ועל בהן רגלו הימנית\", וכתיבי\u0004 \u0005[ונאמרו]\u0006 דברים אלה גם \u0003בשמן\u0004 של \u0003מצורע עשיר\u0004 (שם יז) \u0003ו\u0004גם בזה של \u0003עני\u0004 (שם כח), \u0003למה לי?\u0004","\u0003אלא אמר רבא:\u0004 כתובים יתירים של \"שמאלית\" ו\"ימנית\" שיש בפרשה זו בענין השמן, אינם נדרשים לענין שמאל וימין של המצורע, אלא מופנים הם, ללמד לדינים אחרים בגזירה שווה; מה שנאמר במצורע עשיר \"ידו הימנית\" (שם יז) בא ללמד בגזירה שווה \u0003\"יד\" \"יד\" לקמיצה,\u0004 שנאמר בה \"וימלא כפו ממנה\" (שם ט, יז), שתהא בימין.","ומה שנאמר במצורע עשיר \"רגלו הימנית\" (שם יד, יז) בא ללמד בגזירה שווה \u0003\"רגל\" \"רגל\" לחליצה,\u0004 שנאמר בה \"וחלצה נעלו מעל רגלו\" (דברים כה, ט), לומר שתהא בימין.","וכן מה שנאמר במצורע עשיר \"על תנוך אזן המטהר הימנית\" (ויקרא יד, יז) בא ללמד בגזירה שווה \u0003\"אוזן\" \"אוזן\" לרציעה\u0004 של עבד עברי, שנאמר בה \"ורצע אדוניו את אזנו\" (שמות כא, ו) ללמד שתהא בימין.","ושואלים: מה שנאמר \u0003\"שמאלית\"\u0004 פעם שניה במצורע \u0003(העני)\u0004 עשיר (שם טז), \u0003למאי אתא\u0004 \u0005[למה בא]?\u0006 \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: ליפסול ימין\u0004 של \u0003כהן במצורע, שלא תאמר\u0004 כך: \u0003ומה במקום שלא נתרבתה שמאל,\u0004 כלומר, בכל עבודות הקודש, שפסולות בשמאל — \u0003נתרבתה ימין,\u0004 שהן כשרות בימין, \u0003במקום שנתרבתה שמאל,\u0004 כלומר, במצורע — \u0003אינו דין שנתרבתה\u0004 גם \u0003ימין?\u0004 לכן צריך היה לומר שיוצק לכפו השמאלית — לפסול כף ימין.","ושואלים: \u0003ואידך\u0004 \u0005[ו\u0006הכתובים \u0005האחרים]\u0006 שבעני, \u0003שמאלית\u0004 שחזרה ונזכרה פעמיים נוספות בעני (שם פסוקים כו ו—כז), וכן \u0003יד ורגל ימנית\u0004 של \u0003עני\u0004 (שם פסוקים כה—כט), \u0003למאי אתא\u0004 \u0005[למה בא]?\u0006 ומשיבים: \u0003לכדתנא דבי\u0004 \u0005[לכמו ששנה החכם מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל פרשה שנאמרה ונשנית, לא נשנית\u0004 כולה \u0003אלא בשביל דבר\u0004 אחד \u0003שנתחדש בה,\u0004 ואף כאן לא נאמרה פרשת מצורע עני אלא בשביל הקרבנות השונים שנתחייב בהם, ואין לדרוש את יתור המקראות שבה.","\u0003אמר רבה בר בר חנה, אמר ר' שמעון בן לקיש: כל מקום שנאמרה אצבע וכהונה אינה אלא\u0004 אצבע \u0003ימין.\u0004","ומקדימים: \u0003קא סלקא דעתין\u0004 \u0005[עולה על דעתינו לומר]\u0006 שגם \u0003אצבע ו\u0004גם \u0003כהונה בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו כתובים יחד, כדי לפסול אם עשה בשמאל, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"ולקח הכהן מדם החטאת באצבעו\"\u0004 (ויקרא ד, כה), \u0003וגמר\u0004 \u0005[ולמד]\u0006 שאצבע זו היא ימנית בגזירה שווה \u0003ממצורע, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וטבל הכהן את אצבעו הימנית\"\u0004 (שם יד, טו). ומקשים: \u0003הרי קמיצה דלא כתיבא\u0004 \u0005[שלא כתובה]\u0006 \u0003בה אלא כהונה\u0004 (שם ב, ב) ולא אצבע, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 אם \u0003קמץ בשמאל פסול!\u0004","\u0003אמר רבא,\u0004 צריך לומר: די שייאמר \u0003או אצבע או כהונה\u0004 כדי לפסול בשמאל.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: הרי הולכת אברים לכבש\u0004 כדי להעלותם אחר כך על המזבח, \u0003דכתיב בהו\u0004 \u0005[שנאמר בהם]\u0006 \u0003כהונה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקריב הכהן את הכל המזבחה\"\u0004 (שם א, יג), \u0003ואמר מר\u0004 \u0005[החכם]:\u0006 \u0005הקרבה האמורה כאן\u0006 \u0003זו הולכת אברים לכבש, ותנן\u0004 \u0005[ושנינו\u0006 שם\u0005]:\u0006 כשהיה מוליך את האיברים \u0003הרגל של ימין\u0004 היתה \u0003בשמאל\u0004 של הכהן, \u0003ובית עורה\u0004 צד העור (ולא מקום החיתוך) היה פונה \u0003לחוץ,\u0004 משמע שבהולכה זו אין שמאל פוסלת!","ומשיבים: \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 \u0003או אצבע או כהונה\u0004 — הרי זה \u0003בדבר המעכב כפרה,\u0004 והולכת איברים אינה מעכבת.","ומקשים: \u0003והרי קבלה\u0004 של הדם בכלי, ש\u0003דבר המעכב כפרה הוא, וכתב\u0004 \u0005[וכתובה]\u0006 \u0003בה כהונה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והקריבו בני אהרן הכהנים את הדם\"\u0004 (שם א, ה) \u0003—\u0004 \u0003זו קבלת הדם, ותנן\u0004 \u0005[ושנינו]:\u0006 אם \u0003קבל בשמאל\u0004 — \u0003פסל, ור' שמעון מכשיר,\u0004 למרות שכתובה שם כהונה!","ומשיבים: \u0003ל\u0004דעת \u0003ר' שמעון קאמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003ר' שמעון תרתי בעי\u0004 \u0005[שתים הוא צריך],\u0006 גם \u0005אצבע וגם כהונה, וכאן לא כתובה אצבע. ושואלים:\u0006","\u0003ומי בעי\u0004 \u0005[והאם צריך]\u0006 באמת \u0003ר' שמעון תרתי\u0004 \u0005[שתים]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0003],\u0004 \u0003ר' שמעון אומר: כל מקום שנאמרה יד\u0004 — \u0003אינה אלא\u0004 יד \u0003ימין, אצבע\u0004 — \u0003אינה אלא\u0004 אצבע של יד \u0003ימין!\u0004 ומשיבים: אם כתובה \u0003אצבע לא בעיא\u0004 \u0005[אינה צריכה]\u0006 שתיכתב שם \u0003כהונה,\u0004 אבל אם כתובה \u0003כהונה\u0004 עדיין \u0003בעיא\u0004 \u0005[צריכה]\u0006 שתיכתב \u0003אצבע\u0004 לומר ששמאל פסולה.","ושואלים: \u0003אלא\u0004 הואיל ודי ב\"אצבע\", \u0003כהן\u0004 שנזכר בקבלת דם \u0003למה לי?\u0004 ומשיבים: ללמד שהוא צריך להיות \u0003בכהונו,\u0004 כלומר, כשהוא לבוש בבגדי כהונה."],["\u0003והרי זריקה\u0004 של הדם \u0003דלא כתב ביה\u0004 \u0005[שלא כתובה בו]\u0006 \u0003אלא כהונה, ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003זרק בשמאל\u0004 — \u0003פסול, ולא פליג\u0004 \u0005[ולא\u0006 מצאנו ש\u0005חולק]\u0006 \u0003ר' שמעון\u0004 על כך במשנה! \u0003אמר אביי: פליג\u0004 \u0005[חולק הוא]\u0006 \u0003בברייתא\u0004 על הלכה \u0003זו,\u0004 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קבל\u0004 את דם הקרבן \u0003בשמאל\u0004 — \u0003פסול, ור' שמעון מכשיר; זרק בשמאל\u0004 — \u0003פסול, ור' שמעון מכשיר.\u0004","ושואלים: \u0003ואלא\u0004 לשיטת חכמים שכהונה כשלעצמה משמעה ימין, \u0003הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבא:\u0004 \"ידו הימנית\" שנאמרה במצורע באה ללמד בגזירה שווה \u0003\"יד\" \"יד\" לקמיצה\u0004 שהיא בימין דווקא, \u0003למה לי\u0004 ראיה זו? הרי קמיצה בימין \u0003מכהונה\u0004 שנזכרה בה \u0003נפקא\u0004 \u0005[יוצאת],\u0006 שנאמר \"וקמץ הכהן\" (ויקרא ה, יב)!","ומשיבים: לימוד \u0003חד\u0004 \u0005[אחד]\u0006 נצרך \u0003לקומץ,\u0004 כלומר, לקמיצה, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לקידוש\u0004 ה\u0003קומץ\u0004 בכלי שרת, שצריך ליתנו בתוכו ביד ימין.","ושואלים: \u0003לר' שמעון דלא בעי\u0004 \u0005[שאינו צריך]\u0006 כלל ל\u0003קידוש קומץ\u0004 בכלי, \u0003ולמאן דאמר נמי דבעי\u0004 \u0005[ו\u0006כן \u0005ל\u0006דעת \u0005מי שאומר גם כן שצריך]\u0006 \u0003קידוש קומץ לר' שמעון, ו\u0004מכל מקום \u0003בשמאל אכשורי מכשר\u0004 \u0005[הוא מכשיר],\u0006 אם כן גזירה שווה \u0003\"יד\" \"יד\",\u0004 שממנה לומד \u0003רבא\u0004 קמיצה בימין, \u0003למה לי?\u0004","\u0003אי\u0004 \u0005[אם]\u0006 \u0003לקמיצה גופה\u0004 \u0005[עצמה]\u0006 \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' שמעון,\u0004 הרי \u0003מ\u0004דברי \u0003ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא נפקא\u0004 \u0005[יוצא],\u0006 ש\u0003אמר ר' יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' חייא: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון\u0004 שהכשיר מנחה שנעשתה שלא בכלי שרת? \u0003דאמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"קדש קדשים היא כחטאת וכאשם\"\u0004 (ויקרא ו, י), לומר: אם","\u0003בא לעובדה\u0004 לעשות את עבודות המנחה \u0003ביד\u0004 — \u0003עובדה בימין כ\u0004מו עבודות קרבן \u0003חטאת,\u0004 אם \u0003בא לעובדה בכלי\u0004 שמקדש הקומץ בכלי — \u0003עובדה בשמאל כאשם,\u0004 שעבודתו כשרה בשמאל לדעת ר' שמעון. הרי שקמיצת המנחה בימין נלמדת מן ההיקש לחטאת!","ומסבירים: \u0003לא נצרכא\u0004 גזירה שווה \"יד\" \"יד\" \u0003אלא לקומץ\u0004 של \u0003מנחת חוטא,\u0004 ללמד שגם הוא צריך ימין דווקא, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואמר ר' שמעון\u0004 לגבי מנחת חוטא שאין בה שמן ולבונה כדי \u0003שלא יהא קרבנו מהודר,\u0004 אם כן \u0003כי קמיץ לה נמי\u0004 \u0005[כאשר קומץ אותה גם כן]\u0006 \u0003בשמאל תתכשר\u0004 \u0005[תהיה כשרה],\u0006 למרות שאין זה דרך הידור, על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו]\u0006 שצריך שיהיה בימין דווקא.","שנינו במשנה שאם \u0003קמץ ועלה בידו צרור\u0004 של אבן \u0003או גרגר מלח\u0004"],["\u0003או קורט לבונה\u0004 — \u0003פסול,\u0004 מפני שהקומץ חסר. ושואלים: \u0003כל הני\u0004 \u0005[אלה]\u0006 \u0003למה לי?\u0004 הלוא די היה להביא דוגמה אחת!","ומשיבים: \u0003צריכא\u0004 \u0005[צריך\u0006 הדבר\u0005]\u0006 להיאמר, \u0003דאי תנא\u0004 \u0005[שאילו היה שונה]\u0006 רק \u0003צרור\u0004 של עפר הייתי אומר שהוא מחסר ממידת הקומץ \u0003משום דלאו בת הקרבה היא\u0004 \u0005[שאינו ראוי להקרבה],\u0006 \u0003אבל מלח דבת הקרבה היא\u0004 \u0005[שהוא ראוי להקרבה],\u0006 שהרי נותן מלח על הקומץ קודם שמקטיר אותו — \u0003אימא תתכשר\u0004 \u0005[אמור שתהא כשרה],\u0006 שאינו ממעט ממידת הקומץ,","\u0003ואי תנא\u0004 \u0005[ואם היה שונה]\u0006 \u0003מלח,\u0004 הייתי אומר: המלח ממעט מפני \u0003דלא איקבע בהדי\u0004 \u0005[שלא נקבע עם]\u0006 ה\u0003מנחה מעיקרא\u0004 \u0005[מתחילה],\u0006 \u0003ש\u0004הרי \u0003אינו מולח אלא הקומץ בלבד, אבל לבונה דאיקבע בהדי\u0004 \u0005[שנקבעה יחד]\u0006 עם ה\u0003מנחה מעיקרא\u0004 \u0005[מתחילה],\u0006 שקודם שקומץ נותן עליה לבונה, \u0003אימא תתכשר\u0004 \u0005[אמור שתהא כשרה],\u0006 ולא תמעט ממידת הקומץ, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל אופן פסול.","שנינו במשנה כי אם כשקמץ עלה בידו צרור וכו' פסול \u0003מפני שאמרו: הקומץ החסר או היתר\u0004 — \u0003פסול.\u0004 ושואלים: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003משום חסר ויתר? ותיפוק ליה\u0004 \u0005[ושיצא לו]\u0006 \u0003משום חציצה,\u0004 שהרי הצרור חוצץ בין ידו לבין הקומץ! \u0003אמר ר' ירמיה:\u0004 יש מקרים בהם הצרור אינו נמצא בין ידו לקומץ, אלא \u0003מן הצד,\u0004 כך שאינו חוצץ, ומכל מקום הריהו ממעט בשיעור הקומץ.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרבא: כיצד קומצין?\u0004 כיצד בדיוק עושים את מעשה הקמיצה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כדקמצי אינשי\u0004 \u0005[כמו שקומצים אנשים]\u0006 שמקפלים את כל האצבעות על כף היד. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי, הרי כך אומרים על האצבעות: \u0003זו\u0004 האצבע הקטנה, משמשת למידת ה\u0003זרת\u0004 שבתורה (שמות כח, טז), שהיא מקצה הזרת עד קצה הבהן. \u0003זו\u0004 הסמוכה לה משמשת ל\u0003קמיצה,\u0004 שממנה מתחילה הקמיצה, שמקפל את שלוש האצבעות האמצעיות על כף היד.","זו השלישית משמשת למידת ה\u0003אמה,\u0004 מקצה אצבע זו ועד המרפק. \u0003זו\u0004 הרביעית היא ה\u0003אצבע\u0004 האמורה בתורה, שבה מזים מדם החטאת ועוד. \u0003זו\u0004 החמישית היא ה\u0003גודל\u0004 (בוהן) של המצורע, שנותנים עליה מדם האשם והשמן (ויקרא יד, יז). הרי שאין משתמשים בכל האצבעות לקמיצה!","ומתרצים: אינו משתמש בזרת \u0003אלא\u0004 כדי \u0003להשוות. כלומר, קומץ\u0004 מתחילה \u0003מלא היד כדי שלא יהא חסר, ואחר כך מוחק באצבע קטנה מלמטה\u0004 ובגודל מלמעלה.","ועוד שאלו: \u0003היכי עביד\u0004 \u0005[כיצד עושה]\u0006 את הקמיצה? \u0003אמר רב זוטרא בר טוביה, אמר רב:\u0004 כשמכניס ידו למנחה \u0003חופה שלש אצבעותיו\u0004 האמצעיות \u0003עד שמגיע\u0004 בקצה האצבעות \u0003על פס\u0004 (כף) \u0003ידו ו\u0004כך \u0003קומץ.\u0004","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 נאמר \"וקמץ משם \u0003מלא קמצו\"\u0004 (שם ב, ב) — \u0003יכול מבורץ,\u0004 כלומר, גדוש, שיוצא החוצה? \u0003תלמוד לומר:\u0004 \"והרים ממנו \u0003בקמצו\"\u0004 (שם ו, ח) כלומר, רק מה שנכנס בתוך הקומץ ולא יותר.","\u0003אי\u0004 \u0005[אם]\u0006 \u0003בקמצו, יכול בראשי אצבעותיו\u0004 בלבד, שמקפל את ראשי אצבעותיו, ומה שבתוכן הוא הקומץ? \u0003תלמוד לומר: \"מלא קמצו\",\u0004 צריך להיות מלא ולא רק לקמוץ בו משהו, \u0003הא כיצד\u0004 הוא עושה? \u0003חופה שלש אצבעותיו\u0004 לכל אורכן \u0003על פס\u0004 (כף) \u0003ידו ו\u0004כך \u0003קומץ,\u0004 ו","\u0003ב\u0004מנחת \u0003מחבת וב\u0004מנחת \u0003מרחשת,\u0004 שהן נקמצות לאחר אפייה ויש בהן פתיתים גדולים — \u0003מוחק\u0004 את מה שיצא החוצה \u0003בגודלו מלמעלה ובאצבעו קטנה מלמטה. וזו היא עבודה קשה שבמקדש,\u0004 שצריך למחוק בדיוק מה שיוצא ולא לשייר דבר, וגם שלא יחסר דבר מתוך הקומץ.","ושואלים: \u0003זהו\u0004 זוהי עבודה קשה \u0003ותו לא\u0004 \u0005[ואין יותר]?\u0006 \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003מליקה\u0004 של קרבן העוף, \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003חפינה\u0004 של הקטורת על ידי הכהן הגדול ביום הכיפורים, שעל שתיהן נאמר שהן עבודות קשות שבמקדש! \u0003אלא\u0004 הכוונה היא ש\u0003זו היא אחת מעבודות קשות שבמקדש.\u0004","\u0003אמר רב פפא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004 ש\u0003מלא קמצו\u0004 הוא \u0003כדקמצי אינשי\u0004 \u0005[כמו שקומצים אנשים],\u0006 שמכניס את ידו לסולת כשצידי אצבעותיו כלפי מטה. אבל \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003קמץ בראשי אצבעותיו,\u0004 כלומר, אם היה פס ידו כלפי מטה, והכניס את ראשי אצבעותיו לסולת וכך קמץ, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין?","וכן \u0003מן הצדדין,\u0004 אם הוליך את גב ידו על הסולת עד שנכנסה הסולת לתוכה מן הצד, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? וכן \u0003ממטה למעלה,\u0004 אם היה גב ידו כלפי מטה והכניס את ראשי אצבעותיו לסולת וכך קמץ, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם קמיצה כשרה היא או לא? לשאלות אלו לא נמצאה תשובה ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","כיוצא בזה \u0003אמר רב פפא:\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004 ש\u0003\"מלא חפניו\"\u0004 של חפינת הקטורת על ידי הכהן הגדול ביום הכיפורים (ויקרא טז, יב) הוא \u0003כדחפני אינשי\u0004 \u0005[כמו שחופנים אנשים],\u0006 שמכניס את שתי ידיו כשצידי האצבעות כלפי מטה, וכך מעלה את הקטורת כששתי ידיו מחוברות כעין כלי. אבל \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם \u0003חפן בראשי אצבעותיו\u0004 שהכניס את ראשי אצבעותיו לקטורת וכך חפן, \u0003מהו?\u0004 חפן \u0003מן הצדדין,\u0004 שהוליך גב ידו על הקטורת, ונכנסה הקטורת מן הצד, \u0003מהו? חפן ב\u0004יד \u0003זו וב\u0004יד \u0003זו, ו\u0004לאחר שהגביהן \u0003קרבן זו אצל זו, מהו?\u0004 שאלות אלו לא נמצאה להן תשובה ונשארו ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם כשרצה לקדש את הקומץ בכלי שרת \u0003דבקיה\u0004 \u0005[הדביק]\u0006 את ה\u0003קומץ בדפניה דמנא\u0004 \u0005[בדופן הכלי]\u0006 מתוכו, ולא הניחו בקרקעיתו, \u0003מאי\u0004 \u0005[מה]\u0006 דינו? האם קידוש ב\u0003תוך\u0004 ה\u0003כלי בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והאיכא\u0004 \u0005[והרי יש כאן],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003הנחה בתוכו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]?\u0006 שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003מר בר רב אשי:\u0004 אם \u0003הפכיה למנא\u0004 \u0005[הפך את הכלי],\u0006 \u0003ודבקיה\u0004 \u0005[והדביק]\u0006 את ה\u0003קומץ בארעיתא דמנא\u0004 \u0005[בתחתית הכלי]\u0006 שיש שם בית קיבול, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם \u0003הנחה בתוכו\u0004 של הכלי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003והאיכא\u0004 \u0005[והרי יש כאן],\u0006 שהרי יש תוך לתחתית הכלי, \u0003או דלמא\u0004 \u0005[שמא]\u0006 כלי \u0003כתיקנו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]?\u0006 אף שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003כיצד הוא עושה\u0004 בקמיצה? \u0003פושט את אצבעותיו\u0004 לאורכן \u0003על פס\u0004 (כף) \u0003ידו.\u0004 אם \u0003ריבה שמנה\u0004 של המנחה יותר מן הראוי לה, או \u0003חסר שמנה,\u0004 או \u0003חיסר לבונתה\u0004 — הרי זו \u0003פסולה.\u0004","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003ריבה שמנה? אמר ר' אליעזר: כגון שהפריש לה שני לוגין\u0004 שמן לעשרון סולת, במקום לוג אחד. ומקשים: \u0003ולוקמה\u0004 \u0005[ושיעמיד אותה]\u0006 \u0003כגון דעריב\u0004 \u0005[שעירב]\u0006 \u0003בה שמן\u0004 של \u0003חולין\u0004 או \u0003שמן\u0004 של \u0003חבירתה\u0004 (מנחה אחרת)!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ש\u0003שמן\u0004 של \u0003חולין ושמן\u0004 של \u0003חבירתה לא פסל\u0004 \u0005[אינו פוסל],\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב זוטרא בר טוביה: אלא מעתה\u0004 אם תאמר כך, \u0003מנחת חוטא דפסל\u0004 \u0005[שפוסל]\u0006 \u0003בה שמן\u0004 (להלן מנחות נט,ב) \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006","\u0003אי דידה\u0004 \u0005[אם\u0006 שמן \u0005שלה]\u0006 — \u0003הא לית\u0004 \u0005[הרי אין]\u0006 \u0003לה,\u0004 שהרי אין במנחת חוטא שמן כלל, \u0003אי\u0004 \u0005[אם]\u0006 של \u0003חולין ו\u0004של \u0003חבירתה\u0004 — \u0003הא אמרת\u0004 \u0005[הרי אומר אתה]\u0006 \u0003לא פסל\u0004 \u0005[שאינו פוסל]!\u0006 \u0003ואי אמרת דאפריש לה\u0004 \u0005[ואם תאמר שהפריש\u0006 עבורה\u0005]\u0006 \u0003שמן,\u0004 והוא פוסל למרות שלא עשה כדין, והרי \u0003כיון דלית\u0004 \u0005[שאין]\u0006 \u0003לה שמן כלל\u0004 — \u0003חולין נינהו\u0004 \u0005[הם],\u0006 ואינו נחשב משלה!","ומסבירים, \u0003ור' אליעזר\u0004 שאמר: כגון שהפריש לה שני לוגים, בסגנון \u0003לא מיבעיא קאמר\u0004 \u0005[לא נצרכה הוא אומר],\u0006 וכך יש להבין את דבריו: \u0003לא מיבעיא\u0004 \u0005[לא נצרכה]\u0006 לומר שאם הוסיף לה של \u0003חולין ו\u0004של \u0003חבירתה דפסיל\u0004 \u0005[שהוא פוסל]\u0006 בוודאי את המנחה, \u0003אבל הפריש לה שני לוגין, הואיל ו\u0004מתחילה \u0003האי חזי ליה והאי חזי ליה\u0004 \u0005[זה ראוי לה וזה ראוי לה]\u0006 \u0003אימא לא ליפסיל\u0004 \u0005[אמור שלא יפסול],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שבכל זאת פוסל.","ושואלים: \u0003ומנא ליה\u0004 \u0005[ומנין לו]\u0006 \u0003לר' אליעזר הא\u0004 \u0005[\u0006הלכה \u0005זו]?\u0006 \u0003אמר רבא: מתניתין קשיתיה\u0004 \u0005[המשנה היתה קשה לו],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מה הטעם\u0005]\u0006 \u0003דתני\u0004 \u0005[שהוא שונה]\u0006 \u0003ריבה שמנה,\u0004 כלומר, השמן שלה? \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003ריבה לה שמן! אלא הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003הפריש לה\u0004 מתחילה \u0003שני לוגין\u0004 — אף זה פוסל.","שנינו במשנה: \u0003חיסר לבונתה\u0004 פסול. ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם \u0003חסרה\u0004 הלבונה \u0003ועמדה על קורט\u0004 (גוש קטן) \u0003אחד\u0004 בלבד — \u0003פסולה,\u0004 אם עמדה \u0003על שני\u0004 \u0003קרטין\u0004 — \u0003כשרה, דברי ר' יהודה. ר' שמעון אומר:\u0004 אם עמדה \u0003על קורט אחד\u0004 — \u0003כשרה\u0004 עדיין, \u0003פחות מכאן\u0004 מקורט אחד — \u0003פסולה.\u0004"],["ומתקשים, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון אומר: קומץ ולבונה שחסר כל שהוא\u0004 — \u0003פסול,\u0004 ואין די בקורט אחד! ומתרצים, \u0003תני\u0004 \u0005[שנה]\u0006 כך: \u0003קורט לבונה שחסר כל שהוא\u0004 — \u0003פסול. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 כך\u0005]:\u0006 \u0003כאן בלבונה הבאה עם המנחה,\u0004 שאינה נפסלת גם אם תחסר עד קורט, \u0003כאן בלבונה הבאה בפני עצמה,\u0004 שאם חסרה כל שהוא פסולה.","ובענין זה מביאים מה ש\u0003אמר ר' יצחק בר יוסף, אמר ר' יוחנן: שלש מחלוקת בדבר,\u0004 שיש בענין זה שלוש שיטות חלוקות, \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 \u0003קומץ\u0004 שלם של לבונה \u0003בתחילה,\u0004 כשנותן את הלבונה על המנחה, \u0003וקומץ\u0004 שלם צריך להיות \u0003בסוף,\u0004 בשעת ההקטרה. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003קומץ\u0004 צריך להיות \u0003בתחילה, ושני קרטין\u0004 לפחות \u0003בסוף. ור' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003קומץ\u0004 צריך להיות \u0003בתחילה, וקורט אחד בסוף.\u0004","ומעירים: \u0003ושלשתן מקרא אחד דרשו\u0004 \u0003בדרכים שונות, שנאמר: \"והרים ממנו וכו'\u0004 \u0003ואת כל הלבונה אשר על המנחה\u0004 והקטיר המזבח\" (ויקרא ו, ב), \u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 הכוונה היא שאינו מקטיר \u0003עד דאיתא\u0004 \u0005[שישנה]\u0006 \u0003ללבונה דאיקבעה בהדי\u0004 \u0005[שנקבעה יחד]\u0006 עם ה\u0003מנחה מעיקרא\u0004 \u0005[מתחילה]\u0006 כלומר, קומץ שלם. \u0003ור' יהודה סבר\u0004 \u0005[סבור]:\u0006 כיון שאומר \u0003\"כל\"\u0004 — משמעו כל שהוא, \u0003ואפילו חד קורט\u0004 \u0005[קורט אחד],\u0006 ומה שנאמר \u0003\"את\"\u0004 — הרי זה \u0003לרבות קורט אחר\u0004 נוסף. \u0003ור' שמעון\u0004 סבור כר' יהודה ש\"כל\" משמעו אפילו קורט אחד, ואת המילה \u0003\"את\" לא דריש\u0004 \u0005[אינו דורש]\u0006 לרבות, ולכן די בקורט אחד.","\u0003ואמר ר' יצחק בר יוסף, אמר ר' יוחנן: מחלוקת\u0004 זו היא \u0003בלבונה הבאה עם המנחה, אבל בלבונה הבאה בפני עצמה\u0004 — \u0003דברי הכל,\u0004 גם לדעת ר' יהודה ור' שמעון, \u0003קומץ בתחילה וקומץ בסוף.\u0004 ולשיטתם \u0003להכי איצטריך\u0004 \u0005[לשם כך הוצרך]\u0006 מה שנאמר \u0003\"אשר על המנחה\"\u0004 (שם), ללמדנו שבלבונה \u0003דבהדי\u0004 \u0005[שביחד]\u0006 עם ה\u0003מנחה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יכול להקטיר גם אם נותר קורט או שנים, אבל זו שבאה \u0003בפני עצמה,\u0004 שאינה \"על המנחה\" — \u0003לא. ו\u0004עוד","\u0003אמר ר' יצחק בר יוסף, אמר ר' יוחנן: מחלוקת בלבונה הבאה עם המנחה, אבל בלבונה הבאה בבזיכין\u0004 של לחם הפנים — \u0003דברי הכל,\u0004 כלומר, גם לדעת ר' יהודה ור' שמעון, \u0003שני קמצין\u0004 צריכים להיות \u0003בתחילה,\u0004 קומץ בכל בזך, \u0003ושני קמצין בסוף.\u0004","ומקשים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 שכך הוא\u0005],\u0006 שהרי לא נאמר בה \"כל הלבונה\" להכשיר (לשיטתם) גם בכל שהוא! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דבהדי\u0004 \u0005[שיחד]\u0006 עם \u0003לחם\u0004 הפנים \u0003אתיא\u0004 \u0005[\u0006הלבונה \u0005באה],\u0006 \u0003כ\"\u0004 לבונה \u0003אשר על המנחה\" דמיא\u0004 \u0005[היא נחשבת],\u0006 וגם לגביה יש ללמוד דין זה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין זה כן.","ומעירים: בענין לבונה הבאה בפני עצמה, \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' אמי ור' יצחק נפחא, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מחלוקת\u0004 התנאים, האם לבונה שחסרה עדיין כשרה, היא \u0003בלבונה הבאה עם המנחה, אבל בלבונה הבאה בפני עצמה\u0004 — \u0003דברי הכל קומץ בתחילה וקומץ בסוף, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: כמחלוקת בזו כך מחלוקת בזו.\u0004","שנינו במשנה: \u0003חיסר לבונתה\u0004 — פסולה. ומדייקים מכאן: \u0003הא יתיר\u0004 \u0005[הרי אם ייתר]\u0006 לבונתה — \u0003כשרה.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 אם \u0003יתיר\u0004 — \u0003פסולה! אמר רמי בר חמא:\u0004 מתי היא פסולה — \u0003כגון שהפריש לה שני קמצין\u0004 של לבונה ונתן בה.","\u0003ואמר רמי בר חמא: הפריש לה שני קמצין\u0004 של לבונה, \u0003ואבד אחד מהן קודם קמיצה\u0004 — \u0003לא הוקבעו\u0004 עם המנחה, ואינה פסולה. אם אבד ל\u0003אחר קמיצה\u0004 — כבר \u0003הוקבעו\u0004 עם המנחה, והיא פסולה, מפני שריבה לבונתה.","\u0003ואמר רמי בר חמא: הפריש ארבעה קמצין\u0004 של לבונה \u0003לשני בזיכין\u0004 של לחם הפנים, \u0003ואבדו שנים מהן,\u0004 אם אבדו \u0003קודם סילוק בזיכין\u0004 מעל שולחן לחם הפנים — \u0003לא הוקבעו\u0004 וכשרים, אם \u0003לאחר סילוק בזיכין\u0004 — \u0003הוקבעו,\u0004 ופסולים, מפני שריבה לבונתם.","ועל דין הבזיכים שואלים: \u0003הא תו\u0004 \u0005[זו שוב]\u0006 \u0003למה לי? היינו הך\u0004 \u0005[הרי זה אותו דבר],\u0006 שהרי הקטרת הלבונה מתירה את לחם הפנים, כמו הקטרת הקומץ במנחה, וסילוק הבזיכים של לחם הפנים נחשב כקמיצה של המנחה!","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כיון דבריר\u0004 \u0005[שמבורר]\u0006 ה\u0003קומץ דידה\u0004 \u0005[שלה],\u0006 שבלחם הפנים אין צורך להגדיר מהו ה\"קומץ\", שהרי הלבונה מצויה לעצמה בבזיכים, נאמר כי \u0003כיון שהגיע זמנה לפורקה\u0004 את מערכת לחם הפנים ולסלק את הבזיכים — \u0003כמאן דפריקה דמיא\u0004 \u0005[כמי שמפורקת היא נחשבת],\u0006 ומאותה שעה כבר נקבעה הלבונה עם לחם הפנים, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שכל עוד לא סילק את הבזיכים — לא הוקבעו הקמצים היתירים, ואם אבדו באותה שעה — לחם הפנים כשר.","\u0003הקומץ את המנחה\u0004 על מנת \u0003לאכול שיריה\u0004 של המנחה \u0003בחוץ\u0004 מחוץ לעזרה, \u0003או\u0004 לאכול אפילו \u0003כזית משיריה בחוץ,\u0004 על מנת \u0003להקטיר קומצה בחוץ או כזית\u0004 של \u0003קומצה בחוץ, או להקטיר לבונתה בחוץ\u0004 — הרי בכל אחד מאלה \u0003פסול\u0004 הקומץ והמנחה, \u0003ו\u0004אולם \u0003אין בו כרת\u0004 באכילתו. אבל אם חישב בזמן קמיצה \u0003לאכול שיריה למחר\u0004 לאחר זמנה, \u0003או כזית משיריה למחר, להקטיר קומצה למחר או כזית מקומצה למחר, או להקטיר לבונה למחר\u0004 —"],["הרי זה \u0003פיגול, וחייבין עליו כרת\u0004 על אכילה משיירי המנחה הזו.","\u0003זה הכלל: כל הקומץ [או] נותן\u0004 את הקומץ \u0003בכלי,\u0004 או \u0003המוליך\u0004 את הקומץ בכלי למזבח, או \u0003המקטיר\u0004 את הקומץ על המזבח, אם עשה אחת מעבודות אלו על מנת \u0003לאכול דבר שדרכו לאכול,\u0004 כלומר, השיריים, או על מנת \u0003להקטיר דבר שדרכו להקטיר,\u0004 כלומר, הקומץ או הלבונה, אם עשה על מנת שייאכל או שיקרב \u0003חוץ למקומו\u0004 — הרי זה \u0003פסול\u0004 אבל \u0003אין בו כרת,\u0004 אם על מנת שייעשה כן \u0003חוץ לזמנו\u0004 — \u0003פיגול וחייבין עליו כרת, ובלבד שיקריב\u0004 את \u0003המתיר כמצותו,\u0004 כלומר, שחוץ ממחשבת חוץ לזמנו נעשית עבודת הקומץ, שהיא המתירה את המנחה, כתיקנה. אבל אם לא קרב המתיר כמצוותו, הרי אף שהמנחה פסולה — אין איסור פיגול חל עליה.","\u0003כיצד\u0004 נחשב הדבר ש\u0003קרב המתיר כמצותו?\u0004 אם \u0003קמץ בשתיקה\u0004 (בסתם) ואחר כך \u0003נתן\u0004 את הקומץ \u0003בכלי, והוליך\u0004 \u0003והקטיר\u0004 אותו במחשבת \u0003חוץ לזמנו; או שקמץ חוץ לזמנו,\u0004 ו\u0003נתן בכלי והוליך והקטיר בשתיקה; או שקמץ ונתן בכלי והוליך והקטיר\u0004 במחשבה \u0003חוץ לזמנו\u0004 — \u0003זהו שקרב המתיר כמצותו,\u0004 וחייבים על אכילת המנחה משום פיגול.","\u0003כיצד לא קרב המתיר כמצותו?\u0004 כאשר היתה שם מחשבה נוספת הפוסלת את הקרבן מלבד מחשבת חוץ לזמנו, כגון: אם \u0003קמץ\u0004 במחשבת \u0003חוץ למקומו,\u0004 ואחר כך \u0003נתן בכלי והוליך והקטיר\u0004 במחשבת \u0003חוץ לזמנו; או\u0004 כגון \u0003שקמץ חוץ לזמנו,\u0004 ו\u0003נתן בכלי והוליך והקטיר\u0004 במחשבת \u0003חוץ למקומו; או שקמץ\u0004 ו\u0003נתן בכלי והוליך והקטיר\u0004 במחשבת \u0003חוץ למקומו\u0004 — \u0003זהו\u0004 \u0003שלא קרב המתיר כמצותו.\u0004","וכן \u0003מנחת חוטא ומנחת קנאות שקמצן שלא לשמן\u0004 (ודבר זה פוסלן, כמבואר בראש המסכת) ואחר כך \u0003נתן בכלי והוליך והקטיר\u0004 במחשבת \u0003חוץ לזמנו; או שקמץ\u0004 אותן במחשבת \u0003חוץ לזמנו,\u0004 ואחר כך \u0003נתן\u0004 את הקומץ \u0003בכלי והוליך והקטיר\u0004 במחשבת \u0003שלא לשמן; או שקמץ ונתן בכלי והוליך והקטיר\u0004 במחשבת \u0003שלא לשמן\u0004 — \u0003זהו\u0004 שנקרא \u0003שלא קרב המתיר כמצותו.\u0004","אם עשה אחת מן העבודות על מנת \u0003לאכול כזית בחוץ כזית למחר,\u0004 או \u0003כזית למחר כזית בחוץ,\u0004 וכן אם עשה על מנת לאכול \u0003כחצי זית בחוץ כחצי זית למחר,\u0004 או \u0003כחצי זית למחר כחצי זית בחוץ\u0004 — בכל אחד מהמקרים האלה \u0003פסול ואין בו כרת.\u0004","\u0003אמר ר' יהודה,\u0004 לא כך, אלא \u0003זה הכלל: אם מחשבת הזמן קדמה למחשבת המקום,\u0004 שחישב קודם להקריב או לאכול שלא בזמנו, ואחר כך חישב להקריב שלא במקומו — הרי זה \u0003פיגול וחייבין עליו כרת, אם מחשבת המקום קדמה למחשבת הזמן\u0004 — הרי זה \u0003פסול ואין בו כרת. וחכמים אומרים: זה וזה,\u0004 כל שהיתה עוד מחשבה פסולה מלבד מחשבת חוץ לזמנו, בין בתחילה ובין בסוף — הרי זה \u0003פסול ואין בו כרת.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005],\u0006 \u0003לדברי האומר: שירים\u0004 של מנחה \u0003שחסרו\u0004 שנחסר מהם משהו \u0003בין\u0004 ה\u0003קמיצה ל\u0004בין ה\u0003הקטרה\u0004 של הקומץ, בכל זאת \u0003מקטיר קומץ עליהן; וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 ש\u0003אותן שירים,\u0004 אף על פי שמקטיר את הקומץ עליהם, \u0003אסורים\u0004 הם \u0003באכילה, מהו דתיהני להו\u0004 \u0005[שתועיל להם]\u0006 \u0003הקטרה\u0004 זו \u0003למיקבעינהו\u0004 \u0005[לקבוע אותם]\u0006 \u0003בפיגול\u0004 אם נעשתה במחשבה לאוכלם למחר, כמו אם היו מותרים לאכילה?","\u0003ו\u0004כן מהו שתועיל להם ההקטרה \u0003לפקינהו\u0004 \u0005[להוציא אותם]\u0006 \u0003מידי מעילה?\u0004 האם דינם כשיריים שהותרו באכילה, שלאחר שקרב הקומץ והותרו לכהנים שוב אין בהם דין מעילה?","\u0003אמר רב הונא, אפילו ל\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר: זריקה\u0004 של דם הזבח, שמתירה את בשרו באכילה ומוציאה אותו מדין מעילה, \u0003מועלת\u0004 (מועילה) גם \u0003ל\u0004בשר הזבח ה\u0003יוצא\u0004 מחוץ לעזרה, להוציאו מידי מעילה, למרות שהוא אסור באכילה — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003יוצא,\u0004","\u0003דאיתיה בעיניה\u0004 \u0005[שישנו בעינו],\u0006 \u0003ופסול מחמת דבר אחר הוא,\u0004 שיצא מחוץ לעזרה. \u0003אבל חסרון\u0004 שיש בשיירי המנחה, \u0003דפסולא דגופיה\u0004 \u0005[שפסול של גופו]\u0006 \u0003הוא\u0004 — \u0003לא מהני ליה\u0004 \u0005[לא מועילה לו]\u0006 \u0003הקטרה\u0004 להוציאם מידי מעילה, וגם לא לקבוע אותם בפיגול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אדרבה\u0004 \u0005[להיפך],\u0006 \u0003אפילו ל\u0004דעת \u0003ר' אליעזר\u0004 שחלק על ר' עקיבא ו\u0003אמר: אין זריקה מועלת ליוצא\u0004 להוציאו מידי מעילה — \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא ב\u0003יוצא, דליתיה\u0004 \u0005[שאינו נמצא]\u0006 \u0003בפנים\u0004 כדי שזריקה תועיל לו, \u0003אבל חסרון\u0004 של שיירי המנחה, \u0003דאיתיה\u0004 \u0005[ש\u0006עדיין \u0005נמצא]\u0006 \u0003בפנים\u0004 — \u0003מהניא ליה\u0004 \u0005[מועילה לו]\u0006 \u0003הקטרה\u0004 להוציאם מידי מעילה, ולקבוע אותם בפיגול.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מנין אני אומר אותה],\u0006 שגם על שיריים שחסרו חייבים משום פיגול? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הקומץ את המנחה לאכול שיריה בחוץ או כזית משיריה בחוץ\u0004 וכו' לאכול שייריה למחר או כזית משייריה למחר — פיגול וחייבים עליו כרת, \u0003ותני\u0004 \u0005[ושונה]\u0006 \u0003ר' חייא\u0004 במשנה שלו: \u0003הקומץ את המנחה\u0004 לאכול שייריה, \u0003ולא תני\u0004 \u0005[ואינו שונה]\u0006 \u0003\"או כזית\u0004 משייריה\".","ויש לברר: \u0003מאי טעמא לא תני\u0004 \u0005[מה טעם אינו שונה]\u0006 גם הוא \u0003\"או כזית\"? לאו\u0004 \u0005[האם לא]\u0006 משום שבמשנתנו מדובר \u0003כגון שחסרו שירים וקמו להו\u0004 \u0005[ועמדו להם\u0006\u0005]\u0006 על \u0003כזית. וכיון\u0004 ש\u0003במתן כלי בהילוך ובהקטרה,\u0004 כלומר, כשהוא שונה בהמשך: זה הכלל, כל הקומץ והנותן בכלי והמהלך והמקטיר לאכול את השיריים או להקטיר את הקומץ למחר — פיגול, \u0003לא מתני ליה\u0004 \u0005[לא נשנה לו],\u0006 אינו יכול לשנות:"],["\u0003\"או כזית\"\u0004 על אכילת ה\u0003שירים\u0004 (\"על מנת לאכול כזית משייריה למחר\"), וטעם הדבר, מפני שעל הקטרת הקומץ השנויה עימה לא ניתן לומר \"או להקטיר כזית מקומצה למחר — פיגול\", שהרי אם חסר הקומץ המנחה פסולה, ואין מחשבה כזו עושה פיגול — לפיכך \u0003בקמיצה נמי\u0004 \u0005[גם כן],\u0006 כלומר, כשהוא שונה מתחילה: \"הקומץ את המנחה... \u0003לאכול שירים\" לא תני\u0004 \u0005[אינו שונה]\u0006 ר' חייא \u0003\"או\u0004 לאכול \u0003כזית\u0004 משייריה\", אף שמצד האמת יכול היה לשנות כן; \u0003וקתני סיפא\u0004 \u0005[והוא שונה בסוף],\u0006 שאם הקטיר את הקומץ על מנת לאכול את השיריים לאחר זמנם — הרי זה \u0003פיגול וחייבין עליו כרת, אלמא מהניא להו\u0004 \u0005[מכאן שמועילה להם]\u0006 \u0003הקטרה\u0004 לשיריים שחסרו לקובעם בפיגול!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא,\u0004 מכאן אין להוכיח שמדובר בשיריים שחסרו, ויש להסביר כי \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 ששונה ר' חייא \u0005כשיטת\u0006 \u0005מי היא]?\u0006 שיטת \u0003ר' אלעזר היא, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הקומץ, והלבונה, והקטרת, ומנחת כהנים, ומנחת כהן משיח, ומנחת נסכים, שהקריב מאחת מהן כזית בחוץ\u0004 מחוץ למקדש — הרי זה \u0003חייב\u0004 משום איסור הקרבה בחוץ, \u0003ור' אלעזר פוטר עד שיקריב את כולו,\u0004 ולא רק כזית ממנו.","\u0003ו\u0004\u0003כיון\u0004 ש\u0003בהקטרת קמיצה\u0004 (קומץ) \u0003לא מתני ליה\u0004 \u0005[אינו יכול לשנות]\u0006 את הלשון \u0003\"או\u0004 להקטיר \u0003כזית מקומצה בחוץ\",\u0004 משום שלדעת ר' אלעזר, שאין חייבים על הקטרה כזו בחוץ — גם אין במחשבה לעשות זאת משום פיגול, לכן \u0003בשירים נמי לא מתני ליה\u0004 \u0005[גם כן אינו יכול לשנות]\u0006 \u0003\"או כזית\".\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 ברייתא זו דעת \u0003ר' אלעזר\u0004 היא, \u0003האי\u0004 \u0005[זה]\u0006 שהוא שונה בה \u0003\"להקטיר קומצה\u0004 בחוץ\", הרי \u0003\"להקטיר קומצה ולבונתה\u0004 בחוץ\" \u0003מיבעי ליה\u0004 \u0005[צריך הוא]\u0006 לשנות! \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הקומץ והלבונה שהקריב את אחד מהן בחוץ\u0004 — \u0003חייב\u0004 משום הקרבה בחוץ, \u0003ור' אלעזר פוטר עד שיקריב את שניהם!\u0004","ודוחים: \u0003לא נצרכא\u0004 \u0005[הוצרכה]\u0006 הברייתא לשיטה זו \u0003אלא לקומץ\u0004 של \u0003מנחת חוטא,\u0004 ששם אין לבונה אלא רק קומץ, והוא המתיר היחיד, וממילא חייב על הקרבת הקומץ בפני עצמו בחוץ, וגם מחשבה לעשות כן למחר עושה פיגול.","ושואלים: \u0003ואיכפל תנא לאשמועינן\u0004 \u0005[ו\u0006כי \u0005טרח התנא להשמיע לנו]\u0006 הלכה שנוגעת רק ל\u0003קומץ\u0004 של \u0003מנחת חוטא?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן].\u0006 \u0003וכן כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל \u0003אמר\u0004 בשם האמורא \u0003ר' אלעזר\u0004 בן פדת: מה שנאמר במשנה זו \"על מנת להקריב קומצה בחוץ\" — \u0003קומץ\u0004 של \u0003מנחת חוטא הוא, ו\u0004שיטת \u0003ר' אלעזר היא.\u0004","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לאו מילתא היא דאמרי\u0004 \u0005[לא כלום הוא מה שאמרתי],\u0006 שהקטרה מועילה לשיריים שחסרו, לקבוע אותם בפיגול ולהוציאם מידי מעילה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 נאמר בלחם הפנים: \u0003\"קדש קדשים הוא\"\u0004 (ויקרא כד, ט), לומר: הוא בשלמותו, \u0003שאם נפרסה אחת מהן\u0004 מחלות לחם הפנים, ונחסרה בכך — \u0003חלותיה כולן פסולות\u0004 לגמרי, ואין הקטרת הבזיכים מועילה בהן כלל.","ונדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם לא נפרסה אחת מהן, אלא \u0003יצאת\u0004 (יצאה) — \u0003הני דאיכא גוואי\u0004 \u0005[אלה שישנן בפנים]\u0006 \u0003כשרות.\u0004 ומעתה, \u0003מאן שמעת ליה דאמר\u0004 \u0005[מי\u0006 הוא ש\u0005שמעת אותו שאומר]:\u0006 \u0003זריקה מועלת ליוצא\u0004 מחוץ לעזרה, להוציאו מידי מעילה ולחייב עליו משום פיגול — דעת \u0003ר' עקיבא היא, וקאמר\u0004 \u0005[והוא אומר]\u0006 בברייתא זו שאם \u0003נפרסה\u0004 אחת מן החלות \u0003לא\u0004 מועילה להן ההקטרה. והוא הדין למנחה שחסרו שייריה, שלא תועיל להם ההקטרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 כיצד אתה מוכיח מכאן? \u0003מי קתני\u0004 \u0005[האם\u0006 התנא \u0005שונה\u0006 במפורש\u0005]\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003יצאת\u0004 אחת מהן האחרות כשרות, שאתה מסיק מסקנה זו? \u0003דלמא\u0004 \u0005[שמא]\u0006 יש לדייק באופן אחר: \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003נטמאת\u0004 אחת מהן — \u0003הנך\u0004 \u0005[אלה,\u0006 השאר\u0005]\u0006 הן \u0003כשרות,\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 משום ש\u0003מרצה ציץ\u0004 שבראש הכהן הגדול על הטומאה, \u0003אבל\u0004 אם \u0003יצאת\u0004 אחת מהן — \u0003לא,\u0004 והכל נפסל, כמו שהוא הדין כשנפרסה אחת מהן. \u0003ו\u0004ברייתא זו שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: אין זריקה מועלת ליוצא. ו\u0004לדרך זו,","\u0003בדין הוא דאיבעי ליה למיתני נמי\u0004 \u0005[שצריך לשנות גם כן]\u0006 \u0003יצאת\u0004 אחת מהן כולן פסולות, \u0003והאי דקתני\u0004 \u0005[וזה שהוא שונה]\u0006 \u0003נפרסה\u0004 — \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003אפילו נפרסה, דאיתיה\u0004 \u0005[ש\u0006עדיין היא \u0005נמצאת]\u0006 \u0003בפנים\u0004 — \u0003לא מהניא ליה\u0004 \u0005[מועילה לו]\u0006 \u0003הקטרה. אבל ל\u0004שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר: זריקה מועלת ליוצא\u0004 — \u0003אפילו חסרון נמי מהניא ליה\u0004 \u0005[גם כן מועילה לו]\u0006 \u0003הקטרה.\u0004","אם עשה אחת מעבודות המנחה על מנת \u0003לאכול כחצי זית\u0004 מן השיריים \u0003ולהקטיר כחצי זית\u0004 מן הקומץ למחר — \u0003כשר,\u0004 מפני \u0003שאין אכילה והקטרה מצטרפין.\u0004","ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 אם חישב על מנת \u0003לאכול\u0004 כחצי זית \u0003ולהקטיר\u0004 כחצי זית למחר — אין זה מצטרף, וכשר, \u0003הא\u0004 \u0005[אבל]\u0006 אם חישב על מנת \u0003לאכול\u0004 כחצי זית מן השיריים \u0003ולאכול\u0004 כחצי זית מ\u0003דבר שאין דרכו לאכול,\u0004 כלומר, מן הקומץ — הרי זה \u0003מצטרף\u0004 לכזית לפסול.","ומראים סתירה, \u0003והקתני רישא\u0004 \u0005[והרי\u0006 הוא \u0005שונה בהתחלה,\u0006 במשנה הקודמת\u0005]:\u0006 אם חישב על מנת \u0003לאכול דבר שדרכו לאכול ולהקטיר דבר שדרכו להקטיר\u0004 חוץ לזמנו — הרי זה פיגול, ונדייק: דווקא אם חישב לאכול \u0003דבר שדרכו לאכול\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם חישב לאכול דבר \u0003שאין דרכו לאכול\u0004 — \u0003לא,\u0004 אין מחשבה זו פוסלת, וממילא אין לומר שתצטרף. ואם כן, \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 של משנתנו?","\u0003אמר ר' ירמיה: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: מחשבין מאכילת אדם ל\u0004אכילת \u0003מזבח ומאכילת מזבח ל\u0004אכילת \u0003אדם,\u0004 שאם חישב על מנת להקטיר למחר מן השיריים המיועדים לכהנים, או לאכול מן הקומץ המיועד למזבח — הרי זה פוסל,","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הקומץ את המנחה\u0004 על מנת \u0003לאכול דבר שאין דרכו לאכול\u0004 או \u0003להקטיר דבר שאין דרכו להקטיר\u0004 — הרי זה \u0003כשר, ור' אליעזר פוסל.\u0004","\u0003אביי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 ששיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא משנתנו, \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 ותדייק: \u0003הא\u0004 \u0005[אבל]\u0006 אם חישב על מנת \u0003לאכול\u0004 כחצי זית מדבר שדרכו לאכול \u0003ולאכול\u0004 כחצי זית \u0003דבר שאין דרכו לאכול\u0004 מצטרף לפסול, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 ותדייק כך: \u0003הא\u0004 \u0005[אבל]\u0006 חישב על מנת \u0003לאכול\u0004 כחצי זית למחר \u0003ולאכול\u0004 כחצי זית בחוץ מ\u0003דבר שדרכו לאכול\u0004 הרי זה מצטרף לפסול.","ומקשים: \u0003ומאי קא משמע לן\u0004 \u0005[ומה משמיע לנו\u0006 התנא בכך\u0005]?\u0006 \u0003הא בהדיא קתני לה\u0004 \u0005[הרי במפורש הוא שונה אותה]\u0006 במשנה הקודמת: \u0003לאכול כזית בחוץ וכזית למחר,\u0004 או \u0003כזית למחר וכזית\u0004 \u0003בחוץ, כחצי זית בחוץ וכחצי זית למחר, כחצי זית למחר וכחצי זית בחוץ\u0004 — בכל אלה \u0003פסול ואין בו כרת,\u0004 ואם כן"],["להסברו של אביי, משנתנו ששנינו בה שאין אכילה והקטרה מצטרפים, \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי? אי\u0004 \u0005[אם]\u0006 בשביל לדייק: אבל אם חישב \u0003לאכול\u0004 כחצי זית למחר \u0003ו\u0004שוב חישב \u0003לאכול\u0004 כחצי זית למחר מ\u0003דבר ש(אין) דרכו לאכול קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003מצטרף\u0004 וחייבים על כך משום פיגול — הלוא \u0003מרישא דסיפא שמעת מינה\u0004 \u0005[מתחילתו של סוף\u0006 המשנה הקודמת \u0005שומע אתה],\u0006 \u0003דקתני\u0004 \u0005[שהוא שונה]\u0006 שם: \u0003כחצי זית בחוץ כחצי זית למחר\u0004 — \u0003פסול,\u0004 ונדייק: \u0003הא\u0004 \u0005[אבל]\u0006 לאכול \u0003כחצי זית למחר וכחצי זית למחר\u0004 — \u0003פיגול!\u0004 \u0003אי\u0004 \u0005[אם]\u0006 תאמר שלענין \u0003לאכול ולהקטיר\u0004 כלומר, את הדין \u0003דהיא גופא\u0004 \u0005[של עצמה]\u0006 \u0003קא משמע לן\u0004 \u0005[משמיעה לנו\u0006 המשנה\u0005],\u0006 שמחשבות אכילה והקטרה אינן מצטרפות — הלוא \u0003מדיוקא דרישא שמעת מינה\u0004 \u0005[\u0006\u0005מהדיוק של ההתחלה\u0006 של המשנה הקודמת, \u0005אתה שומע\u0006 דבר \u0005זה],\u0006 ששנינו בה: לאכול דבר שדרכו לאכול הרי זה פיגול, ומכאן יש לדייק: אבל לאכול דבר שאין דרכו לאכול — אין חייבים על כך משום פיגול.","","\u0003דהשתא\u0004 \u0005[שעכשיו,\u0006 שהרי\u0003]\u0004 \u0003מה\u0004 אם כשחישב \u0003לאכול\u0004 דבר שדרכו לאכול \u0003ולאכול דבר שאין דרכו לאכול\u0004 — \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003לא מצטרף,\u0004 למרות שבשתיהן חישב על אכילה, אם חישב \u0003לאכול ולהקטיר מיבעיא\u0004 \u0005[נצרכה לומר]\u0006 שאין מצטרף?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 גם אם שנינו מתחילה שלאכול ולאכול דבר שאין דרכו לאכול אינו מצטרף, עדיין \u0003לאכול ולהקטיר איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך\u0006 לומר\u0005]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 כשמחשב לאכול דבר שאין דרכו לאכול \u0003הוא\u0004 שאינו מצטרף, משום \u0003דלא כי אורחיה קמחשב\u0004 \u0005[שלא כדרכו הוא מחשב],\u0006 שהוא מחשב על דבר שאין דרכו בכך,","\u0003אבל הכא\u0004 \u0005[כאן],\u0006 שמחשב לאכול כחצי זית ולהקטיר כחצי זית, \u0003דבהאי כי אורחיה קמחשב\u0004 \u0005[שבזה כדרכו מחשב]\u0006 \u0003ובהאי כי אורחיה קא מחשב\u0004 \u0005[ובזה הוא כדרכו מחשב]\u0006 \u0003אימא לצטרף\u0004 \u0005[אמור שיצטרפו],\u0006 אף על פי שכל אחד מהם \u0005הוא כחצי זית, על כן\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאינם מצטרפים.","","\u0003הקומץ את המנחה\u0004 על מנת \u0003לאכול שיריה או להקטיר קומצה למחר\u0004 — \u0003מודה ר' יוסי בזה שהוא פיגול וחייבין עליו כרת.\u0004 אבל אם קמץ את המנחה על מנת \u0003להקטיר לבונתה למחר, ר' יוסי אומר: פסול\u0004 הוא, אבל \u0003אין בו כרת, וחכמים אומרים: פיגול וחייבין עליו כרת.\u0004","\u0003אמרו לו\u0004 חכמים לר' יוסי: \u0003מה שינה\u0004 במה שונה דבר \u0003זה מן הזבח,\u0004 שאם שחטו על מנת להקריב אימוריו (החלקים המוקטרים) על המזבח למחר הרי זה פיגול? \u0003אמר להן:\u0004 יש הבדל, \u0003שהזבח דמו ובשרו ואימוריו\u0004 דבר \u0003אחד\u0004 הם, ולכן כשמחשב על כל אחד מהם הרי הוא מפגל, \u0003ו\u0004ה\u0003לבונה אינה מן המנחה.\u0004","ושואלים על סגנון המשנה: \u0003למה לי למיתנא\u0004 \u0005[לשנות]:\u0006 \u0003מודה ר' יוסי בזו?\u0004 די היה לשנות: הקומץ את המנחה לאכול שייריה או להקטיר קומצה למחר — פיגול וחייבים עליו כרת!","ומשיבים, \u0003משום דקא בעי למיתנא סיפא\u0004 \u0005[שהוא רוצה לשנות בסופה\u0006 של המשנה\u0005]:\u0006 \u0003להקטיר לבונתה למחר, ר' יוסי אומר: פסול ואין בו כרת.\u0004","\u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003ר' יוסי\u0004 שאומר כן הוא \u0003משום דקסבר\u0004 \u0005[שהוא סבור]:\u0006 \u0003אין מפגלין בחצי מתיר,\u0004 אם חישב להקטיר חצי מתיר חוץ לזמנו אינו עושה פיגול, והרי המתיר של המנחה הוא גם הקומץ וגם הלבונה, \u0003ו\u0004אם כן \u0003אפילו רישא נמי\u0004 \u0005[בתחילת\u0006 המשנה \u0005גם כן],\u0006 שמחשב בזמן הקמיצה על הקטרת הקומץ למחר — אינו עושה פיגול, הואיל ואינו מחשב גם על הלבונה,"],["\u0003קא משמע לן דבהא\u0004 \u0005[משמיע לנו שבזה]\u0006 הוא \u0003מודה\u0004 שאם קמץ על מנת להקטיר רק את הקומץ למחר הרי זה פיגול, שמפגלים בחצי מתיר, ויש טעם אחר לדבריו, כאשר יבואר להלן.","שנינו במשנה: הקומץ את המנחה על מנת \u0003להקטיר לבונתה למחר, ר' יוסי אומר: פסול ואין בו כרת. אמר ריש לקיש, אומר היה ר' יוסי\u0004 כלומר, זהו טעמו: לפי ש\u0003אין מתיר מפגל את המתיר,\u0004 אם בשעת עבודת מתיר אחד של קרבן, חישב מחשבת חוץ לזמנו במתיר אחר — אין מחשבה זו מועילה לפגל את המנחה.","\u0003וכן אתה אומר בשני\u0004 \u0003בזיכי לבונה של לחם הפנים, שאין מתיר\u0004 אחד \u0003מפגל את המתיר\u0004 השני, ואם הקטיר אחד מהם על מנת להקטיר חבירו למחר — אין מחשבה זו מפגלת.","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003וכן אתה אומר?\u0004 מה נוסף בזה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003טעמא\u0004 \u0005[טעמו]\u0006 של \u0003ר' יוסי\u0004 שאין פיגול מועיל \u0003בלבונה\u0004 — \u0003משום דלאו\u0004 \u0005[שלא]\u0006 \u0003מינה\u0004 של קומץ המנחה \u0003היא, אבל בשני בזיכי לבונה, דמינה דהדדי נינהו\u0004 \u0005[ש\u0006הלבונה \u0005מין של שניהם היא]\u0006 — \u0003אימא מפגלי אהדדי\u0004 \u0005[אמור שמפגלים זה את זה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם במקרה זה אין מתיר מפגל את המתיר.","ומקשים: \u0003ומי מצית אמרת טעמא\u0004 \u0005[והאם יכול אתה לומר שטעמו]\u0006 של \u0003ר' יוסי בלבונה לאו\u0004 \u0005[אינו]\u0006 \u0003משום דלאו\u0004 \u0005[ש\u0006לבונה \u0005לא]\u0006 \u0003מינה\u0004 של ה\u0003מנחה היא? והא קתני סיפא\u0004 \u0005[והרי הוא שונה בסוף],\u0006 \u0003אמרו לו\u0004 חכמים לר' יוסי: \u0003מה שינתה\u0004 זו \u0003מן הזבח\u0004 שאם זרק דמו על מנת להקטיר אימוריו למחר הרי זה פיגול? \u0003אמר להן: הזבח דמו ובשרו ואימוריו אחד, ולבונה אינה מן המנחה,\u0004 משמע שלדעתו אין בזה פיגול משום שהיא מין אחר!","ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 שהלבונה \u0003אינה מן המנחה? אינה בעיכוב מנחה,\u0004 \u0003דלאו כי היכי דמעכב להו\u0004 \u0005[שלא כמו שמעכב]\u0006 ה\u0003קומץ\u0004 את ה\u0003שירים, דכמה דלאו מתקטר\u0004 \u0005[שכל\u0006 זמן \u0005שלא הוקטר]\u0006 ה\u0003קומץ לא מיתאכלי\u0004 \u0005[אין נאכלים]\u0006 ה\u0003שירים, הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003מעכב לה\u0004 הקומץ את ה\u0003לבונה.\u0004 אינו כן, \u0003אלא אי בעי האי מקטר ברישא ואי בעי האי מקטר ברישא\u0004 \u0005[אם רוצה מקטיר את זה,\u0006 הקומץ, \u0005בתחילה ואם רוצה מקטיר את זה,\u0006 הלבונה, \u0005בתחילה],\u0006 ומתוך שאין הקומץ מתיר את הלבונה, אלא הוא מתיר לעצמו — אין הקומץ מפגל בה, שאין מתיר מפגל מתיר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 הסבורים במשנתנו שהקומץ מפגל בלבונה, מה הם סבורים? ומשיבים: \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003אין מתיר מפגל את המתיר, גבי\u0004 \u0005[אצל]\u0006 מה ששנינו: \u0003שחט אחד מן הכבשים\u0004 המתירים את שתי הלחם בעצרת, על מנת \u0003לאכול מחבירו למחר, דאמרת\u0004 \u0005[שאתה אומר]\u0006 ש\u0003שניהם כשרים\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה אמורים]\u0006 \u0003היכא דלא איקבעו בחד מנא\u0004 \u0005[במקום שלא נקבעו\u0006 שני המתירים \u0005בכלי אחד],\u0006 \u0003אבל היכא דאיקבעו בחד מנא\u0004 \u0005[במקום שנקבעו בכלי אחד],\u0006 כגון הקומץ והלבונה — \u0003כחד דמי\u0004 \u0005[כאחד\u0006 הם \u0005נחשבים],\u0006 ומפגלים זה בזה.","ועוד בענין הלבונה, \u0003אמר ר' ינאי: ליקוט לבונה\u0004 מעל המנחה \u0003בזר\u0004 כדי להקטירה — \u0003פסול.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר ר' ירמיה: משום הולכה נגעו בה,\u0004 שליקוט הלבונה נחשב כהולכה של הלבונה כדי להקטירה על המזבח. ואף שאינו מהלך, אלא נוטל את הלבונה בידו ונותנה לכהן, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 ר' ינאי כי \u0003הולכה שלא ברגל שמה הולכה, ו\u0004הרי \u0003הולכה בזר\u0004 — \u0003פסולה.\u0004","\u0003אמר רב מרי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דבר זה במשנה שפירטה את עבודות המנחה שהמחשבה בהם עושה פיגול, \u0003זה הכלל: כל הקומץ ונותן בכלי והמוליך והמקטיר.\u0004","ונברר: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 שה\u0003קומץ\u0004 במנחה \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמו \u0003שוחט\u0004 בזבחים, \u0003מוליך\u0004 את הקומץ להקטירו \u0003נמי היינו\u0004 \u0005[גם כן הרי זה]\u0006 כ\u0003מוליך\u0004 את דם הזבח לזורקו על המזבח, וכן \u0003מקטיר\u0004 את הקומץ והלבונה במנחה \u0003היינו\u0004 \u0005[הרי זה]\u0006 כמו \u0003זורק\u0004 את הדם בזבח, \u0003אלא נותן\u0004 את הקומץ \u0003בכלי מאי קא עביד\u0004 \u0005[מה\u0006 עבודה \u0005הוא עושה]\u0006 בדומה לזבח, שנאמר שהמחשבה מפגלת בו?","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דדמי\u0004 \u0005[שהוא דומה]\u0006 \u0003לקבלה\u0004 של הדם בכלי, \u0003מי דמי\u0004 \u0005[האם הוא דומה]?\u0006 והרי \u0003התם\u0004 \u0005[שם]\u0006 הדם נשפך \u0003ממילא\u0004 \u0005[מאליו]\u0006 לכלי שביד הכהן, ואילו \u0003הכא קא שקיל ורמי\u0004 \u0005[כאן הוא נוטל\u0006 את הקומץ מן המנחה \u0005ונותן\u0006 אותו בכלי\u0005]!\u0006","\u0003אלא משום\u0004 ש\u0003כיון דלא סגיא ליה דלא עבד לה\u0004 \u0005[שאינו יכול\u0006 \u0005שלא לעשות אותה],\u0006 אם כן \u0003עבודה חשובה היא\u0004 — \u0003על כרחיך משוי לה\u0004 \u0005[עושה אותה]\u0006 \u0003כקבלה, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בליקוט הלבונה, \u0003כיון דלא סגיא לה דלא עבד לה\u0004 \u0005[שאינו יכול שלא לעשות אותה],\u0006 אם כן \u0003עבודה חשובה היא\u0004 — \u0003על כרחיך משוי לה\u0004 \u0005[עושה אותה]\u0006 \u0003כי\u0004 \u0005[כמו]\u0006 \u0003הולכה.\u0004","ודוחים: \u0003לא,\u0004 מכאן אין להוכיח לליקוט לבונה. שכן \u0003לעולם\u0004 תפרש לגבי נתינת הקומץ בכלי שהיא מפגלת, מפני \u0003דדמי\u0004 \u0005[שהיא דומה]\u0006 \u0003לקבלה\u0004 של דם הזבח. \u0003ודקא קשיא לך\u0004 \u0005[ו\u0006מה \u0005שקשה לך]:\u0006 והרי \u0003התם ממילא\u0004 \u0005[שם מאליו\u0006 הוא נשפך לכלי\u0005],\u0006 ואילו \u0003הכא קא שקיל ורמי\u0004 \u0005[כאן הוא נוטל ונותן]!\u0006","על כך יש להשיב: \u0003מכדי תרוייהו\u0004 \u0005[הואיל ושניהם]\u0006 ענין של \u0003קדושת כלי הוא,\u0004 שמקדש את המתיר של הקרבן (דם או קומץ) בכלי שרת כדי להקריבו — \u0003מה לי ממילא\u0004 \u0005[מה\u0006 ההבדל \u0005אם\u0006 הדבר \u0005נעשה מאליו],\u0006 \u0003מה לי קא שקיל ורמי\u0004 \u0005[אם\u0006 הוא \u0005נוטל ונותן].\u0006","\u0003שחט שני כבשים\u0004 הבאים עם שתי הלחם בעצרת, על מנת \u0003לאכול אחת מן החלות\u0004 משתי הלחם \u0003למחר,\u0004 או \u0003הקטיר שני בזיכין\u0004 של לבונה של לחם הפנים, על מנת \u0003לאכול אחד מן\u0004 שני \u0003הסדרים\u0004 (המערכות) של הלחם \u0003למחר, ר' יוסי אומר: אותו החלה ואותו הסדר שחישב עליו\u0004 לאוכלו למחר — \u0003פיגול\u0004 הוא \u0003וחייבין עליו כרת\u0004 על אכילתו, \u0003והשני\u0004 רק \u0003פסול ואין בו כרת. וחכמים אומרים: זה וזה פיגול וחייבין עליו כרת.\u0004","\u0003אמר רב הונא: אומר היה ר' יוסי\u0004 כלומר, לשיטתו, לא רק בשתי הלחם מחשבה באחת אינה מפגלת את השניה, אלא אפילו באיברים שונים של בהמה אחת, אם \u0003פיגל בירך של ימין\u0004 ששחט את הזבח על מנת לאכול למחר ירך של ימין — \u0003לא נתפגל הירך של שמאל,\u0004 שאינו חייב כרת על אכילתה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003סברא\u0004 \u0005[סברה\u0006 היא\u0005],\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003קרא\u0004 \u0005[מקרא\u0006 הוא\u0005].\u0006","ומפרטים: \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור סברה]:\u0006 \u0003לא עדיפא מחשבה\u0004 פסולה \u0003ממעשה הטומאה,\u0004 והלוא \u0003אילו איטמי חד אבר\u0004 [אם היה נטמא איבר אחד] \u0003מי איטמי ליה כוליה\u0004 \u0005[האם היה נטמא\u0006 הזבח \u0005כולו]?\u0006 \u0003ואיבעית אימא קרא\u0004 \u0005[ואם תרצה אמור מן המקרא]\u0006, שנאמר בפיגול: \u0003\"והנפש האכלת ממנו עונה תשא\"\u0004 (ויקרא ז, יח), ונדייק מכאן: הנפש האוכלת \u0003ממנו ולא מחבירו.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב נחמן לרב הונא\u0004 ממה ששנינו, \u0003וחכמים אומרים:\u0004 \u0003לעולם אין בו כרת\u0004 בשתי הלחם, \u0003עד שיפגל בשתיהן בכזית\u0004 כלומר, עד שישחוט את הכבשים כדי לאכול כזית אחד משתיהן. ונדייק: אם חישב על כזית \u0003בשתיהן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 יש בזה פיגול, אבל אם חישב על כזית \u0003באחת מהן\u0004 — \u0003לא\u0004 פיגל בחבירתה.","ונברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא רבנן\u0004 \u0005[אם תאמר\u0006 כשיטת \u0005חכמים]\u0006 של משנתנו, הרי לשיטתם \u0003אפילו\u0004 חישב \u0003באחת מהן נמי\u0004 \u0005[גם כן]\u0006 פיגל גם בחבירתה! \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שהיא כשיטת \u0003ר' יוסי\u0004 שאם חישב באחת לא פיגל בחבירתה. ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שלדעת ר' יוסי ירך ימין וירך שמאל \u0003חד גופא\u0004 \u0005[\u0006\u0005כגוף אחד]\u0006 \u0003הוא,\u0004 ואם חישב על אחת מהן פיגל גם בשניה — \u0003משום הכי\u0004 \u0005[כך]\u0006 מובן מדוע בשתי הלחם שאינן גוף אחד, אם חישב על כזית משתיהן ביחד הרי זה \u0003מצטרף.\u0004"]]};
